/* DAWAH X — ahmad, অধ্যায় 77 · খণ্ড 77 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][77]=[[15201,15201,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ الْعَدَوِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يَحْتَكِرُ ‏ ‏إِلَّا ‏ ‏الْأَخَاطُ ‏ ‏وَكَانَ ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏يَحْتَكِرُ ‏ ‏الزَّيْتَ ‏","","",""],[15202,15202,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عُوَيْمِرِ بْنِ أَشْقَرَ ‏ ‏أَنَّهُ ذَبَحَ قَبْلَ أَنْ يَغْدُوَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ ذَلِكَ لَهُ فَأَمَرَهُ أَنْ يُعِيدَ أُضْحِيَّتَهُ ‏","","",""],[15203,15203,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْمُسْتَلِمُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏خُبَيْبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُرِيدُ غَزْوًا أَنَا وَرَجُلٌ مِنْ قَوْمِي وَلَمْ نُسْلِمْ فَقُلْنَا إِنَّا ‏ ‏نَسْتَحْيِي أَنْ يَشْهَدَ قَوْمُنَا مَشْهَدًا لَا نَشْهَدُهُ مَعَهُمْ قَالَ ‏ ‏أَوَ أَسْلَمْتُمَا قُلْنَا لَا قَالَ ‏ ‏فَإِنَّا لَا نَسْتَعِينُ ‏ ‏بِالْمُشْرِكِينَ عَلَى الْمُشْرِكِينَ قَالَ فَأَسْلَمْنَا وَشَهِدْنَا مَعَهُ فَقَتَلْتُ رَجُلًا وَضَرَبَنِي ضَرْبَةً وَتَزَوَّجْتُ بِابْنَتِهِ بَعْدَ ذَلِكَ فَكَانَتْ تَقُولُ لَا عَدِمْتَ رَجُلًا ‏ ‏وَشَّحَكَ ‏ ‏هَذَا ‏ ‏الْوِشَاحَ ‏ ‏فَأَقُولُ لَا عَدِمْتِ رَجُلًا عَجَّلَ أَبَاكِ النَّارَ ‏","","",""],[15204,15204,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ كَعْبِ بْنِ مَالِكٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ طَعَامًا فَلَعِقَ أَصَابِعَهُ ‏","","",""],[15205,15205,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّ جَارِيَةً ‏ ‏لِكَعْبٍ ‏ ‏كَانَتْ ‏ ‏تَرْعَى غَنَمًا لَهُ ‏ ‏بِسَلْعٍ ‏ ‏فَعَدَا الذِّئْبُ عَلَى شَاةٍ مِنْ شَائِهَا فَأَدْرَكَتْهَا الرَّاعِيَةُ ‏ ‏فَذَكَّتْهَا ‏ ‏بِمَرْوَةٍ ‏ ‏فَسَأَلَ ‏ ‏كَعْبُ بْنُ مَالِكٍ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُ بِأَكْلِهَا ‏","","",""],[15206,15206,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏زَمْعَةُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِهِ وَهُوَ مُلَازِمٌ رَجُلًا فِي ‏ ‏أُوقِيَّتَيْنِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلرَّجُلِ هَكَذَا أَيْ ضَعْ عَنْهُ ‏ ‏الشَّطْرَ ‏ ‏قَالَ الرَّجُلُ نَعَمْ يَا رَسُولَ اللَّهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلرَّجُلِ أَدِّ إِلَيْهِ مَا بَقِيَ مِنْ حَقِّهِ ‏","","",""],[15207,15207,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَعْدِ ‏ ‏عَنْ ‏ ‏ابْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَلْعَقُ أَصَابِعَهُ الثَّلَاثَ مِنْ الطَّعَامِ ‏","","",""],[15208,15208,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏جَارِيَةً ‏ ‏لَهُمْ سَوْدَاءَ ‏ ‏ذَكَّتْ ‏ ‏شَاةً لَهُمْ ‏ ‏بِمَرْوَةٍ ‏ ‏فَسَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَأَمَرَهُ بِأَكْلِهَا ‏","","",""],[15209,15209,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَوْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏هُوَ شَكَّ ‏ ‏يَعْنِي ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُؤْمِنِ ‏ ‏كَمَثَلِ ‏ ‏الْخَامَةِ ‏ ‏مِنْ الزَّرْعِ تُقِيمُهَا الرِّيَاحُ تَعْدِلُهَا مَرَّةً وَتَصْرَعُهَا أُخْرَى حَتَّى يَأْتِيَهُ أَجَلُهُ وَمَثَلُ الْكَافِرِ مَثَلُ الْأَرْزَةِ ‏ ‏الْمُجْذِيَةِ ‏ ‏عَلَى أَصْلِهَا لَا يُقِلُّهَا شَيْءٌ حَتَّى يَكُونَ ‏ ‏انْجِعَافُهَا ‏ ‏يَخْتَلِعُهَا ‏ ‏أَوْ ‏ ‏انْجِعَافُهَا ‏ ‏مَرَّةً وَاحِدَةً ‏ ‏شَكَّ ‏ ‏عَبْدُ الرَّحْمَنِ ‏","","",""],[15210,15210,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏لَمَّا تَابَ اللَّهُ عَلَيْهِ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ اللَّهَ لَمْ يُنْجِنِي إِلَّا بِالصِّدْقِ وَإِنَّ مِنْ تَوْبَتِي إِلَى اللَّهِ أَنْ لَا أَكْذِبَ أَبَدًا وَإِنِّي ‏ ‏أَنْخَلِعُ ‏ ‏مِنْ مَالِي ‏ ‏صَدَقَةً ‏ ‏لِلَّهِ تَعَالَى وَرَسُولِهِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْسِكْ عَلَيْكَ بَعْضَ مَالِكَ فَإِنَّهُ خَيْرٌ لَكَ قَالَ فَإِنِّي أُمْسِكُ سَهْمِي مِنْ ‏ ‏خَيْبَرَ ‏","","",""],[15211,15211,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ كَثِيرِ بْنِ أَفْلَحٍ ‏ ‏قَالَ قَالَ ‏ ‏كَعْبُ بْنُ مَالِكٍ ‏ ‏مَا كُنْتُ فِي غَزَاةٍ أَيْسَرَ لِلظَّهْرِ وَالنَّفَقَةِ مِنِّي فِي تِلْكَ الْغَزَاةِ قَالَ لَمَّا خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ أَتَجَهَّزُ غَدًا ثُمَّ أَلْحَقُهُ فَأَخَذْتُ فِي جَهَازِي فَأَمْسَيْتُ وَلَمْ أَفْرُغْ فَقُلْتُ آخُذُ فِي جَهَازِي غَدًا وَالنَّاسُ قَرِيبٌ بَعْدُ ثُمَّ أَلْحَقُهُمْ فَأَمْسَيْتُ وَلَمْ أَفْرُغْ فَلَمَّا كَانَ الْيَوْمُ الثَّالِثُ أَخَذْتُ فِي جَهَازِي فَأَمْسَيْتُ فَلَمْ أَفْرُغْ فَقُلْتُ ‏ ‏أَيْهَاتَ ‏ ‏سَارَ النَّاسُ ثَلَاثًا فَأَقَمْتُ فَلَمَّا قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ النَّاسُ يَعْتَذِرُونَ إِلَيْهِ فَجِئْتُ حَتَّى قُمْتُ بَيْنَ يَدَيْهِ فَقُلْتُ مَا كُنْتُ فِي غَزَاةٍ أَيْسَرَ لِلظَّهْرِ وَالنَّفَقَةِ مِنِّي فِي هَذِهِ الْغَزَاةِ فَأَعْرَضَ عَنِّي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَرَ النَّاسَ أَنْ لَا يُكَلِّمُونَا وَأُمِرَتْ نِسَاؤُنَا أَنْ يَتَحَوَّلْنَ عَنَّا قَالَ فَتَسَوَّرْتُ ‏ ‏حَائِطًا ‏ ‏ذَاتَ يَوْمٍ فَإِذَا أَنَا ‏ ‏بِجَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏فَقُلْتُ أَيْ ‏ ‏جَابِرُ ‏ ‏نَشَدْتُكَ ‏ ‏بِاللَّهِ هَلْ عَلِمْتَنِي غَشَشْتُ اللَّهَ وَرَسُولَهُ يَوْمًا قَطُّ قَالَ فَسَكَتَ عَنِّي فَجَعَلَ لَا يُكَلِّمُنِي قَالَ فَبَيْنَا أَنَا ذَاتَ يَوْمٍ إِذْ سَمِعْتُ رَجُلًا عَلَى ‏ ‏الثَّنِيَّةِ ‏ ‏يَقُولُ ‏ ‏كَعْبًا ‏ ‏كَعْبًا ‏ ‏حَتَّى دَنَا مِنِّي فَقَالَ بَشِّرُوا ‏ ‏كَعْبًا ‏","","",""],[15212,15212,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنِ ‏ ‏ابْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَحَدُ الثَّلَاثَةِ الَّذِينَ تِيبَ عَلَيْهِمْ ‏ ‏أَنَّ ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَدِمَ مِنْ سَفَرٍ ‏ ‏بَدَأَ بِالْمَسْجِدِ فَسَبَّحَ فِيهِ رَكْعَتَيْنِ ثُمَّ سَلَّمَ فَجَلَسَ فِي مُصَلَّاهُ فَيَأْتِيهِ النَّاسُ فَيُسَلِّمُونَ عَلَيْهِ ‏","","",""],[15213,15213,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدِمَ مِنْ غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏ضُحًى فَصَلَّى فِي الْمَسْجِدِ رَكْعَتَيْنِ وَكَانَ إِذَا جَاءَ مِنْ سَفَرٍ فَعَلَ ذَلِكَ ‏","","",""],[15214,15214,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي مِنْ ‏ ‏تَبُوكَ ‏ ‏فَصَلَّى فِي الْمَسْجِدِ رَكْعَتَيْنِ وَكَانَ إِذَا قَدِمَ مِنْ سَفَرٍ فَعَلَ ذَلِكَ ‏","","",""],[15215,15215,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏وَعَنْ ‏ ‏عَمِّهِ ‏ ‏عُبَيْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقْدَمُ مِنْ سَفَرٍ إِلَّا نَهَارًا فِي الضُّحَى فَإِذَا قَدِمَ بَدَأَ بِالْمَسْجِدِ فَصَلَّى فِيهِ رَكْعَتَيْنِ ثُمَّ جَلَسَ فِيهِ ‏ ‏وَقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏","","",""],[15216,15216,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏أُمُّ مُبَشِّرٍ ‏ ‏لِكَعْبِ بْنِ مَالِكٍ ‏ ‏وَهُوَ ‏ ‏شَاكٍ ‏ ‏اقْرَأْ عَلَى ابْنِي السَّلَامَ تَعْنِي ‏ ‏مُبَشِّرًا ‏ ‏فَقَالَ يَغْفِرُ اللَّهُ لَكِ يَا ‏ ‏أُمَّ مُبَشِّرٍ ‏ ‏أَوَلَمْ تَسْمَعِي مَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا ‏ ‏نَسَمَةُ ‏ ‏الْمُسْلِمِ طَيْرٌ تَعْلُقُ فِي شَجَرِ الْجَنَّةِ حَتَّى يُرْجِعَهَا اللَّهُ عَزَّ وَجَلَّ إِلَى جَسَدِهِ يَوْمَ الْقِيَامَةِ قَالَتْ صَدَقْتَ فَأَسْتَغْفِرُ اللَّهَ ‏","","",""],[15217,15217,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏أَنَّهُ ‏ ‏بَلَغَهُ ‏ ‏أَنَّ ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَسَمَةُ ‏ ‏الْمُؤْمِنِ إِذَا مَاتَ طَائِرٌ يَعْلُقُ بِشَجَرِ الْجَنَّةِ حَتَّى يُرْجِعَهُ اللَّهُ تَبَارَكَ وَتَعَالَى إِلَى جَسَدِهِ يَوْمَ يَبْعَثُهُ اللَّهُ ‏","","",""],[15218,15218,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِدْرِيسَ يَعْنِي الشَّافِعِيَّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ أَخْبَرَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏كَانَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا ‏ ‏نَسَمَةُ ‏ ‏الْمُؤْمِنِ طَائِرٌ يَعْلُقُ فِي شَجَرِ الْجَنَّةِ حَتَّى يُرْجِعَهُ اللَّهُ تَبَارَكَ وَتَعَالَى إِلَى جَسَدِهِ يَوْمَ يَبْعَثُهُ ‏","","",""],[15219,15219,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ يَوْمَ الْخَمِيسِ فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏","","",""],[15220,15220,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا ‏ ‏نَسَمَةُ ‏ ‏الْمُسْلِمِ طَيْرٌ يَعْلُقُ بِشَجَرِ الْجَنَّةِ حَتَّى يُرْجِعَهُ اللَّهُ تَبَارَكَ وَتَعَالَى إِلَى جَسَدِهِ يَوْمَ يَبْعَثُهُ ‏","","",""],[15221,15221,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَلَّ مَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ إِذَا أَرَادَ سَفَرًا إِلَّا يَوْمَ الْخَمِيسِ ‏","","",""],[15222,15222,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ كَعْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَلَّمَا يُرِيدُ غَزْوَةً يَغْزُوهَا إِلَّا ‏ ‏وَرَّى ‏ ‏بِغَيْرِهَا حَتَّى كَانَ غَزْوَةُ ‏ ‏تَبُوكَ ‏ ‏فَغَزَاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَرٍّ شَدِيدٍ اسْتَقْبَلَ سَفَرًا بَعِيدًا ‏ ‏وَمَفَازًا ‏ ‏وَاسْتَقْبَلَ غَزْوَ عَدُوٍّ كَثِيرٍ ‏ ‏فَجَلَا ‏ ‏لِلْمُسْلِمِينَ أَمَرَهُمْ لِيَتَأَهَّبُوا أُهْبَةَ عَدُوِّهِمْ أَخْبَرَهُمْ بِوَجْهِهِ الَّذِي يُرِيدُ ‏","","",""],[15223,15223,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّبَيْدِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُبْعَثُ النَّاسُ يَوْمَ الْقِيَامَةِ فَأَكُونُ أَنَا وَأُمَّتِي عَلَى تَلٍّ وَيَكْسُونِي رَبِّي تَبَارَكَ وَتَعَالَى حُلَّةً خَضْرَاءَ ثُمَّ يُؤْذَنُ لِي فَأَقُولُ مَا شَاءَ اللَّهُ أَنْ أَقُولَ فَذَاكَ الْمَقَامُ الْمَحْمُودُ ‏","","",""],[15224,15224,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ سَعْدِ بْنِ زُرَارَةَ ‏ ‏أَنَّ ‏ ‏ابْنَ كَعْبِ بْنِ مَالِكٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا ذِئْبَانِ جَائِعَانِ أُرْسِلَا فِي غَنَمٍ أَفْسَدَ لَهَا مِنْ حِرْصِ الْمَرْءِ عَلَى الْمَالِ وَالشَّرَفِ لِدِينِهِ ‏","","",""],[15225,15225,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏حِينَ أَنْزَلَ اللَّهُ تَبَارَكَ وَتَعَالَى فِي الشِّعْرِ مَا أَنْزَلَ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَدْ أَنْزَلَ فِي الشِّعْرِ مَا قَدْ عَلِمْتَ وَكَيْفَ ‏ ‏تَرَى فِيهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُؤْمِنَ يُجَاهِدُ بِسَيْفِهِ وَلِسَانِهِ ‏","","",""],[15226,15226,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَنَّ ‏ ‏مَرْوَانَ بْنَ الْحَكَمِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ الْأَسْوَدِ بْنِ عَبْدِ يَغُوثَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أُبَيَّ بْنَ كَعْبٍ الْأَنْصَارِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مِنْ الشِّعْرِ حِكْمَةٌ ‏ ‏وَكَانَ ‏ ‏بَشِيرُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ كَعْبٍ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏كَانَ يُحَدِّثُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ لَكَأَنَّمَا تَنْضَحُونَهُمْ بِالنَّبْلِ فِيمَا تَقُولُونَ لَهُمْ مِنْ الشِّعْرِ ‏","","",""],[15227,15227,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏كَعْبَ بْنَ مَالِكٍ الْأَنْصَارِيَّ ‏ ‏وَهُوَ أَحَدُ الثَّلَاثَةِ الَّذِينَ تِيبَ عَلَيْهِمْ كَانَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا ‏ ‏نَسَمَةُ ‏ ‏الْمُؤْمِنِ طَائِرٌ يَعْلُقُ فِي شَجَرِ الْجَنَّةِ حَتَّى يُرْجِعَهَا اللَّهُ تَبَارَكَ وَتَعَالَى إِلَى جَسَدِهِ يَوْمَ يَبْعَثُهُ ‏","","",""],[15228,15228,"","","‏ ‏حَدَّثَنَا ‏ ‏عَامِرُ بْنُ صَالِحٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يُونُسُ بْنُ يَزِيدَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ كَعْبِ بْنِ مَالِكٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ تَابَ اللَّهُ تَبَارَكَ وَتَعَالَى عَلَيْهِ يَا رَسُولَ اللَّهِ ‏ ‏أَنْخَلِعُ ‏ ‏مِنْ مَالِي ‏ ‏صَدَقَةً ‏ ‏إِلَى اللَّهِ وَرَسُولِهِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْسِكْ عَلَيْكَ بَعْضَ مَالِكَ فَإِنَّهُ خَيْرٌ لَكَ ‏","","",""],[15229,15229,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ‏ ‏الزُّهْرِيِّ ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏مُحَمَّدِ بْنِ مُسْلِمٍ الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ كَعْبِ بْنِ مَالِكٍ ‏ ‏وَكَانَ قَائِدَ ‏ ‏كَعْبٍ ‏ ‏مِنْ بَنِيهِ حِينَ عَمِيَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ حَدِيثَهُ حِينَ تَخَلَّفَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏فَقَالَ ‏ ‏كَعْبُ بْنُ مَالِكٍ ‏ ‏لَمْ أَتَخَلَّفْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةٍ غَيْرِهَا قَطُّ إِلَّا فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏غَيْرَ ‏ ‏أَنِّي كُنْتُ تَخَلَّفْتُ فِي غَزْوَةِ ‏ ‏بَدْرٍ ‏ ‏وَلَمْ يُعَاتِبْ أَحَدًا تَخَلَّفَ عَنْهَا إِنَّمَا خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرِيدُ ‏ ‏عِيرَ ‏ ‏قُرَيْشٍ ‏ ‏حَتَّى جَمَعَ اللَّهُ بَيْنَهُمْ وَبَيْنَ عَدُوِّهِمْ عَلَى غَيْرِ مِيعَادٍ وَلَقَدْ شَهِدْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ ‏ ‏الْعَقَبَةِ ‏ ‏حِينَ تَوَافَقْنَا عَلَى الْإِسْلَامِ مَا أُحِبُّ أَنَّ لِي بِهَا مَشْهَدَ ‏ ‏بَدْرٍ ‏ ‏وَإِنْ كَانَتْ ‏ ‏بَدْرٌ ‏ ‏أَذْكَرَ فِي النَّاسِ مِنْهَا وَأَشْهَرَ وَكَانَ مِنْ خَبَرِي حِينَ تَخَلَّفْتُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏لِأَنِّي لَمْ أَكُنْ قَطُّ أَقْوَى وَلَا أَيْسَرَ مِنِّي حِينَ تَخَلَّفْتُ عَنْهُ فِي تِلْكَ الْغَزَاةِ وَاللَّهِ مَا جَمَعْتُ قَبْلَهَا رَاحِلَتَيْنِ قَطُّ حَتَّى جَمَعْتُهَا فِي تِلْكَ الْغَزَاةِ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَلَّمَا يُرِيدُ غَزَاةً يَغْزُوهَا إِلَّا ‏ ‏وَرَّى ‏ ‏بِغَيْرِهَا حَتَّى كَانَتْ تِلْكَ الْغَزَاةُ فَغَزَاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَرٍّ شَدِيدٍ وَاسْتَقْبَلَ سَفَرًا بَعِيدًا ‏ ‏وَمَفَازًا ‏ ‏وَاسْتَقْبَلَ عَدُوًّا كَثِيرًا ‏ ‏فَجَلَا ‏ ‏لِلْمُسْلِمِينَ أَمْرَهُ ‏ ‏لِيَتَأَهَّبُوا ‏ ‏أُهْبَةَ ‏ ‏عَدُوِّهِمْ فَأَخْبَرَهُمْ بِوَجْهِهِ الَّذِي يُرِيدُ وَالْمُسْلِمُونَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَثِيرٌ لَا يَجْمَعُهُمْ كِتَابُ حَافِظٍ ‏ ‏يُرِيدُ الدِّيوَانَ ‏ ‏فَقَالَ ‏ ‏كَعْبٌ ‏ ‏فَقَلَّ رَجُلٌ يُرِيدُ يَتَغَيَّبُ إِلَّا ظَنَّ أَنَّ ذَلِكَ ‏ ‏سَيُخْفَى لَهُ مَا لَمْ يَنْزِلْ فِيهِ وَحْيٌ مِنْ اللَّهِ عَزَّ وَجَلَّ وَغَزَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِلْكَ الْغَزْوَةَ حِينَ طَابَتْ الثِّمَارُ وَالظِّلُّ وَأَنَا إِلَيْهَا ‏ ‏أَصْعَرُ ‏ ‏فَتَجَهَّزَ إِلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمُؤْمِنُونَ مَعَهُ ‏ ‏وَطَفِقْتُ ‏ ‏أَغْدُو ‏ ‏لِكَيْ أَتَجَهَّزَ مَعَهُ فَأَرْجِعَ وَلَمْ أَقْضِ شَيْئًا فَأَقُولُ فِي نَفْسِي أَنَا قَادِرٌ عَلَى ذَلِكَ إِذَا أَرَدْتُ فَلَمْ يَزَلْ كَذَلِكَ يَتَمَادَى بِي حَتَّى شَمَّرَ بِالنَّاسِ ‏ ‏الْجِدُّ ‏ ‏فَأَصْبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَادِيًا وَالْمُسْلِمُونَ مَعَهُ وَلَمْ أَقْضِ مِنْ جَهَازِي شَيْئًا فَقُلْتُ الْجَهَازُ بَعْدَ يَوْمٍ أَوْ يَوْمَيْنِ ثُمَّ أَلْحَقُهُمْ ‏ ‏فَغَدَوْتُ ‏ ‏بَعْدَ مَا فَصَلُوا لِأَتَجَهَّزَ فَرَجَعْتُ وَلَمْ أَقْضِ شَيْئًا مِنْ جَهَازِي ثُمَّ ‏ ‏غَدَوْتُ ‏ ‏فَرَجَعْتُ وَلَمْ أَقْضِ شَيْئًا فَلَمْ يَزَلْ ذَلِكَ يَتَمَادَى بِي حَتَّى أَسْرَعُوا ‏ ‏وَتَفَارَطَ ‏ ‏الْغَزْوُ فَهَمَمْتُ أَنْ أَرْتَحِلَ فَأُدْرِكَهُمْ وَلَيْتَ أَنِّي فَعَلْتُ ثُمَّ لَمْ يُقَدَّرْ ذَلِكَ لِي ‏ ‏فَطَفِقْتُ ‏ ‏إِذَا خَرَجْتُ فِي النَّاسِ بَعْدَ خُرُوجِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَطُفْتُ فِيهِمْ يَحْزُنُنِي أَنْ لَا أَرَى إِلَّا رَجُلًا ‏ ‏مَغْمُوصًا ‏ ‏عَلَيْهِ فِي النِّفَاقِ أَوْ رَجُلًا مِمَّنْ عَذَرَهُ اللَّهُ وَلَمْ يَذْكُرْنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى بَلَغَ ‏ ‏تَبُوكَ ‏ ‏فَقَالَ وَهُوَ جَالِسٌ فِي الْقَوْمِ ‏ ‏بِتَبُوكَ ‏ ‏مَا فَعَلَ ‏ ‏كَعْبُ بْنُ مَالِكٍ ‏ ‏قَالَ رَجُلٌ مِنْ ‏ ‏بَنِي سَلِمَةَ ‏ ‏حَبَسَهُ يَا رَسُولَ اللَّهِ ‏ ‏بُرْدَاهُ ‏ ‏وَالنَّظَرُ فِي ‏ ‏عِطْفَيْهِ ‏ ‏فَقَالَ لَهُ ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏بِئْسَمَا قُلْتَ وَاللَّهِ يَا رَسُولَ اللَّهِ مَا عَلِمْنَا عَلَيْهِ إِلَّا خَيْرًا فَسَكَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏كَعْبُ بْنُ مَالِكٍ ‏ ‏فَلَمَّا بَلَغَنِي أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ تَوَجَّهَ ‏ ‏قَافِلًا ‏ ‏مِنْ ‏ ‏تَبُوكَ ‏ ‏حَضَرَنِي ‏ ‏بَثِّي ‏ ‏فَطَفِقْتُ ‏ ‏أَتَفَكَّرُ الْكَذِبَ وَأَقُولُ بِمَاذَا أَخْرُجُ مِنْ سَخَطِهِ غَدًا أَسْتَعِينُ عَلَى ذَلِكَ كُلَّ ذِي رَأْيٍ مِنْ أَهْلِي فَلَمَّا قِيلَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ أَظَلَّ قَادِمًا زَاحَ عَنِّي الْبَاطِلُ وَعَرَفْتُ أَنِّي لَنْ أَنْجُوَ مِنْهُ بِشَيْءٍ أَبَدًا فَأَجْمَعْتُ صِدْقَهُ وَصَبَّحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ إِذَا قَدِمَ مِنْ سَفَرٍ بَدَأَ بِالْمَسْجِدِ فَرَكَعَ فِيهِ رَكْعَتَيْنِ ثُمَّ جَلَسَ لِلنَّاسِ فَلَمَّا فَعَلَ ذَلِكَ جَاءَهُ الْمُتَخَلِّفُونَ ‏ ‏فَطَفِقُوا ‏ ‏يَعْتَذِرُونَ إِلَيْهِ وَيَحْلِفُونَ لَهُ وَكَانُوا ‏ ‏بِضْعَةً ‏ ‏وَثَمَانِينَ رَجُلًا فَقَبِلَ مِنْهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَانِيَتَهُمْ وَيَسْتَغْفِرُ لَهُمْ وَيَكِلُ ‏ ‏سَرَائِرَهُمْ ‏ ‏إِلَى اللَّهِ تَبَارَكَ وَتَعَالَى حَتَّى جِئْتُ فَلَمَّا سَلَّمْتُ عَلَيْهِ تَبَسَّمَ تَبَسُّمَ الْمُغْضَبِ ثُمَّ قَالَ لِي تَعَالَ فَجِئْتُ أَمْشِي حَتَّى جَلَسْتُ بَيْنَ يَدَيْهِ فَقَالَ لِي مَا خَلَّفَكَ أَلَمْ تَكُنْ قَدْ اسْتَمَرَّ ظَهْرُكَ قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي لَوْ جَلَسْتُ عِنْدَ غَيْرِكَ مِنْ أَهْلِ الدُّنْيَا لَرَأَيْتُ أَنِّي أَخْرُجُ مِنْ سَخْطَتِهِ بِعُذْرٍ لَقَدْ أُعْطِيتُ ‏ ‏جَدَلًا ‏ ‏وَلَكِنَّهُ وَاللَّهِ لَقَدْ عَلِمْتُ لَئِنْ حَدَّثْتُكَ الْيَوْمَ حَدِيثَ كَذِبٍ ‏ ‏تَرْضَى عَنِّي بِهِ لَيُوشِكَنَّ اللَّهُ تَعَالَى يُسْخِطُكَ عَلَيَّ وَلَئِنْ حَدَّثْتُكَ الْيَوْمَ بِصِدْقٍ تَجِدُ عَلَيَّ فِيهِ إِنِّي لَأَرْجُو ‏ ‏قُرَّةَ ‏ ‏عَيْنِي عَفْوًا مِنْ اللَّهِ تَبَارَكَ وَتَعَالَى وَاللَّهِ مَا كَانَ لِي عُذْرٌ وَاللَّهِ مَا كُنْتُ قَطُّ أَفْرَغَ وَلَا أَيْسَرَ مِنِّي حِينَ تَخَلَّفْتُ عَنْكَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا هَذَا فَقَدْ صَدَقَ فَقُمْ حَتَّى يَقْضِيَ اللَّهُ تَعَالَى فِيكَ ‏ ‏فَقُمْتُ وَبَادَرَتْ رِجَالٌ مِنْ ‏ ‏بَنِي سَلِمَةَ ‏ ‏فَاتَّبَعُونِي فَقَالُوا لِي وَاللَّهِ مَا عَلِمْنَاكَ كُنْتَ أَذْنَبْتَ ذَنْبًا قَبْلَ هَذَا وَلَقَدْ عَجَزْتَ أَنْ لَا تَكُونَ اعْتَذَرْتَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَا اعْتَذَرَ بِهِ الْمُتَخَلِّفُونَ لَقَدْ كَانَ كَافِيَكَ مِنْ ذَنْبِكَ اسْتِغْفَارُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَكَ قَالَ فَوَاللَّهِ مَا زَالُوا يُؤَنِّبُونِي حَتَّى أَرَدْتُ أَنْ أَرْجِعَ فَأُكَذِّبَ نَفْسِي قَالَ ثُمَّ قُلْتُ لَهُمْ هَلْ لَقِيَ هَذَا مَعِي أَحَدٌ قَالُوا نَعَمْ لَقِيَهُ مَعَكَ رَجُلَانِ قَالَا مَا قُلْتَ فَقِيلَ لَهُمَا مِثْلُ مَا قِيلَ لَكَ قَالَ فَقُلْتُ لَهُمْ مَنْ هُمَا قَالُوا ‏ ‏مُرَارَةُ بْنُ الرَّبِيعِ الْعَامِرِيُّ ‏ ‏وَهِلَالُ بْنُ أُمَيَّةَ الْوَاقِفِيُّ ‏ ‏قَالَ فَذَكَرُوا لِي رَجُلَيْنِ صَالِحَيْنِ قَدْ شَهِدَا ‏ ‏بَدْرًا ‏ ‏لِي فِيهِمَا أُسْوَةٌ قَالَ فَمَضَيْتُ حِينَ ذَكَرُوهُمَا لِي قَالَ ‏ ‏وَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُسْلِمِينَ عَنْ كَلَامِنَا أَيُّهَا الثَّلَاثَةُ مِنْ بَيْنِ مَنْ تَخَلَّفَ عَنْهُ فَاجْتَنَبَنَا النَّاسُ قَالَ وَتَغَيَّرُوا لَنَا حَتَّى تَنَكَّرَتْ لِي مِنْ ‏ ‏نَفْسِي الْأَرْضُ فَمَا هِيَ بِالْأَرْضِ الَّتِي كُنْتُ أَعْرِفُ فَلَبِثْنَا عَلَى ذَلِكَ خَمْسِينَ لَيْلَةً فَأَمَّا صَاحِبَايَ فَاسْتَكَانَا وَقَعَدَا فِي بُيُوتِهِمَا يَبْكِيَانِ وَأَمَّا أَنَا فَكُنْتُ أَشَبَّ الْقَوْمِ وَأَجْلَدَهُمْ فَكُنْتُ أَشْهَدُ الصَّلَاةَ مَعَ الْمُسْلِمِينَ وَأَطُوفُ بِالْأَسْوَاقِ وَلَا يُكَلِّمُنِي أَحَدٌ وَآتِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي مَجْلِسِهِ بَعْدَ الصَّلَاةِ فَأُسَلِّمُ عَلَيْهِ فَأَقُولُ فِي نَفْسِي حَرَّكَ شَفَتَيْهِ بِرَدِّ السَّلَامِ أَمْ لَا ثُمَّ أُصَلِّي قَرِيبًا مِنْهُ وَأُسَارِقُهُ النَّظَرَ فَإِذَا أَقْبَلْتُ عَلَى صَلَاتِي نَظَرَ إِلَيَّ فَإِذَا الْتَفَتُّ نَحْوَهُ أَعْرَضَ حَتَّى إِذَا طَالَ عَلَيَّ ذَلِكَ مِنْ هَجْرِ الْمُسْلِمِينَ مَشَيْتُ حَتَّى ‏ ‏تَسَوَّرْتُ ‏ ‏حَائِطَ ‏ ‏أَبِي قَتَادَةَ ‏ ‏وَهُوَ ابْنُ عَمِّي وَأَحَبُّ النَّاسِ إِلَيَّ فَسَلَّمْتُ عَلَيْهِ فَوَاللَّهِ مَا رَدَّ عَلَيَّ السَّلَامَ فَقُلْتُ لَهُ يَا ‏ ‏أَبَا قَتَادَةَ ‏ ‏أَنْشُدُكَ ‏ ‏اللَّهَ هَلْ تَعْلَمُ أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ قَالَ فَسَكَتَ قَالَ فَعُدْتُ ‏ ‏فَنَشَدْتُهُ ‏ ‏فَسَكَتَ فَعُدْتُ ‏ ‏فَنَشَدْتُهُ ‏ ‏فَقَالَ اللَّهُ وَرَسُولُهُ أَعْلَمُ فَفَاضَتْ عَيْنَايَ ‏ ‏وَتَوَلَّيْتُ ‏ ‏حَتَّى ‏ ‏تَسَوَّرْتُ ‏ ‏الْجِدَارَ فَبَيْنَمَا أَنَا أَمْشِي بِسُوقِ ‏ ‏الْمَدِينَةِ ‏ ‏إِذَا ‏ ‏نَبَطِيٌّ ‏ ‏مِنْ ‏ ‏أَنْبَاطِ ‏ ‏أَهْلِ ‏ ‏الشَّامِ ‏ ‏مِمَّنْ قَدِمَ بِطَعَامٍ يَبِيعُهُ ‏ ‏بِالْمَدِينَةِ ‏ ‏يَقُولُ مَنْ يَدُلُّنِي عَلَى ‏ ‏كَعْبِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏فَطَفِقَ ‏ ‏النَّاسُ يُشِيرُونَ لَهُ إِلَيَّ حَتَّى جَاءَ فَدَفَعَ إِلَيَّ كِتَابًا مِنْ مَلِكِ ‏ ‏غَسَّانَ ‏ ‏وَكُنْتُ كَاتِبًا فَإِذَا فِيهِ أَمَّا بَعْدُ فَقَدْ بَلَغَنَا أَنَّ صَاحِبَكَ قَدْ جَفَاكَ وَلَمْ يَجْعَلْكَ اللَّهُ بِدَارِ هَوَانٍ وَلَا مَضْيَعَةٍ فَالْحَقْ بِنَا نُوَاسِكَ قَالَ فَقُلْتُ حِينَ قَرَأْتُهَا وَهَذَا أَيْضًا مِنْ الْبَلَاءِ قَالَ ‏ ‏فَتَيَمَّمْتُ ‏ ‏بِهَا ‏ ‏التَّنُّورَ ‏ ‏فَسَجَرْتُهُ ‏ ‏بِهَا حَتَّى إِذَا مَضَتْ أَرْبَعُونَ لَيْلَةً مِنْ الْخَمْسِينَ إِذَا بِرَسُولِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِينِي فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُكَ أَنْ تَعْتَزِلَ امْرَأَتَكَ قَالَ فَقُلْتُ أُطَلِّقُهَا أَمْ مَاذَا أَفْعَلُ قَالَ بَلْ اعْتَزِلْهَا فَلَا تَقْرَبْهَا قَالَ وَأَرْسَلَ إِلَى صَاحِبَيَّ بِمِثْلِ ذَلِكَ قَالَ فَقُلْتُ لِامْرَأَتِي الْحَقِي بِأَهْلِكِ فَكُونِي عِنْدَهُمْ حَتَّى يَقْضِيَ اللَّهُ فِي هَذَا الْأَمْرِ قَالَ فَجَاءَتْ ‏ ‏امْرَأَةُ هِلَالِ بْنِ أُمَيَّةَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ لَهُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏هِلَالًا ‏ ‏شَيْخٌ ‏ ‏ضَائِعٌ ‏ ‏لَيْسَ لَهُ خَادِمٌ فَهَلْ تَكْرَهُ أَنْ أَخْدُمَهُ قَالَ لَا وَلَكِنْ لَا يَقْرَبَنَّكِ قَالَتْ فَإِنَّهُ وَاللَّهِ مَا بِهِ حَرَكَةٌ إِلَى شَيْءٍ وَاللَّهِ مَا يَزَالُ يَبْكِي مِنْ لَدُنْ أَنْ كَانَ مِنْ أَمْرِكَ مَا كَانَ إِلَى يَوْمِهِ هَذَا قَالَ فَقَالَ لِي بَعْضُ أَهْلِي لَوْ اسْتَأْذَنْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي امْرَأَتِكَ فَقَدْ أَذِنَ ‏ ‏لِامْرَأَةِ هِلَالِ بْنِ أُمَيَّةَ ‏ ‏أَنْ تَخْدُمَهُ قَالَ فَقُلْتُ وَاللَّهِ لَا أَسْتَأْذِنُ فِيهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا أَدْرِي مَا يَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَأْذَنْتُهُ وَأَنَا رَجُلٌ شَابٌّ قَالَ فَلَبِثْنَا بَعْدَ ذَلِكَ عَشْرَ لَيَالٍ كَمَالُ خَمْسِينَ لَيْلَةً حِينَ نُهِيَ عَنْ كَلَامِنَا قَالَ ثُمَّ صَلَّيْتُ صَلَاةَ الْفَجْرِ صَبَاحَ خَمْسِينَ لَيْلَةً عَلَى ظَهْرِ بَيْتٍ مِنْ بُيُوتِنَا فَبَيْنَمَا أَنَا جَالِسٌ عَلَى الْحَالِ الَّتِي ذَكَرَ اللَّهُ تَبَارَكَ وَتَعَالَى مِنَّا قَدْ ضَاقَتْ عَلَيَّ نَفْسِي وَضَاقَتْ عَلَيَّ الْأَرْضُ بِمَا ‏ ‏رَحُبَتْ ‏ ‏سَمِعْتُ صَارِخًا ‏ ‏أَوْفَى ‏ ‏عَلَى ‏ ‏جَبَلِ سَلْعٍ ‏ ‏يَقُولُ بِأَعْلَى صَوْتِهِ يَا ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏أَبْشِرْ قَالَ ‏ ‏فَخَرَرْتُ ‏ ‏سَاجِدًا وَعَرَفْتُ أَنْ قَدْ جَاءَ فَرَجٌ وَآذَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِتَوْبَةِ اللَّهِ تَبَارَكَ وَتَعَالَى عَلَيْنَا حِينَ صَلَّى صَلَاةَ الْفَجْرِ فَذَهَبَ النَّاسُ يُبَشِّرُونَنَا وَذَهَبَ قِبَلَ صَاحِبَيَّ يُبَشِّرُونَ وَرَكَضَ إِلَيَّ رَجُلٌ فَرَسًا وَسَعَى سَاعٍ مِنْ ‏ ‏أَسْلَمَ ‏ ‏وَأَوْفَى ‏ ‏الْجَبَلَ فَكَانَ الصَّوْتُ أَسْرَعَ مِنْ الْفَرَسِ فَلَمَّا جَاءَنِي الَّذِي سَمِعْتُ صَوْتَهُ ‏ ‏يُبَشِّرُنِي نَزَعْتُ لَهُ ثَوْبَيَّ فَكَسَوْتُهُمَا إِيَّاهُ بِبِشَارَتِهِ وَاللَّهِ مَا أَمْلِكُ غَيْرَهُمَا يَوْمَئِذٍ فَاسْتَعَرْتُ ثَوْبَيْنِ فَلَبِسْتُهُمَا فَانْطَلَقْتُ ‏ ‏أَتَأَمَّمُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَلْقَانِي النَّاسُ فَوْجًا فَوْجًا يُهَنِّئُونِي بِالتَّوْبَةِ يَقُولُونَ ‏ ‏لِيَهْنِكَ تَوْبَةُ اللَّهِ عَلَيْكَ حَتَّى دَخَلْتُ الْمَسْجِدَ فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسٌ فِي الْمَسْجِدِ حَوْلَهُ النَّاسُ فَقَامَ إِلَيَّ ‏ ‏طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏يُهَرْوِلُ ‏ ‏حَتَّى صَافَحَنِي وَهَنَّأَنِي وَاللَّهِ مَا قَامَ إِلَيَّ رَجُلٌ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏غَيْرَهُ قَالَ فَكَانَ ‏ ‏كَعْبٌ ‏ ‏لَا ‏ ‏يَنْسَاهَا ‏ ‏لِطَلْحَةَ ‏ ‏قَالَ ‏ ‏كَعْبٌ ‏ ‏فَلَمَّا سَلَّمْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَهُوَ يَبْرُقُ وَجْهُهُ مِنْ السُّرُورِ أَبْشِرْ بِخَيْرِ يَوْمٍ مَرَّ عَلَيْكَ مُنْذُ وَلَدَتْكَ أُمُّكَ قَالَ قُلْتُ أَمِنْ عِنْدِكَ يَا رَسُولَ اللَّهِ أَمْ مِنْ عِنْدِ اللَّهِ قَالَ لَا بَلْ مِنْ عِنْدِ اللَّهِ قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سُرَّ اسْتَنَارَ وَجْهُهُ كَأَنَّهُ قِطْعَةُ قَمَرٍ حَتَّى يُعْرَفَ ذَلِكَ مِنْهُ قَالَ فَلَمَّا جَلَسْتُ بَيْنَ يَدَيْهِ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ مِنْ تَوْبَتِي أَنْ ‏ ‏أَنْخَلِعَ ‏ ‏مِنْ مَالِي ‏ ‏صَدَقَةً ‏ ‏إِلَى اللَّهِ تَعَالَى وَإِلَى رَسُولِهِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْسِكْ بَعْضَ مَالِكَ فَهُوَ خَيْرٌ لَكَ قَالَ فَقُلْتُ إِنِّي أُمْسِكُ ‏ ‏سَهْمِي ‏ ‏الَّذِي ‏ ‏بِخَيْبَرَ ‏ ‏قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّمَا اللَّهُ تَعَالَى نَجَّانِي بِالصِّدْقِ وَإِنَّ مِنْ تَوْبَتِي أَنْ لَا أُحَدِّثَ إِلَّا صِدْقًا مَا بَقِيتُ قَالَ فَوَاللَّهِ مَا أَعْلَمُ أَحَدًا مِنْ الْمُسْلِمِينَ ‏ ‏أَبْلَاهُ ‏ ‏اللَّهُ مِنْ الصِّدْقِ فِي الْحَدِيثِ مُذْ ذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْسَنَ مِمَّا أَبْلَانِي اللَّهُ تَبَارَكَ وَتَعَالَى وَاللَّهِ مَا تَعَمَّدْتُ كَذِبَةً مُذْ قُلْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى يَوْمِي هَذَا وَإِنِّي لَأَرْجُو أَنْ يَحْفَظَنِي فِيمَا بَقِيَ قَالَ وَأَنْزَلَ اللَّهُ تَبَارَكَ وَتَعَالَى ‏ { ‏لَقَدْ تَابَ اللَّهُ عَلَى النَّبِيِّ ‏ ‏وَالْمُهَاجِرِينَ ‏ ‏وَالْأَنْصَارِ ‏ ‏الَّذِينَ اتَّبَعُوهُ فِي سَاعَةِ الْعُسْرَةِ مِنْ بَعْدِ مَا كَادَ ‏ ‏يَزِيغُ ‏ ‏قُلُوبُ فَرِيقٍ مِنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُ بِهِمْ رَءُوفٌ رَحِيمٌ وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا حَتَّى إِذَا ضَاقَتْ عَلَيْهِمْ الْأَرْضُ بِمَا ‏ ‏رَحُبَتْ ‏ ‏وَضَاقَتْ عَلَيْهِمْ أَنْفُسُهُمْ وَظَنُّوا أَنْ لَا مَلْجَأَ مِنْ اللَّهِ إِلَّا إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوا إِنَّ اللَّهَ هُوَ التَّوَّابُ الرَّحِيمُ يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ ‏} ‏قَالَ ‏ ‏كَعْبٌ ‏ ‏فَوَاللَّهِ مَا أَنْعَمَ اللَّهُ تَبَارَكَ وَتَعَالَى عَلَيَّ مِنْ نِعْمَةٍ قَطُّ بَعْدَ أَنْ هَدَانِي أَعْظَمَ فِي نَفْسِي مِنْ صِدْقِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ أَنْ لَا أَكُونَ كَذَبْتُهُ فَأَهْلِكُ كَمَا هَلَكَ الَّذِينَ كَذَبُوهُ حِينَ كَذَبُوهُ فَإِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَالَ لِلَّذِينَ كَذَبُوهُ حِينَ كَذَبُوهُ شَرَّ مَا يُقَالُ لِأَحَدٍ فَقَالَ اللَّهُ تَعَالَى ‏ { ‏سَيَحْلِفُونَ بِاللَّهِ لَكُمْ إِذَا انْقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا عَنْهُمْ فَأَعْرِضُوا عَنْهُمْ إِنَّهُمْ ‏ ‏رِجْسٌ ‏ ‏وَمَأْوَاهُمْ جَهَنَّمُ جَزَاءً بِمَا كَانُوا يَكْسِبُونَ يَحْلِفُونَ لَكُمْ لِتَرْضَوْا عَنْهُمْ فَإِنْ تَرْضَوْا عَنْهُمْ فَإِنَّ اللَّهَ لَا ‏ ‏يَرْضَى عَنْ الْقَوْمِ الْفَاسِقِينَ ‏} ‏قَالَ وَكُنَّا خُلِّفْنَا أَيُّهَا الثَّلَاثَةُ عَنْ أَمْرِ أُولَئِكَ الَّذِينَ قَبِلَ مِنْهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ حَلَفُوا فَبَايَعَهُمْ وَاسْتَغْفَرَ لَهُمْ فَأَرْجَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْرَنَا حَتَّى قَضَى اللَّهُ تَعَالَى فَبِذَلِكَ قَالَ اللَّهُ تَعَالَى ‏ { ‏وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا ‏} ‏وَلَيْسَ تَخْلِيفُهُ إِيَّانَا وَإِرْجَاؤُهُ أَمْرَنَا الَّذِي ذَكَرَ مِمَّا خُلِّفْنَا بِتَخَلُّفِنَا عَنْ الْغَزْوِ وَإِنَّمَا هُوَ عَمَّنْ حَلَفَ لَهُ وَاعْتَذَرَ إِلَيْهِ فَقَبِلَ مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ كَعْبِ بْنِ مَالِكٍ ‏ ‏وَكَانَ قَائِدَ ‏ ‏كَعْبٍ ‏ ‏مِنْ بَنِيهِ حِينَ عَمِيَ قَالَ سَمِعْتُ ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ حَدِيثَهُ حِينَ تَخَلَّفَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏قَالَ ‏ ‏كَعْبُ بْنُ مَالِكٍ ‏ ‏لَمْ أَتَخَلَّفْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةٍ غَزَاهَا قَطُّ إِلَّا فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏غَيْرَ أَنِّي كُنْتُ تَخَلَّفْتُ عَنْ غَزْوَةِ ‏ ‏بَدْرٍ ‏ ‏وَلَمْ يُعَاتِبْ أَحَدًا تَخَلَّفَ عَنْهَا لِأَنَّهُ إِنَّمَا خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرِيدُ ‏ ‏الْعِيرَ ‏ ‏الَّتِي كَانَتْ ‏ ‏لِقُرَيْشٍ ‏ ‏كَانَ فِيهَا ‏ ‏أَبُو سُفْيَانَ بْنُ حَرْبٍ ‏ ‏وَنَفَرٌ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏ثُمَّ قَالَ تَعَالَ فَجِئْتُ أَمْشِي حَتَّى جَلَسْتُ بَيْنَ يَدَيْهِ فَقَالَ مَا خَلَّفَكَ أَلَمْ تَكُنْ قَدْ ابْتَعْتَ ‏ ‏ظَهْرَكَ ‏ ‏قُلْتُ بَلَى يَا رَسُولَ اللَّهِ إِنِّي وَاللَّهِ لَوْ جَلَسْتُ عِنْدَ غَيْرِكَ مِنْ أَهْلِ الدُّنْيَا لَرَأَيْتُ ‏ ‏أَنِّي سَأَخْرُجُ مِنْ سَخْطَتِهِ بِعُذْرٍ وَلَقَدْ أُعْطِيتُ ‏ ‏جَدَلًا ‏ ‏فَذَكَرَ الْحَدِيثَ وَقَالَ فِيهِ إِنِّي لَأَرْجُو عَفْوَ اللَّهِ وَقَالَ فَقُلْتُ لِامْرَأَتِي الْحَقِي بِأَهْلِكِ فَكُونِي عِنْدَهُمْ حَتَّى يَقْضِيَ اللَّهُ فِي هَذَا الْأَمْرِ وَقَالَ سَمِعْتُ صَوْتَ صَارِخٍ ‏ ‏أَوْفَى ‏ ‏عَلَى أَعْلَى ‏ ‏جَبَلِ سَلْعٍ ‏ ‏بِأَعْلَى صَوْتِهِ يَا ‏ ‏كَعْبُ بْنَ مَالِكٍ ‏ ‏أَبْشِرْ قَالَ ‏ ‏فَخَرَرْتُ ‏ ‏سَاجِدًا وَعَرَفْتُ أَنَّهُ قَدْ جَاءَ فَرَجٌ وَآذَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسَ بِالتَّوْبَةِ عَلَيْنَا حِينَ صَلَّى صَلَاةَ الْفَجْرِ فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏ابْنِ أَخِي ابْنِ شِهَابٍ ‏ ‏وَقَالَ فِيهِ وَأَقُولُ فِي نَفْسِي هَلْ حَرَّكَ شَفَتَيْهِ بِرَدِّ السَّلَامِ ‏","","",""],[15230,15230,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ الْأَعْرَجُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ كَانَ لَهُ مَالٌ عَلَى ‏ ‏عَبْدِ اللَّهِ أَبِي حَدْرَدٍ الْأَسْلَمِيِّ ‏ ‏فَلَقِيَهُ فَلَزِمَهُ حَتَّى ارْتَفَعَتْ الْأَصْوَاتُ فَمَرَّ بِهِمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏كَعْبُ ‏ ‏فَأَشَارَ بِيَدِهِ كَأَنَّهُ يَقُولُ النِّصْفُ فَأَخَذَ نِصْفًا مِمَّا عَلَيْهِ وَتَرَكَ النِّصْفَ ‏","","",""],[15231,15231,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ الْأَنْصَارِيُّ ‏ ‏أَنَّ ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏كَانَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا ‏ ‏نَسَمَةُ ‏ ‏الْمُؤْمِنِ طَيْرٌ يَعْلُقُ فِي شَجَرِ الْجَنَّةِ حَتَّى يُرْجِعَهُ اللَّهُ تَعَالَى إِلَى جَسَدِهِ يَوْمَ يَبْعَثُهُ ‏","","",""],[15232,15232,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَابِقٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ طَهْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏ابْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ ‏ ‏وَأَوْسُ بْنُ الْحَدَثَانِ ‏ ‏فِي ‏ ‏أَيَّامِ التَّشْرِيقِ ‏ ‏فَنَادَيَا ‏ ‏أَنْ لَا يَدْخُلَ الْجَنَّةَ إِلَّا مُؤْمِنٌ ‏ ‏وَأَيَّامُ التَّشْرِيقِ ‏ ‏أَيَّامُ أَكْلٍ وَشُرْبٍ ‏","","",""],[15233,15233,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏زَكَرِيَّا بْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ سَعْدِ بْنِ زُرَارَةَ ‏ ‏عَنِ ‏ ‏ابْنِ كَعْبِ بْنِ مَالِكٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ذِئْبَانِ جَائِعَانِ أُرْسِلَا فِي غَنَمٍ بِأَفْسَدَ لَهَا مِنْ حِرْصِ الْمَرْءِ عَلَى الْمَالِ وَالشَّرَفِ لِدِينِهِ ‏","","",""],[15234,15234,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُوسَى بْنُ جُبَيْرٍ ‏ ‏مَوْلَى ‏ ‏بَنِي سَلِمَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ كَعْبِ بْنِ مَالِكٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ النَّاسُ فِي رَمَضَانَ إِذَا صَامَ الرَّجُلُ فَأَمْسَى فَنَامَ حَرُمَ عَلَيْهِ الطَّعَامُ وَالشَّرَابُ وَالنِّسَاءُ حَتَّى يُفْطِرَ مِنْ الْغَدِ فَرَجَعَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏مِنْ عِنْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ وَقَدْ سَهِرَ عِنْدَهُ فَوَجَدَ امْرَأَتَهُ قَدْ نَامَتْ فَأَرَادَهَا فَقَالَتْ إِنِّي قَدْ نِمْتُ قَالَ مَا نِمْتِ ثُمَّ وَقَعَ بِهَا وَصَنَعَ ‏ ‏كَعْبُ بْنُ مَالِكٍ ‏ ‏مِثْلَ ذَلِكَ فَغَدَا ‏ ‏عُمَرُ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏عَلِمَ اللَّهُ أَنَّكُمْ كُنْتُمْ تَخْتَانُونَ أَنْفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنْكُمْ ‏}","","",""],[15235,15235,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ الدَّرَاوَرْدِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ ‏ ‏ابْنِ أَخِي ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اهْجُوا ‏ ‏بِالشِّعْرِ إِنَّ الْمُؤْمِنَ يُجَاهِدُ بِنَفْسِهِ وَمَالِهِ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ كَأَنَّمَا يَنْضَحُوهُمْ بِالنَّبْلِ ‏","","",""],[15236,15236,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏أَبُو بَكْرِ بْنُ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏عَلَى ‏ ‏عُمَرَ بْنِ الْحَكَمِ بْنِ ثَوْبَانَ ‏ ‏فَقَالَ ‏ ‏يَا ‏ ‏أَبَا حَفْصٍ ‏ ‏حَدِّثْنَا حَدِيثًا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ فِيهِ اخْتِلَافٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏كَعْبُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏عَادَ ‏ ‏مَرِيضًا خَاضَ فِي الرَّحْمَةِ فَإِذَا جَلَسَ عِنْدَهُ اسْتَنْقَعَ فِيهَا وَقَدْ اسْتَنْقَعْتُمْ إِنْ شَاءَ اللَّهُ فِي الرَّحْمَةِ ‏","","",""],[15237,15237,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ فَحَدَّثَنِي ‏ ‏مَعْبَدُ بْنُ كَعْبِ بْنِ مَالِكِ بْنِ أَبِي كَعْبِ بْنِ الْقَيْنِ ‏ ‏أَخُو ‏ ‏بَنِي سَلِمَةَ ‏ ‏أَنَّ ‏ ‏أَخَاهُ ‏ ‏عُبَيْدَ اللَّهِ بْنَ كَعْبٍ ‏ ‏وَكَانَ مِنْ أَعْلَمِ ‏ ‏الْأَنْصَارِ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏وَكَانَ ‏ ‏كَعْبٌ ‏ ‏مِمَّنْ شَهِدَ ‏ ‏الْعَقَبَةَ ‏ ‏وَبَايَعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَا ‏ ‏قَالَ ‏ ‏خَرَجْنَا فِي حُجَّاجِ قَوْمِنَا مِنْ الْمُشْرِكِينَ وَقَدْ صَلَّيْنَا وَفَقِهْنَا وَمَعَنَا ‏ ‏الْبَرَاءُ بْنُ مَعْرُورٍ ‏ ‏كَبِيرُنَا وَسَيِّدُنَا فَلَمَّا تَوَجَّهْنَا لِسَفَرِنَا وَخَرَجْنَا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ ‏ ‏الْبَرَاءُ ‏ ‏لَنَا يَا هَؤُلَاءِ إِنِّي قَدْ رَأَيْتُ وَاللَّهِ رَأْيًا وَإِنِّي وَاللَّهِ مَا أَدْرِي تُوَافِقُونِي عَلَيْهِ أَمْ لَا قَالَ قُلْنَا لَهُ وَمَا ذَاكَ قَالَ قَدْ رَأَيْتُ أَنْ لَا أَدَعَ هَذِهِ الْبَنِيَّةِ مِنِّي بِظَهْرٍ ‏ ‏يَعْنِي ‏ ‏الْكَعْبَةَ ‏ ‏وَأَنْ أُصَلِّيَ إِلَيْهَا قَالَ فَقُلْنَا وَاللَّهِ مَا بَلَغَنَا أَنَّ نَبِيَّنَا ‏ ‏يُصَلِّي إِلَّا إِلَى ‏ ‏الشَّامِ ‏ ‏وَمَا نُرِيدُ أَنْ نُخَالِفَهُ فَقَالَ إِنِّي أُصَلِّي إِلَيْهَا قَالَ فَقُلْنَا لَهُ لَكِنَّا لَا نَفْعَلُ فَكُنَّا إِذَا حَضَرَتْ الصَّلَاةُ صَلَّيْنَا إِلَى ‏ ‏الشَّامِ ‏ ‏وَصَلَّى إِلَى ‏ ‏الْكَعْبَةِ ‏ ‏حَتَّى قَدِمْنَا ‏ ‏مَكَّةَ ‏ ‏قَالَ أَخِي وَقَدْ كُنَّا عِبْنَا عَلَيْهِ مَا صَنَعَ وَأَبَى إِلَّا الْإِقَامَةَ عَلَيْهِ فَلَمَّا قَدِمْنَا ‏ ‏مَكَّةَ ‏ ‏قَالَ يَا ابْنَ أَخِي انْطَلِقْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْأَلْهُ عَمَّا صَنَعْتُ فِي سَفَرِي هَذَا فَإِنَّهُ وَاللَّهِ قَدْ وَقَعَ فِي نَفْسِي مِنْهُ شَيْءٌ لَمَّا رَأَيْتُ مِنْ خِلَافِكُمْ إِيَّايَ فِيهِ قَالَ فَخَرَجْنَا نَسْأَلُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكُنَّا لَا نَعْرِفُهُ لَمْ نَرَهُ قَبْلَ ذَلِكَ فَلَقِيَنَا رَجُلٌ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏فَسَأَلْنَاهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ هَلْ تَعْرِفَانِهِ قَالَ قُلْنَا لَا قَالَ فَهَلْ تَعْرِفَانِ ‏ ‏الْعَبَّاسَ بْنَ عَبْدِ الْمُطَّلِبِ ‏ ‏عَمَّهُ قُلْنَا نَعَمْ قَالَ وَكُنَّا نَعْرِفُ ‏ ‏الْعَبَّاسَ ‏ ‏كَانَ لَا يَزَالُ يَقْدَمُ عَلَيْنَا تَاجِرًا قَالَ فَإِذَا دَخَلْتُمَا الْمَسْجِدَ فَهُوَ الرَّجُلُ الْجَالِسُ مَعَ ‏ ‏الْعَبَّاسِ ‏ ‏قَالَ فَدَخَلْنَا الْمَسْجِدَ فَإِذَا ‏ ‏الْعَبَّاسُ ‏ ‏جَالِسٌ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَهُ جَالِسٌ فَسَلَّمْنَا ثُمَّ جَلَسْنَا إِلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْعَبَّاسِ ‏ ‏هَلْ تَعْرِفُ هَذَيْنِ الرَّجُلَيْنِ يَا ‏ ‏أَبَا الْفَضْلِ ‏ ‏قَالَ نَعَمْ هَذَا ‏ ‏الْبَرَاءُ بْنُ مَعْرُورٍ ‏ ‏سَيِّدُ قَوْمِهِ وَهَذَا ‏ ‏كَعْبُ بْنُ مَالِكٍ ‏ ‏قَالَ فَوَاللَّهِ مَا أَنْسَى قَوْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّاعِرُ قَالَ نَعَمْ قَالَ فَقَالَ ‏ ‏الْبَرَاءُ بْنُ مَعْرُورٍ ‏ ‏يَا نَبِيَّ اللَّهِ إِنِّي خَرَجْتُ فِي سَفَرِي هَذَا وَهَدَانِي اللَّهُ لِلْإِسْلَامِ فَرَأَيْتُ أَنْ لَا أَجْعَلَ هَذِهِ الْبَنِيَّةَ مِنِّي بِظَهْرٍ فَصَلَّيْتُ إِلَيْهَا وَقَدْ خَالَفَنِي أَصْحَابِي فِي ذَلِكَ حَتَّى وَقَعَ فِي نَفْسِي مِنْ ذَلِكَ شَيْءٌ فَمَاذَا ‏ ‏تَرَى يَا رَسُولَ اللَّهِ قَالَ لَقَدْ ‏ ‏كُنْتَ عَلَى قِبْلَةٍ لَوْ صَبَرْتَ عَلَيْهَا قَالَ فَرَجَعَ ‏ ‏الْبَرَاءُ ‏ ‏إِلَى قِبْلَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى مَعَنَا إِلَى ‏ ‏الشَّامِ ‏ ‏قَالَ وَأَهْلُهُ يَزْعُمُونَ أَنَّهُ صَلَّى إِلَى ‏ ‏الْكَعْبَةِ ‏ ‏حَتَّى مَاتَ وَلَيْسَ ذَلِكَ كَمَا قَالُوا نَحْنُ أَعْلَمُ بِهِ مِنْهُمْ قَالَ وَخَرَجْنَا إِلَى الْحَجِّ فَوَاعَدْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَقَبَةَ ‏ ‏مِنْ أَوْسَطِ ‏ ‏أَيَّامِ التَّشْرِيقِ ‏ ‏فَلَمَّا فَرَغْنَا مِنْ الْحَجِّ وَكَانَتْ اللَّيْلَةُ الَّتِي وَعَدْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ حَرَامٍ أَبُو جَابِرٍ ‏ ‏سَيِّدٌ مِنْ سَادَتِنَا وَكُنَّا نَكْتُمُ مَنْ مَعَنَا مِنْ قَوْمِنَا مِنْ الْمُشْرِكِينَ أَمْرَنَا فَكَلَّمْنَاهُ وَقُلْنَا لَهُ يَا ‏ ‏أَبَا جَابِرٍ ‏ ‏إِنَّكَ سَيِّدٌ مِنْ سَادَتِنَا وَشَرِيفٌ مِنْ أَشْرَافِنَا وَإِنَّا نَرْغَبُ بِكَ عَمَّا أَنْتَ فِيهِ أَنْ تَكُونَ حَطَبًا لِلنَّارِ غَدًا ثُمَّ دَعَوْتُهُ إِلَى الْإِسْلَامِ وَأَخْبَرْتُهُ بِمِيعَادِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْلَمَ وَشَهِدَ مَعَنَا ‏ ‏الْعَقَبَةَ ‏ ‏وَكَانَ نَقِيبًا قَالَ فَنِمْنَا تِلْكَ اللَّيْلَةَ مَعَ قَوْمِنَا فِي رِحَالِنَا حَتَّى إِذَا مَضَى ثُلُثُ اللَّيْلِ خَرَجْنَا مِنْ رِحَالِنَا لِمِيعَادِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَتَسَلَّلُ مُسْتَخْفِينَ تَسَلُّلَ الْقَطَا حَتَّى اجْتَمَعْنَا فِي ‏ ‏الشِّعْبِ ‏ ‏عِنْدَ ‏ ‏الْعَقَبَةِ ‏ ‏وَنَحْنُ سَبْعُونَ رَجُلًا وَمَعَنَا امْرَأَتَانِ مِنْ نِسَائِهِمْ ‏ ‏نَسِيبَةُ بِنْتُ كَعْبٍ ‏ ‏أُمُّ ‏ ‏عُمَارَةَ ‏ ‏إِحْدَى نِسَاءِ ‏ ‏بَنِي مَازِنِ بْنِ النَّجَّارِ ‏ ‏وَأَسْمَاءُ بِنْتُ عَمْرِو بْنِ عَدِيِّ بْنِ ثَابِتٍ ‏ ‏إِحْدَى نِسَاءِ ‏ ‏بَنِي سَلِمَةَ ‏ ‏وَهِيَ أُمُّ ‏ ‏مَنِيعٍ ‏ ‏قَالَ فَاجْتَمَعْنَا ‏ ‏بِالشِّعْبِ ‏ ‏نَنْتَظِرُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى جَاءَنَا وَمَعَهُ يَوْمَئِذٍ عَمُّهُ ‏ ‏الْعَبَّاسُ بْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏وَهُوَ يَوْمَئِذٍ عَلَى دِينِ قَوْمِهِ إِلَّا أَنَّهُ أَحَبَّ أَنْ يَحْضُرَ أَمْرَ ابْنِ أَخِيهِ وَيَتَوَثَّقُ لَهُ فَلَمَّا جَلَسْنَا كَانَ ‏ ‏الْعَبَّاسُ بْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏أَوَّلَ مُتَكَلِّمٍ فَقَالَ يَا مَعْشَرَ ‏ ‏الْخَزْرَجِ ‏ ‏قَالَ وَكَانَتْ ‏ ‏الْعَرَبُ ‏ ‏مِمَّا يُسَمُّونَ هَذَا الْحَيَّ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏الْخَزْرَجَ ‏ ‏أَوْسَهَا وَخَزْرَجَهَا إِنَّ ‏ ‏مُحَمَّدًا ‏ ‏مِنَّا حَيْثُ قَدْ عَلِمْتُمْ وَقَدْ مَنَعْنَاهُ مِنْ قَوْمِنَا مِمَّنْ هُوَ عَلَى مِثْلِ رَأْيِنَا فِيهِ وَهُوَ فِي عِزٍّ مِنْ قَوْمِهِ وَمَنَعَةٍ فِي بَلَدِهِ قَالَ فَقُلْنَا قَدْ سَمِعْنَا مَا قُلْتَ فَتَكَلَّمْ يَا رَسُولَ اللَّهِ فَخُذْ لِنَفْسِكَ وَلِرَبِّكَ مَا أَحْبَبْتَ قَالَ فَتَكَلَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَلَا وَدَعَا إِلَى اللَّهِ عَزَّ وَجَلَّ وَرَغَّبَ فِي الْإِسْلَامِ قَالَ أُبَايِعُكُمْ عَلَى أَنْ تَمْنَعُونِي مِمَّا تَمْنَعُونَ مِنْهُ نِسَاءَكُمْ وَأَبْنَاءَكُمْ قَالَ فَأَخَذَ ‏ ‏الْبَرَاءُ بْنُ مَعْرُورٍ ‏ ‏بِيَدِهِ ثُمَّ قَالَ نَعَمْ وَالَّذِي بَعَثَكَ بِالْحَقِّ لَنَمْنَعَنَّكَ مِمَّا نَمْنَعُ ‏ ‏مِنْهُ أُزُرَنَا فَبَايِعْنَا يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَحْنُ أَهْلُ الْحُرُوبِ وَأَهْلُ الْحَلْقَةِ وَرِثْنَاهَا كَابِرًا عَنْ كَابِرٍ قَالَ فَاعْتَرَضَ الْقَوْلَ ‏ ‏وَالْبَرَاءُ ‏ ‏يُكَلِّمُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبُو الْهَيْثَمِ بْنُ التَّيِّهَانِ ‏ ‏حَلِيفُ ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ بَيْنَنَا وَبَيْنَ الرِّجَالِ حِبَالًا وَإِنَّا قَاطِعُوهَا ‏ ‏يَعْنِي الْعُهُودَ ‏ ‏فَهَلْ عَسَيْتَ إِنْ نَحْنُ فَعَلْنَا ذَلِكَ ثُمَّ أَظْهَرَكَ اللَّهُ أَنْ تَرْجِعَ إِلَى قَوْمِكَ وَتَدَعَنَا قَالَ فَتَبَسَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ بَلْ الدَّمَ الدَّمَ وَالْهَدْمَ الْهَدْمَ أَنَا مِنْكُمْ وَأَنْتُمْ مِنِّي أُحَارِبُ مَنْ حَارَبْتُمْ وَأُسَالِمُ مَنْ سَالَمْتُمْ وَقَدْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْرِجُوا إِلَيَّ مِنْكُمْ اثْنَيْ عَشَرَ ‏ ‏نَقِيبًا ‏ ‏يَكُونُونَ عَلَى قَوْمِهِمْ فَأَخْرَجُوا مِنْهُمْ اثْنَيْ عَشَرَ ‏ ‏نَقِيبًا ‏ ‏مِنْهُمْ تِسْعَةٌ مِنْ ‏ ‏الْخَزْرَجِ ‏ ‏وَثَلَاثَةٌ مِنْ ‏ ‏الْأَوْسِ ‏ ‏وَأَمَّا ‏ ‏مَعْبَدُ بْنُ كَعْبٍ ‏ ‏فَحَدَّثَنِي فِي حَدِيثِهِ عَنْ أَخِيهِ عَنْ أَبِيهِ ‏ ‏كَعْبِ بْنِ مَالِكٍ ‏ ‏قَالَ كَانَ أَوَّلَ مَنْ ضَرَبَ عَلَى يَدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَرَاءُ بْنُ مَعْرُورٍ ‏ ‏ثُمَّ تَتَابَعَ الْقَوْمُ فَلَمَّا بَايَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَرَخَ الشَّيْطَانُ مِنْ رَأْسِ ‏ ‏الْعَقَبَةِ ‏ ‏بِأَبْعَدِ صَوْتٍ سَمِعْتُهُ قَطُّ يَا أَهْلَ ‏ ‏الْجُبَاجِبِ ‏ ‏وَالْجُبَاجِبُ الْمَنَازِلُ ‏ ‏هَلْ لَكُمْ فِي مُذَمَّمٍ وَالصُّبَاةُ مَعَهُ قَدْ أَجْمَعُوا عَلَى حَرْبِكُمْ قَالَ ‏ ‏عَلِيٌّ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏مَا يَقُولُهُ عَدُوُّ اللَّهِ ‏ ‏مُحَمَّدٌ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا أَزَبُّ ‏ ‏الْعَقَبَةِ ‏ ‏هَذَا ابْنُ أَزْيَبَ اسْمَعْ أَيْ عَدُوَّ اللَّهِ أَمَا وَاللَّهِ لَأَفْرُغَنَّ لَكَ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ارْفَعُوا إِلَى ‏ ‏رِحَالِكُمْ ‏ ‏قَالَ فَقَالَ لَهُ ‏ ‏الْعَبَّاسُ بْنُ عُبَادَةَ بْنِ نَضْلَةَ ‏ ‏وَالَّذِي بَعَثَكَ بِالْحَقِّ لَئِنْ شِئْتَ لَنَمِيلَنَّ عَلَى أَهْلِ ‏ ‏مِنًى ‏ ‏غَدًا بِأَسْيَافِنَا قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ أُومَرْ بِذَلِكَ قَالَ فَرَجَعْنَا فَنِمْنَا حَتَّى أَصْبَحْنَا فَلَمَّا أَصْبَحْنَا غَدَتْ عَلَيْنَا ‏ ‏جُلَّةُ ‏ ‏قُرَيْشٍ ‏ ‏حَتَّى جَاءُونَا فِي مَنَازِلِنَا فَقَالُوا يَا مَعْشَرَ ‏ ‏الْخَزْرَجِ ‏ ‏إِنَّهُ قَدْ بَلَغَنَا أَنَّكُمْ قَدْ جِئْتُمْ إِلَى صَاحِبِنَا هَذَا تَسْتَخْرِجُونَهُ مِنْ بَيْنِ أَظْهُرِنَا وَتُبَايِعُونَهُ عَلَى حَرْبِنَا وَاللَّهِ إِنَّهُ مَا مِنْ ‏ ‏الْعَرَبِ ‏ ‏أَحَدٌ أَبْغَضَ إِلَيْنَا أَنْ تَنْشَبَ الْحَرْبُ بَيْنَنَا وَبَيْنَهُ مِنْكُمْ قَالَ فَانْبَعَثَ مَنْ هُنَالِكَ مِنْ مُشْرِكِي قَوْمِنَا يَحْلِفُونَ لَهُمْ بِاللَّهِ مَا كَانَ مِنْ هَذَا شَيْءٌ وَمَا عَلِمْنَاهُ وَقَدْ صَدَقُوا لَمْ يَعْلَمُوا مَا كَانَ مِنَّا قَالَ فَبَعْضُنَا يَنْظُرُ إِلَى بَعْضٍ قَالَ وَقَامَ الْقَوْمُ وَفِيهِمْ ‏ ‏الْحَارِثُ بْنُ هِشَامِ بْنِ الْمُغِيرَةِ الْمَخْزُومِيُّ ‏ ‏وَعَلَيْهِ نَعْلَانِ جَدِيدَانِ قَالَ فَقُلْتُ كَلِمَةً كَأَنِّي أُرِيدُ أَنْ أُشْرِكَ الْقَوْمَ بِهَا فِيمَا قَالُوا مَا تَسْتَطِيعُ يَا ‏ ‏أَبَا جَابِرٍ ‏ ‏وَأَنْتَ سَيِّدٌ مِنْ سَادَتِنَا أَنْ تَتَّخِذَ نَعْلَيْنِ مِثْلَ نَعْلَيْ هَذَا الْفَتَى مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَسَمِعَهَا ‏ ‏الْحَارِثُ ‏ ‏فَخَلَعَهُمَا ثُمَّ رَمَى بِهِمَا إِلَيَّ فَقَالَ وَاللَّهِ لَتَنْتَعِلَنَّهُمَا قَالَ يَقُولُ ‏ ‏أَبُو جَابِرٍ ‏ ‏أَحْفَظْتَ وَاللَّهِ الْفَتَى فَارْدُدْ عَلَيْهِ نَعْلَيْهِ قَالَ فَقُلْتُ وَاللَّهِ لَا أَرُدَّهُمَا قَالَ وَاللَّهِ صُلْحٌ وَاللَّهِ لَئِنْ صَدَقَ الْفَأْلُ لَأَسْلُبَنَّهُ ‏ ‏فَهَذَا حَدِيثُ ‏ ‏كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏الْعَقَبَةِ ‏ ‏وَمَا حَضَرَ مِنْهَا ‏","","",""],[15238,15238,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏بُشَيْرَ بْنَ يَسَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُوَيْدَ بْنَ النُّعْمَانِ ‏ ‏رَجُلًا مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏أَصْحَابِ الشَّجَرَةِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَلَمْ يَكُنْ عِنْدَهُمْ طَعَامٌ قَالَ فَأَتَوْا ‏ ‏بِسَوِيقٍ ‏ ‏فَلَاكُوا مِنْهُ وَشَرِبُوا مِنْهُ ثُمَّ أَتَوْا بِمَاءٍ فَمَضْمَضُوا ثُمَّ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى ‏","","",""],[15239,15239,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏سُوَيْدِ بْنِ النُّعْمَانِ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ ‏ ‏خَيْبَرَ ‏ ‏حَتَّى إِذَا كُنَّا ‏ ‏بِالصَّهْبَاءِ ‏ ‏وَصَلَّى الْعَصْرَ دَعَا بِالْأَطْعِمَةِ فَمَا أُتِيَ إِلَّا ‏ ‏بِسَوِيقٍ ‏ ‏فَأَكَلُوا وَشَرِبُوا مِنْهُ ثُمَّ قَامَ إِلَى الْمَغْرِبِ فَمَضْمَضَ وَمَضْمَضْنَا مَعَهُ وَمَا مَسَّ مَاءً ‏","","",""],[15240,15240,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا مَالِكٍ الْأَشْجَعِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْ ‏ ‏رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ قَدْ خَالَفَ بَيْنَ طَرَفَيْهِ ‏","","",""],[15241,15241,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَلْقَمَةُ الْمُزَنِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏قَالَ ‏ ‏كُنْتُ فِي مَجْلِسٍ فِيهِ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَقَالَ لِرَجُلٍ مِنْ الْقَوْمِ يَا ‏ ‏فُلَانُ ‏ ‏كَيْفَ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْعَتُ الْإِسْلَامَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْإِسْلَامَ بَدَأَ ‏ ‏جَذَعًا ‏ ‏ثُمَّ ‏ ‏ثَنِيًّا ‏ ‏ثُمَّ ‏ ‏رَبَاعِيًا ‏ ‏ثُمَّ ‏ ‏سَدِيسِيًّا ‏ ‏ثُمَّ ‏ ‏بَازِلًا ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏فَمَا بَعْدَ ‏ ‏الْبُزُولِ ‏ ‏إِلَّا النُّقْصَانُ ‏","","",""],[15242,15242,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرًا ‏ ‏سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُخَابِرُ ‏ ‏وَلَا نَرَى بِذَلِكَ بَأْسًا حَتَّى زَعَمَ ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهُ فَتَرَكْنَاهُ ‏","","",""],[15243,15243,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا قَطْعَ فِي ثَمَرٍ وَلَا كَثَرٍ ‏","","",""],[15244,15244,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْوَاحِدِ بْنِ نَافِعٍ الْكَلَاعِيِّ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏قَالَ ‏ ‏مَرَرْتُ بِمَسْجِدٍ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَأُقِيمَتْ الصَّلَاةُ فَإِذَا ‏ ‏شَيْخٌ ‏ ‏فَلَامَ الْمُؤَذِّنَ وَقَالَ أَمَا عَلِمْتَ أَنَّ ‏ ‏أَبِي ‏ ‏أَخْبَرَنِي أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْمُرُ بِتَأْخِيرِ هَذِهِ الصَّلَاةِ ‏ ‏قَالَ ‏ ‏قُلْتُ مَنْ هَذَا الشَّيْخُ قَالُوا هَذَا ‏ ‏عَبْدُ اللَّهِ بْنُ رَافِعِ بْنِ خَدِيجٍ ‏","","",""],[15245,15245,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبَايَةَ بْنِ رِفَاعَةَ بْنِ رَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّا لَاقُو الْعَدُوِّ غَدًا وَلَيْسَ مَعَنَا ‏ ‏مُدًى ‏ ‏قَالَ ‏ ‏مَا ‏ ‏أَنْهَرَ ‏ ‏الدَّمَ وَذُكِرَ عَلَيْهِ اسْمُ اللَّهِ فَكُلْ لَيْسَ السِّنَّ وَالظُّفُرَ وَسَأُحَدِّثُكَ أَمَّا السِّنُّ فَعَظْمٌ وَأَمَّا الظُّفُرُ ‏ ‏فَمُدَى ‏ ‏الْحَبَشَةِ ‏ ‏قَالَ وَأَصَابَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهْبًا ‏ ‏فَنَدَّ ‏ ‏مِنْهَا بَعِيرٌ فَسَعَوْا لَهُ فَلَمْ يَسْتَطِيعُوا فَرَمَاهُ رَجُلٌ بِسَهْمٍ فَحَبَسَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِهَذِهِ الْإِبِلِ ‏ ‏أَوْ قَالَ لِهَذِهِ النَّعَمِ ‏ ‏أَوَابِدَ ‏ ‏كَأَوَابِدِ ‏ ‏الْوَحْشِ فَمَا غَلَبَكُمْ فَاصْنَعُوا بِهِ هَكَذَا ‏","","",""],[15246,15246,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ عَطَاءٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏بَنِي حَارِثَةَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏رَافِعَ بْنَ خَدِيجٍ ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّهُمْ خَرَجُوا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ قَالَ فَلَمَّا نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْغَدَاءِ قَالَ عَلَّقَ كُلُّ رَجُلٍ ‏ ‏بِخِطَامِ ‏ ‏نَاقَتِهِ ثُمَّ أَرْسَلَهَا تَهُزُّ فِي الشَّجَرِ قَالَ ثُمَّ جَلَسْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَرِحَالُنَا ‏ ‏عَلَى أَبَاعِرِنَا قَالَ فَرَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ فَرَأَى أَكْسِيَةً لَنَا فِيهَا خُيُوطٌ مِنْ ‏ ‏عِهْنٍ ‏ ‏أَحْمَرَ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أَرَى ‏ ‏هَذِهِ الْحُمْرَةَ قَدْ عَلَتْكُمْ قَالَ فَقُمْنَا سِرَاعًا لِقَوْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى ‏ ‏نَفَرَ ‏ ‏بَعْضُ إِبِلِنَا فَأَخَذْنَا الْأَكْسِيَةَ فَنَزَعْنَاهَا مِنْهَا ‏","","",""],[15247,15247,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏حَدَّثَنَا ‏ ‏مُجَاهِدٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أُسَيْدُ ‏ ‏ابْنُ أَخِي ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ قَالَ ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَمْرٍ كَانَ لَنَا نَافِعًا وَطَاعَةُ اللَّهِ وَطَاعَةُ رَسُولِهِ أَنْفَعُ لَنَا قَالَ ‏ ‏مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَزْرَعْهَا فَإِنْ عَجَزَ عَنْهَا فَلْيُزْرِعْهَا أَخَاهُ ‏ ‏هَذَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الرَّحْمَنِ الزُّبَيْدِيُّ ‏ ‏حَدَّثَ عَنْهُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وحَكَّامٌ ‏","","",""],[15248,15248,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَّ النَّاسَ ‏ ‏كَانُوا ‏ ‏يُكْرُونَ ‏ ‏الْمَزَارِعَ فِي زَمَانِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَاذِيَانَاتِ ‏ ‏وَمَا سَقَى ‏ ‏الرَّبِيعُ ‏ ‏وَشَيْئًا مِنْ التِّبْنِ فَكَرِهَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِرَاءَ ‏ ‏الْمَزَارِعِ بِهَذَا وَنَهَى عَنْهَا ‏ ‏و قَالَ ‏ ‏رَافِعٌ ‏ ‏لَا بَأْسَ بِكِرَائِهَا بِالدَّرَاهِمِ وَالدَّنَانِيرِ ‏","","",""],[15249,15249,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبَايَةَ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏الْحُمَّى ‏ ‏فَوْرُ جَهَنَّمَ فَابْرُدُوهَا بِالْمَاءِ ‏","","",""],[15250,15250,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏الْحَكَمُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْحَقْلِ ‏ ‏قَالَ ‏ ‏قُلْتُ وَمَا ‏ ‏الْحَقْلُ ‏ ‏قَالَ ‏ ‏الثُّلُثُ وَالرُّبُعُ ‏ ‏فَلَمَّا سَمِعَ ذَلِكَ ‏ ‏إِبْرَاهِيمُ ‏ ‏كَرِهَ الثُّلُثَ وَالرُّبُعَ وَلَمْ يَرَ بَأْسًا بِالْأَرْضِ ‏ ‏الْبَيْضَاءِ ‏ ‏يَأْخُذُهَا بِالدَّرَاهِمِ ‏","","",""],[15251,15251,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ قَارِظٍ ‏ ‏عَنْ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَسْبُ الْحَجَّامِ ‏ ‏خَبِيثٌ وَمَهْرُ ‏ ‏الْبَغِيِّ ‏ ‏خَبِيثٌ وَثَمَنُ الْكَلْبِ خَبِيثٌ ‏","","",""],[15252,15252,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبَايَةَ بْنِ رِفَاعَةَ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏جَدِّهِ ‏ ‏أَنَّهُ قَالَ يَا رَسُولَ اللَّهِ إِنَّا لَاقُو الْعَدُوِّ غَدًا وَلَيْسَ مَعَنَا ‏ ‏مُدًى ‏ ‏قَالَ ‏ ‏مَا ‏ ‏أَنْهَرَ ‏ ‏الدَّمَ وَذُكِرَ اسْمُ اللَّهِ عَلَيْهِ فَكُلْ لَيْسَ السِّنَّ وَالظُّفُرَ وَسَأُحَدِّثُكَ أَمَّا السِّنُّ فَعَظْمٌ وَأَمَّا الظُّفُرُ ‏ ‏فَمُدَى ‏ ‏الْحَبَشَةِ ‏","","",""],[15253,15253,"","","‏ ‏وَأَصَابَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهْبًا ‏ ‏فَنَدَّ ‏ ‏بَعِيرٌ مِنْهَا فَسَعَوْا فَلَمْ يَسْتَطِيعُوهُ فَرَمَاهُ رَجُلٌ مِنْ الْقَوْمِ بِسَهْمٍ فَحَبَسَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِهَذِهِ الْإِبِلِ ‏ ‏أَوْ النَّعَمِ ‏ ‏أَوَابِدَ ‏ ‏كَأَوَابِدِ ‏ ‏الْوَحْشِ فَإِذَا غَلَبَكُمْ شَيْءٌ مِنْهَا فَاصْنَعُوا بِهِ هَكَذَا ‏","","",""],[15254,15254,"","","‏ ‏قَالَ ‏ ‏وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْعَلُ فِي قَسْمِ الْغَنَائِمِ عَشْرًا مِنْ الشَّاءِ بِبَعِيرٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَكْثَرُ عِلْمِي أَنِّي قَدْ سَمِعْتُ مِنْ ‏ ‏سَعِيدٍ ‏ ‏هَذَا الْحَرْفَ وَجَعَلَ عَشْرًا مِنْ الشَّاءِ بِبَعِيرٍ ‏ ‏وَقَدْ ‏ ‏حَدَّثَنِي ‏ ‏سُفْيَانُ ‏ ‏عَنْهُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَقَدْ ‏ ‏سَمِعْتُ مِنْ ‏ ‏سُفْيَانَ ‏ ‏هَذَا الْحَرْفَ ‏","","",""],[15255,15255,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏قَالَ ‏ ‏سَرَقَ ‏ ‏غُلَامٌ ‏ ‏لِنُعْمَانَ الْأَنْصَارِيِّ ‏ ‏نَخْلًا صِغَارًا فَرُفِعَ إِلَى ‏ ‏مَرْوَانَ ‏ ‏فَأَرَادَ أَنْ يَقْطَعَهُ فَقَالَ ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُقْطَعُ فِي الثَّمَرِ وَلَا فِي ‏ ‏الْكَثَرِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِيَحْيَى ‏ ‏مَا ‏ ‏الْكَثَرُ ‏ ‏قَالَ ‏ ‏الْجُمَّارُ ‏","","",""],[15256,15256,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أُسَيْدِ بْنِ ظُهَيْرٍ ‏ ‏ابْنُ أَخِي ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏كَانَ أَحَدُنَا إِذَا اسْتَغْنَى عَنْ أَرْضِهِ أَعْطَاهَا بِالثُّلُثِ وَالرُّبُعِ وَالنِّصْفِ وَيَشْتَرِطُ ثَلَاثَ ‏ ‏جَدَاوِلَ ‏ ‏وَالْقُصَارَةَ ‏ ‏وَمَا سَقَى ‏ ‏الرَّبِيعُ ‏ ‏وَكَانَ الْعَيْشُ إِذْ ذَاكَ شَدِيدًا وَكَانَ يُعْمَلُ فِيهَا بِالْحَدِيدِ وَمَا شَاءَ اللَّهُ وَيُصِيبُ مِنْهَا مَنْفَعَةً فَأَتَانَا ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَاكُمْ عَنْ أَمْرٍ كَانَ لَكُمْ نَافِعًا وَطَاعَةُ اللَّهِ وَطَاعَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْفَعُ لَكُمْ إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَاكُمْ عَنْ ‏ ‏الْحَقْلِ ‏ ‏وَيَقُولُ مَنْ اسْتَغْنَى عَنْ أَرْضِهِ فَلْيَمْنَحْهَا أَخَاهُ أَوْ لِيَدَعْ ‏ ‏وَيَنْهَاكُمْ عَنْ الْمُزَابَنَةِ ‏ ‏وَالْمُزَابَنَةُ أَنْ يَكُونَ الرَّجُلُ لَهُ الْمَالُ الْعَظِيمُ مِنْ النَّخْلِ فَيَأْتِيهِ الرَّجُلُ فَيَقُولُ قَدْ أَخَذْتُهُ بِكَذَا ‏ ‏وَسْقًا ‏ ‏مِنْ تَمْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أُسَيْدِ بْنِ ظُهَيْرٍ ‏ ‏قَالَ ‏ ‏كَانَ أَحَدُنَا إِذَا اسْتَغْنَى عَنْ أَرْضِهِ فَذَكَرَ الْحَدِيثَ وَقَالَ يَشْتَرِطُ ثَلَاثَ ‏ ‏جَدَاوِلَ ‏ ‏وَالْقُصَارَةُ ‏ ‏مَا سَقَطَ مِنْ السُّنْبُلِ ‏","","",""],[15257,15257,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أُسَيْدِ بْنِ ظُهَيْرٍ ‏ ‏قَالَ ‏ ‏كَانَ أَحَدُنَا إِذَا اسْتَغْنَى عَنْ أَرْضِهِ أَوْ افْتَقَرَ إِلَيْهَا أَعْطَاهَا بِالنِّصْفِ وَالثُّلُثِ وَالرُّبُعِ وَيَشْتَرِطُ ثَلَاثَ ‏ ‏جَدَاوِلَ ‏ ‏وَالْقُصَارَةَ ‏ ‏وَمَا سَقَى ‏ ‏الرَّبِيعُ ‏ ‏وَكُنَّا نَعْمَلُ فِيهَا عَمَلًا شَدِيدًا وَنُصِيبُ مِنْهَا مَنْفَعَةً فَأَتَانَا ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏فَقَالَ نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَمْرٍ كَانَ لَكُمْ نَافِعًا وَطَاعَةُ اللَّهِ وَطَاعَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرٌ لَكُمْ ‏ ‏نَهَاكُمْ عَنْ ‏ ‏الْحَقْلِ ‏ ‏وَقَالَ مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَمْنَحْهَا أَخَاهُ أَوْ لِيَدَعْهَا وَنَهَانَا عَنْ الْمُزَابَنَةِ ‏ ‏وَالْمُزَابَنَةُ الرَّجُلُ يَكُونُ لَهُ الْمَالُ الْعَظِيمُ مِنْ النَّخْلِ فَيَجِيءُ الرَّجُلُ فَيَأْخُذُهَا بِكَذَا وَكَذَا ‏ ‏وَسْقًا ‏ ‏مِنْ تَمْرٍ ‏","","",""],[15258,15258,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يُكْرِي ‏ ‏الْمَزَارِعَ ‏ ‏فَبَلَغَهُ أَنَّ ‏ ‏رَافِعًا ‏ ‏يَأْثِرُ ‏ ‏فِيهِ حَدِيثًا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجَ إِلَيْهِ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِلَى ‏ ‏الْبَلَاطِ ‏ ‏فَسَأَلَهُ فَأَخْبَرَهُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏كِرَاءِ ‏ ‏الْمَزَارِعِ فَتَرَكَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏كِرَاءَهَا ‏ ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏فِي حَدِيثِهِ فَذَهَبَ إِلَيْهِ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَذَهَبْتُ مَعَهُ ‏ ‏وَكَذَا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَاه ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏أَيْضًا قَالَ ‏ ‏فَذَهَبَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَذَهَبْتُ مَعَهُ ‏","","",""],[15259,15259,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَصْبِحُوا بِالصُّبْحِ فَإِنَّهُ أَعْظَمُ لِلْأَجْرِ ‏ ‏أَوْ لِأَجْرِهَا ‏","","",""],[15260,15260,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبَايَةَ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏جِبْرِيلَ ‏ ‏أَوْ مَلَكًا ‏ ‏جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا تَعُدُّونَ مَنْ شَهِدَ ‏ ‏بَدْرًا ‏ ‏فِيكُمْ قَالُوا خِيَارُنَا قَالَ كَذَلِكَ هُمْ عِنْدَنَا خِيَارُنَا مِنْ الْمَلَائِكَةِ ‏","","",""],[15261,15261,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ زَرَعَ أَرْضًا بِغَيْرِ إِذْنِ أَهْلِهَا فَلَهُ نَفَقَتُهُ ‏ ‏قَالَ ‏ ‏أَبُو كَامِلٍ ‏ ‏فِي حَدِيثِهِ وَلَيْسَ لَهُ مِنْ الزَّرْعِ شَيْءٌ ‏","","",""],[15262,15262,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ ذَرٍّ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ رَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏جَاءَنَا مِنْ عِنْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَمْرٍ كَانَ يَرْفُقُ بِنَا وَطَاعَةُ اللَّهِ وَطَاعَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْفَقُ بِنَا ‏ ‏نَهَانَا أَنْ نَزْرَعَ أَرْضًا إِلَّا أَرْضًا يَمْلِكُ أَحَدُنَا رَقَبَتَهَا أَوْ ‏ ‏مِنْحَةَ ‏ ‏رَجُلٍ ‏","","",""],[15263,15263,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُحَاقِلُ ‏ ‏بِالْأَرْضِ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنُكْرِيهَا ‏ ‏بِالثُّلُثِ وَالرُّبُعِ وَالطَّعَامِ الْمُسَمَّى فَجَاءَنَا ذَاتَ يَوْمٍ ‏ ‏رَجُلٌ ‏ ‏مِنْ عُمُومَتِي فَقَالَ نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَمْرٍ كَانَ لَنَا نَافِعًا وَطَاعَةُ اللَّهِ وَرَسُولِهِ أَنْفَعُ لَنَا ‏ ‏نَهَانَا أَنْ ‏ ‏نُحَاقِلَ ‏ ‏بِالْأَرْضِ ‏ ‏فَنُكْرِيَهَا ‏ ‏عَلَى الثُّلُثِ وَالرُّبُعِ وَالطَّعَامِ الْمُسَمَّى وَأَمَرَ رَبَّ الْأَرْضِ أَنْ يَزْرَعَهَا أَوْ يُزْرِعَهَا وَكَرِهَ ‏ ‏كِرَاءَهَا ‏ ‏وَمَا سِوَى ذَلِكَ ‏","","",""],[15264,15264,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏مَا كُنَّا نَرَى بِالْخَبْرِ بَأْسًا حَتَّى زَعَمَ ‏ ‏ابْنُ خَدِيجٍ ‏ ‏عَامَ أَوَّلٍ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهُ ‏","","",""],[15265,15265,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ يَا ‏ ‏ابْنَ خَدِيجٍ ‏ ‏مَاذَا تُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏كِرَاءِ ‏ ‏الْأَرْضِ قَالَ ‏ ‏رَافِعٌ ‏ ‏لَقَدْ سَمِعْتُ ‏ ‏عَمَّيَّ ‏ ‏وَكَانَا قَدْ شَهِدَا ‏ ‏بَدْرًا ‏ ‏يُحَدِّثَانِ أَهْلَ الدَّارِ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏كِرَاءِ ‏ ‏الْأَرْضِ ‏","","",""],[15266,15266,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْعَامِلُ فِي ‏ ‏الصَّدَقَةِ ‏ ‏بِالْحَقِّ لِوَجْهِ اللَّهِ عَزَّ وَجَلَّ كَالْغَازِي فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ حَتَّى يَرْجِعَ إِلَى أَهْلِهِ ‏","","",""],[15267,15267,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَسْبُ الْحَجَّامِ ‏ ‏خَبِيثٌ وَمَهْرُ ‏ ‏الْبَغِيِّ ‏ ‏خَبِيثٌ وَثَمَنُ الْكَلْبِ خَبِيثٌ ‏","","",""],[15268,15268,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏عَنْ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[15269,15269,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْحَقْلِ ‏ ‏قَالَ ‏ ‏الْحَكَمُ ‏ ‏وَالْحَقْلُ ‏ ‏الثُّلُثُ وَالرُّبُعُ ‏","","",""],[15270,15270,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ بْنِ نِيَارٍ ‏ ‏أَنَّهُ ذَبَحَ قَبْلَ أَنْ يَذْبَحَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُ أَنْ يُعِيدَ قَالَ إِنِّي لَا أَجِدُ إِلَّا ‏ ‏جَذَعَةً ‏ ‏فَأَمَرَهُ أَنْ يَذْبَحَ ‏","","",""],[15271,15271,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ عَبْدِ اللَّهِ بْنِ جُمَيْعٍ ‏ ‏عَنِ ‏ ‏الْجَهْمِ بْنِ أَبِي الْجَهْمِ ‏ ‏عَنِ ‏ ‏ابْنِ نِيَارٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَذْهَبُ الدُّنْيَا حَتَّى تَكُونَ ‏ ‏لِلُكَعِ ‏ ‏ابْنِ ‏ ‏لُكَعٍ ‏","","",""],[15272,15272,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُجْلَدُ فَوْقَ عَشْرِ جَلَدَاتٍ إِلَّا فِي ‏ ‏حَدٍّ ‏ ‏مِنْ ‏ ‏حُدُودِ ‏ ‏اللَّهِ تَعَالَى ‏","","",""],[15273,15273,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏جُمَيْعِ بْنِ عُمَيْرٍ ‏ ‏وَلَمْ يَشُكَّ ‏ ‏عَنْ ‏ ‏خَالِهِ ‏ ‏أَبِي بُرْدَةَ بْنِ نِيَارٍ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏نَقِيعِ ‏ ‏الْمُصَلَّى فَأَدْخَلَ يَدَهُ فِي طَعَامٍ ثُمَّ أَخْرَجَهَا فَإِذَا هُوَ مَغْشُوشٌ ‏ ‏أَوْ مُخْتَلِفٌ ‏ ‏فَقَالَ ‏ ‏لَيْسَ مِنَّا مَنْ غَشَّنَا ‏","","",""],[15274,15274,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ جَابِرٍ ‏ ‏حَدِّثْ فَحَدَّثَ عَنْ ‏ ‏أَبِي بُرْدَةَ بْنِ نِيَارٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا جَلْدَ فَوْقَ عَشْرِ جَلَدَاتٍ إِلَّا فِي ‏ ‏حَدٍّ ‏ ‏مِنْ ‏ ‏حُدُودِ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[15275,15275,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ بْنِ نِيَارٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يُجْلَدُ فَوْقَ عَشْرِ جَلَدَاتٍ إِلَّا فِي ‏ ‏حَدٍّ ‏ ‏مِنْ ‏ ‏حُدُودِ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏ ‏وَكَانَ ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنَاهُ ‏ ‏بِبَغْدَادَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏بُكَيْرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏فَلَمَّا كُنَّا ‏ ‏بِمِصْرَ ‏ ‏أَخْبَرَنَا ‏ ‏بُكَيْرُ بْنُ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏","","",""],[15276,15276,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏وَائِلٍ ‏ ‏عَنْ ‏ ‏جُمَيْعِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏خَالِهِ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَفْضَلِ الْكَسْبِ فَقَالَ بَيْعٌ ‏ ‏مَبْرُورٌ ‏ ‏وَعَمَلُ الرَّجُلِ بِيَدِهِ ‏","","",""],[15277,15277,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ جُمَيْعٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ أَبِي الْجَهْمِ ‏ ‏قَالَ ‏ ‏أَقْبَلْتُ أَنَا ‏ ‏وَزَيْدُ بْنُ حَسَنٍ ‏ ‏بَيْنَنَا ‏ ‏ابْنُ رُمَّانَةَ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الْعَزِيزِ بْنِ مَرْوَانَ ‏ ‏قَدْ نَصَبْنَا لَهُ أَيْدِيَنَا فَهُوَ مُتَّكِئٌ عَلَيْهَا دَاخِلَ الْمَسْجِدِ ‏ ‏مَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَهَى ‏ ‏ابْنَ نِيَارٍ ‏ ‏رَجُلٌ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرْسَلَ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏ائْتِنِي فَأَتَاهُ فَقَالَ رَأَيْتُ ‏ ‏ابْنَ رُمَّانَةَ ‏ ‏بَيْنَكُمَا يَتَوَكَّأُ عَلَيْكَ وَعَلَى ‏ ‏زَيْدِ بْنِ حَسَنٍ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَنْ تَذْهَبَ الدُّنْيَا حَتَّى تَكُونَ عِنْدَ ‏ ‏لُكَعِ ‏ ‏ابْنِ ‏ ‏لُكَعٍ ‏","","",""],[15278,15278,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ الْبُرْسَانِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ مِينَاءَ ‏ ‏عَنْ ‏ ‏أَبِي سَعْدِ بْنِ أَبِي فَضَالَةَ الْأَنْصَارِيِّ ‏ ‏وَكَانَ مِنْ الصَّحَابَةِ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا جَمَعَ اللَّهُ عَزَّ وَجَلَّ الْأَوَّلِينَ وَالْآخِرِينَ لِيَوْمٍ لَا رَيْبَ فِيهِ نَادَى مُنَادٍ مَنْ كَانَ أَشْرَكَ فِي عَمَلٍ عَمِلَهُ لِلَّهِ تَبَارَكَ وَتَعَالَى أَحَدًا فَلْيَطْلُبْ ثَوَابَهُ مِنْ عِنْدِ غَيْرِ اللَّهِ عَزَّ وَجَلَّ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ أَغْنَى الشُّرَكَاءِ عَنْ الشِّرْكِ ‏","","",""],[15279,15279,"","","‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ إِبْرَاهِيمَ الزُّهْرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏سُهَيْلِ ابْنِ بَيْضَاءَ ‏ ‏أَنَّهُ قَالَ ‏ ‏نَادَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ وَأَنَا ‏ ‏رَدِيفُهُ ‏ ‏يَا ‏ ‏سُهَيْلُ ابْنَ بَيْضَاءَ ‏ ‏رَافِعًا بِهَا صَوْتَهُ مِرَارًا حَتَّى سَمِعَ مَنْ خَلْفَنَا وَأَمَامَنَا فَاجْتَمَعُوا وَعَلِمُوا أَنَّهُ يُرِيدُ أَنْ يَتَكَلَّمَ بِشَيْءٍ إِنَّهُ ‏ ‏مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ أَوْجَبَ اللَّهُ عَزَّ وَجَلَّ لَهُ بِهَا الْجَنَّةَ وَأَعْتَقَهُ بِهَا مِنْ النَّارِ ‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ ‏ ‏حَيْوَةُ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الصَّلْتِ ‏ ‏عَنْ ‏ ‏سُهَيْلِ ابْنِ الْبَيْضَاءِ ‏ ‏مِنْ ‏ ‏بَنِي عَبْدِ الدَّارِ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ فِي سَفَرٍ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[15280,15280,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏صَالِحُ بْنُ إِبْرَاهِيمَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏أَخِي ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ سَلَامَةَ بْنِ وَقْشٍ ‏ ‏وَكَانَ مِنْ أَصْحَابِ ‏ ‏بَدْرٍ ‏ ‏قَالَ ‏ ‏كَانَ لَنَا جَارٌ مِنْ ‏ ‏يَهُودَ ‏ ‏فِي ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏قَالَ فَخَرَجَ عَلَيْنَا يَوْمًا مِنْ بَيْتِهِ قَبْلَ مَبْعَثِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَسِيرٍ فَوَقَفَ عَلَى مَجْلِسِ ‏ ‏عَبْدِ الْأَشْهَلِ ‏ ‏قَالَ ‏ ‏سَلَمَةُ ‏ ‏وَأَنَا يَوْمَئِذٍ أَحْدَثُ مَنْ فِيهِ سِنًّا عَلَيَّ ‏ ‏بُرْدَةٌ ‏ ‏مُضْطَجِعًا فِيهَا ‏ ‏بِفِنَاءِ ‏ ‏أَهْلِي فَذَكَرَ الْبَعْثَ وَالْقِيَامَةَ وَالْحِسَابَ وَالْمِيزَانَ وَالْجَنَّةَ وَالنَّارَ فَقَالَ ذَلِكَ لِقَوْمٍ أَهْلِ شِرْكٍ أَصْحَابِ أَوْثَانٍ لَا يَرَوْنَ أَنَّ بَعْثًا كَائِنٌ بَعْدَ الْمَوْتِ فَقَالُوا لَهُ ‏ ‏وَيْحَكَ ‏ ‏يَا فُلَانُ ‏ ‏تَرَى هَذَا كَائِنًا إِنَّ النَّاسَ يُبْعَثُونَ بَعْدَ مَوْتِهِمْ إِلَى دَارٍ فِيهَا جَنَّةٌ وَنَارٌ يُجْزَوْنَ فِيهَا بِأَعْمَالِهِمْ قَالَ نَعَمْ وَالَّذِي يُحْلَفُ بِهِ لَوَدَّ أَنَّ لَهُ بِحَظِّهِ مِنْ تِلْكَ النَّارِ أَعْظَمَ ‏ ‏تَنُّورٍ ‏ ‏فِي الدُّنْيَا يُحَمُّونَهُ ثُمَّ يُدْخِلُونَهُ إِيَّاهُ فَيُطْبَقُ بِهِ عَلَيْهِ وَأَنْ يَنْجُوَ مِنْ تِلْكَ النَّارِ غَدًا قَالُوا لَهُ ‏ ‏وَيْحَكَ ‏ ‏وَمَا آيَةُ ذَلِكَ قَالَ نَبِيٌّ يُبْعَثُ مِنْ نَحْوِ هَذِهِ الْبِلَادِ وَأَشَارَ بِيَدِهِ نَحْوَ ‏ ‏مَكَّةَ ‏ ‏وَالْيَمَنِ ‏ ‏قَالُوا وَمَتَى تَرَاهُ قَالَ فَنَظَرَ إِلَيَّ وَأَنَا مِنْ أَحْدَثِهِمْ سِنًّا فَقَالَ إِنْ يَسْتَنْفِدْ هَذَا الْغُلَامُ عُمُرَهُ يُدْرِكْهُ قَالَ ‏ ‏سَلَمَةُ ‏ ‏فَوَاللَّهِ مَا ذَهَبَ اللَّيْلُ وَالنَّهَارُ حَتَّى ‏ ‏بَعَثَ اللَّهُ تَعَالَى رَسُولَهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ حَيٌّ بَيْنَ أَظْهُرِنَا فَآمَنَّا بِهِ وَكَفَرَ بِهِ بَغْيًا وَحَسَدًا فَقُلْنَا وَيْلَكَ يَا فُلَانُ أَلَسْتَ بِالَّذِي قُلْتَ لَنَا فِيهِ مَا قُلْتَ قَالَ بَلَى وَلَيْسَ بِهِ ‏","","",""],[15281,15281,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ يَعْنِي ابْنَ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ حُرَيْثٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَخِي ‏ ‏سَعِيدُ بْنُ حُرَيْثٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ بَاعَ ‏ ‏عَقَارًا ‏ ‏كَانَ ‏ ‏قَمِنًا ‏ ‏أَنْ لَا يُبَارَكَ لَهُ إِلَّا أَنْ يَجْعَلَهُ فِي مِثْلِهِ أَوْ غَيْرِهِ ‏","","",""],[15282,15282,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏مِنْ كِتَابِهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ كُرَيْبٍ ‏ ‏أَنَّ غُلَامًا مِنْهُمْ تُوُفِّيَ ‏ ‏فَوَجَدَ ‏ ‏عَلَيْهِ أَبَوَاهُ أَشَدَّ ‏ ‏الْوَجْدِ ‏ ‏فَقَالَ ‏ ‏حَوْشَبٌ صَاحِبُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُخْبِرُكُمْ بِمَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي مِثْلِ ابْنِكَ إِنَّ رَجُلًا مِنْ أَصْحَابِهِ كَانَ لَهُ ابْنٌ قَدْ ‏ ‏أَدَبَّ ‏ ‏أَوْ ‏ ‏دَبَّ ‏ ‏وَكَانَ يَأْتِي مَعَ أَبِيهِ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ إِنَّ ابْنَهُ تُوُفِّيَ ‏ ‏فَوَجَدَ ‏ ‏عَلَيْهِ أَبُوهُ قَرِيبًا مِنْ سِتَّةِ أَيَّامٍ لَا يَأْتِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَرَى فُلَانًا قَالُوا يَا رَسُولَ اللَّهِ إِنَّ ابْنَهُ تُوُفِّيَ ‏ ‏فَوَجَدَ ‏ ‏عَلَيْهِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا فُلَانُ ‏ ‏أَتُحِبُّ لَوْ أَنَّ ابْنَكَ عِنْدَكَ الْآنَ كَأَنْشَطِ الصِّبْيَانِ نَشَاطًا أَتُحِبُّ أَنَّ ابْنَكَ عِنْدَكَ أَحَرُّ الْغِلْمَانِ جَرَاءَةً أَتُحِبُّ أَنَّ ابْنَكَ عِنْدَكَ كَهْلًا كَأَفْضَلِ الْكُهُولِ أَوْ يُقَالُ لَكَ ادْخُلْ الْجَنَّةَ ثَوَابَ مَا أُخِذَ مِنْكَ ‏","","",""],[15283,15283,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ قَالَ ‏ ‏أَبِي ‏ ‏كَمَا ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ عَبْدِ اللَّهِ بْنِ جُنْدُبٍ الْجُهَنِيِّ ‏ ‏عَنْ ‏ ‏جُنْدُبِ بْنِ مَكِيثٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَالِبَ بْنَ عَبْدِ اللَّهِ الْكَلْبِيَّ ‏ ‏كَلْبَ لَيْثٍ ‏ ‏إِلَى ‏ ‏بَنِي مُلَوَّحٍ ‏ ‏بِالْكَدِيدِ ‏ ‏وَأَمَرَهُ أَنْ ‏ ‏يُغِيرَ ‏ ‏عَلَيْهِمْ فَخَرَجَ فَكُنْتُ فِي ‏ ‏سَرِيَّتِهِ ‏ ‏فَمَضَيْنَا حَتَّى إِذَا كُنَّا ‏ ‏بِقُدَيْدٍ ‏ ‏لَقِينَا بِهِ ‏ ‏الْحَارِثَ بْنَ مَالِكٍ وَهُوَ ابْنُ الْبَرْصَاءِ اللَّيْثِيُّ ‏ ‏فَأَخَذْنَاهُ فَقَالَ إِنَّمَا جِئْتُ لِأُسْلِمَ فَقَالَ ‏ ‏غَالِبُ بْنُ عَبْدِ اللَّهِ ‏ ‏إِنْ كُنْتَ إِنَّمَا جِئْتَ مُسْلِمًا فَلَنْ يَضُرَّكَ رِبَاطُ يَوْمٍ وَلَيْلَةٍ وَإِنْ كُنْتَ عَلَى غَيْرِ ذَلِكَ اسْتَوْثَقْنَا مِنْكَ قَالَ فَأَوْثَقَهُ رِبَاطًا ثُمَّ خَلَّفَ عَلَيْهِ رَجُلًا أَسْوَدَ كَانَ مَعَنَا فَقَالَ امْكُثْ مَعَهُ حَتَّى نَمُرَّ عَلَيْكَ فَإِنْ نَازَعَكَ ‏ ‏فَاجْتَزَّ ‏ ‏رَأْسَهُ قَالَ ثُمَّ مَضَيْنَا حَتَّى أَتَيْنَا بَطْنَ ‏ ‏الْكَدِيدِ ‏ ‏فَنَزَلْنَا ‏ ‏عُشَيْشِيَةً بَعْدَ الْعَصْرِ فَبَعَثَنِي أَصْحَابِي فِي ‏ ‏رَبِيئَةٍ ‏ ‏فَعَمَدْتُ إِلَى تَلٍّ يُطْلِعُنِي عَلَى الْحَاضِرِ فَانْبَطَحْتُ عَلَيْهِ وَذَلِكَ الْمَغْرِبَ فَخَرَجَ رَجُلٌ مِنْهُمْ فَنَظَرَ فَرَآنِي مُنْبَطِحًا عَلَى التَّلِّ فَقَالَ لِامْرَأَتِهِ وَاللَّهِ إِنِّي لَأَرَى عَلَى هَذَا التَّلِّ سَوَادًا مَا رَأَيْتُهُ أَوَّلَ النَّهَارِ فَانْظُرِي لَا تَكُونُ الْكِلَابُ اجْتَرَّتْ بَعْضَ أَوْعِيَتِكِ قَالَ فَنَظَرَتْ فَقَالَتْ لَا وَاللَّهِ مَا أَفْقِدُ شَيْئًا قَالَ فَنَاوِلِينِي قَوْسِي وَسَهْمَيْنِ مِنْ ‏ ‏كِنَانَتِي ‏ ‏قَالَ فَنَاوَلَتْهُ فَرَمَانِي بِسَهْمٍ فَوَضَعَهُ فِي جَنْبِي قَالَ فَنَزَعْتُهُ فَوَضَعْتُهُ وَلَمْ أَتَحَرَّكْ ثُمَّ رَمَانِي بِآخَرَ فَوَضَعَهُ فِي رَأْسِ ‏ ‏مَنْكِبِي ‏ ‏فَنَزَعْتُهُ فَوَضَعْتُهُ وَلَمْ أَتَحَرَّكْ فَقَالَ لِامْرَأَتِهِ وَاللَّهِ لَقَدْ خَالَطَهُ سَهْمَايَ وَلَوْ كَانَ دَابَّةً لَتَحَرَّكَ فَإِذَا أَصْبَحْتِ فَابْتَغِي سَهْمَيَّ فَخُذِيهِمَا لَا تَمْضُغُهُمَا عَلَيَّ الْكِلَابُ قَالَ وَأَمْهَلْنَاهُمْ حَتَّى ‏ ‏رَاحَتْ ‏ ‏رَائِحَتُهُمْ ‏ ‏حَتَّى إِذَا احْتَلَبُوا ‏ ‏وَعَطَنُوا ‏ ‏أَوْ سَكَنُوا ‏ ‏وَذَهَبَتْ عَتَمَةٌ مِنْ اللَّيْلِ ‏ ‏شَنَنَّا ‏ ‏عَلَيْهِمْ ‏ ‏الْغَارَةَ ‏ ‏فَقَتَلْنَا مَنْ قَتَلْنَا مِنْهُمْ وَاسْتَقْنَا النَّعَمَ فَتَوَجَّهْنَا ‏ ‏قَافِلِينَ ‏ ‏وَخَرَجَ ‏ ‏صَرِيخُ ‏ ‏الْقَوْمِ إِلَى قَوْمِهِمْ ‏ ‏مُغَوِّثًا ‏ ‏وَخَرَجْنَا سِرَاعًا حَتَّى نَمُرَّ ‏ ‏بِالْحَارِثِ ابْنِ الْبَرْصَاءِ ‏ ‏وَصَاحِبِهِ فَانْطَلَقْنَا بِهِ مَعَنَا وَأَتَانَا ‏ ‏صَرِيخُ ‏ ‏النَّاسِ فَجَاءَنَا مَا لَا قِبَلَ لَنَا بِهِ حَتَّى إِذَا لَمْ يَكُنْ بَيْنَنَا وَبَيْنَهُمْ إِلَّا ‏ ‏بَطْنُ الْوَادِي ‏ ‏أَقْبَلَ سَيْلٌ ‏ ‏حَالَ ‏ ‏بَيْنَنَا وَبَيْنَهُمْ بَعَثَهُ اللَّهُ تَعَالَى مِنْ حَيْثُ شَاءَ مَا رَأَيْنَا قَبْلَ ذَلِكَ مَطَرًا وَلَا حَالًا فَجَاءَ بِمَا لَا يَقْدِرُ أَحَدٌ أَنْ يَقُومَ عَلَيْهِ فَلَقَدْ رَأَيْنَاهُمْ وُقُوفًا يَنْظُرُونَ إِلَيْنَا مَا يَقْدِرُ أَحَدٌ مِنْهُمْ أَنْ يَتَقَدَّمَ وَنَحْنُ نُحَوِّزُهَا سِرَاعًا حَتَّى أَسْنَدْنَاهَا فِي ‏ ‏الْمَشْلَلِ ‏ ‏ثُمَّ حَدَرْنَاهَا عَنَّا فَأَعْجَزْنَا الْقَوْمَ بِمَا فِي أَيْدِينَا ‏","","",""],[15284,15284,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو نَعَامَةَ الْعَدَوِيُّ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ بُدَيْلٍ ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ زُهَيْرٍ ‏ ‏عَنْ ‏ ‏سُوَيْدِ بْنِ هُبَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ مَالِ الْمَرْءِ لَهُ ‏ ‏مُهْرَةٌ ‏ ‏مَأْمُورَةٌ أَوْ ‏ ‏سِكَّةٌ ‏ ‏مَأْبُورَةٌ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏فِي بَيْتِهِ ‏ ‏وَقِيلَ لَهُ إِنَّكَ قُلْتَ لَنَا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15285,15285,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَكِيمِ بْنِ حِزَامٍ ‏ ‏قَالَ ‏ ‏مَرَّ بِقَوْمٍ يُعَذَّبُونَ فِي الْجِزْيَةِ ‏ ‏بِفِلَسْطِينَ ‏ ‏قَالَ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُعَذِّبُ يَوْمَ الْقِيَامَةِ الَّذِينَ يُعَذِّبُونَ النَّاسَ فِي الدُّنْيَا ‏","","",""],[15286,15286,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاشِعِ بْنِ مَسْعُودٍ ‏ ‏أَنَّهُ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِابْنِ أَخٍ لَهُ يُبَايِعُهُ عَلَى الْهِجْرَةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا بَلْ ‏ ‏يُبَايِعُ ‏ ‏عَلَى الْإِسْلَامِ فَإِنَّهُ لَا هِجْرَةَ بَعْدَ الْفَتْحِ وَيَكُونُ مِنْ التَّابِعِينَ بِإِحْسَانٍ ‏","","",""],[15287,15287,"","","‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏مُجَاشِعِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ بِأَخِي ‏ ‏مَعْبَدٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ الْفَتْحِ فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏بَايِعْهُ ‏ ‏عَلَى الْهِجْرَةِ فَقَالَ ‏ ‏مَضَتْ الْهِجْرَةُ لِأَهْلِهَا قَالَ فَقُلْتُ فَمَاذَا قَالَ عَلَى الْإِسْلَامِ وَالْجِهَادِ ‏","","",""],[15288,15288,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ إِسْحَاقَ ‏ ‏أَنَّهُ أَخْبَرَهُ عَنْ ‏ ‏مُجَاشِعِ بْنِ مَسْعُودٍ الْبَهْزِيِّ ‏ ‏أَنَّهُ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِابْنِ أَخِيهِ لِيُبَايِعَهُ عَلَى الْهِجْرَةِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا بَلْ ‏ ‏يُبَايِعُ ‏ ‏عَلَى الْإِسْلَامِ فَإِنَّهُ لَا هِجْرَةَ بَعْدَ الْفَتْحِ قَالَ وَيَكُونُ مِنْ التَّابِعِينَ بِإِحْسَانٍ ‏","","",""],[15289,15289,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏مُجَاشِعِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ هَذَا ‏ ‏مُجَالِدُ بْنُ مَسْعُودٍ ‏ ‏يُبَايِعُكَ عَلَى الْهِجْرَةِ قَالَ ‏ ‏لَا هِجْرَةَ بَعْدَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏وَلَكِنْ أُبَايِعُهُ عَلَى الْإِسْلَامِ ‏","","",""],[15290,15290,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ بْنِ وَاقِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏مُجَاشِعٍ ‏ ‏قَالَ ‏ ‏قَدِمْتُ بِأَخِي ‏ ‏مَعْبَدٍ ‏ ‏عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ الْفَتْحِ فَقُلْتُ يَا رَسُولَ اللَّهِ جِئْتُكَ بِأَخِي لِتُبَايِعَهُ عَلَى الْهِجْرَةِ فَقَالَ ‏ ‏ذَهَبَ أَهْلُ الْهِجْرَةِ بِمَا فِيهَا فَقُلْتُ عَلَى أَيِّ شَيْءٍ ‏ ‏تُبَايِعُهُ ‏ ‏قَالَ عَلَى الْإِسْلَامِ وَالْإِيمَانِ وَالْجِهَادِ ‏ ‏قَالَ ‏ ‏فَلَقِيتُ ‏ ‏مَعْبَدًا ‏ ‏بَعْدُ وَكَانَ هُوَ أَكْبَرُهُمَا فَسَأَلْتُهُ ‏ ‏فَقَالَ ‏ ‏صَدَقَ ‏ ‏مُجَاشِعٌ ‏","","",""],[15291,15291,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ عَلْقَمَةَ اللَّيْثِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ الْحَارِثِ الْمُزَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الرَّجُلَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مِنْ رِضْوَانِ اللَّهِ عَزَّ وَجَلَّ مَا يَظُنُّ أَنْ تَبْلُغَ مَا بَلَغَتْ يَكْتُبُ اللَّهُ عَزَّ وَجَلَّ لَهُ بِهَا رِضْوَانَهُ إِلَى يَوْمِ الْقِيَامَةِ وَإِنَّ الرَّجُلَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مِنْ سَخَطِ اللَّهِ عَزَّ وَجَلَّ مَا يَظُنُّ أَنْ تَبْلُغَ مَا بَلَغَتْ يَكْتُبُ اللَّهُ عَزَّ وَجَلَّ بِهَا عَلَيْهِ سَخَطَهُ إِلَى يَوْمِ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏عَلْقَمَةُ ‏ ‏يَقُولُ ‏ ‏كَمْ مِنْ كَلَامٍ قَدْ مَنَعَنِيهِ حَدِيثُ ‏ ‏بِلَالِ بْنِ الْحَارِثِ ‏","","",""],[15292,15292,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏الْحَارِثِ بْنِ بِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏فَسْخُ الْحَجِّ لَنَا خَاصَّةً أَمْ لِلنَّاسِ عَامَّةً قَالَ بَلْ لَنَا خَاصَّةً ‏","","",""],[15293,15293,"","","‏ ‏حَدَّثَنِي ‏ ‏قُرَيْشُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ الدَّرَاوَرْدِيُّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏رَبِيعَةُ بْنُ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَارِثَ بْنَ بِلَالِ بْنِ الْحَارِثِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏يَا رَسُولَ اللَّهِ أَرَأَيْتَ ‏ ‏مُتْعَةَ ‏ ‏الْحَجِّ لَنَا خَاصَّةً أَمْ لِلنَّاسِ عَامَّةً فَقَالَ لَا بَلْ لَنَا خَاصَّةً ‏","","",""],[15294,15294,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَلَّامِ بْنِ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏حَبَّةَ ‏ ‏وَسَوَاءَ ‏ ‏ابْنَيْ ‏ ‏خَالِدٍ ‏ ‏قَالَا ‏ ‏دَخَلْنَا عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُصْلِحُ شَيْئًا فَأَعَنَّاهُ فَقَالَ ‏ ‏لَا ‏ ‏تَأْيَسَا مِنْ الرِّزْقِ مَا تَهَزَّزَتْ رُءُوسُكُمَا فَإِنَّ الْإِنْسَانَ تَلِدُهُ أُمُّهُ أَحْمَرَ لَيْسَ عَلَيْهِ قِشْرَةٌ ثُمَّ يَرْزُقُهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[15295,15295,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَلَّامٍ أَبِي شُرَحْبِيلَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حَبَّةَ ‏ ‏وَسَوَاءَ ‏ ‏ابْنَيْ ‏ ‏خَالِدٍ ‏ ‏يَقُولَانِ ‏ ‏أَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَعْمَلُ عَمَلًا ‏ ‏أَوْ يَبْنِي بِنَاءً ‏ ‏فَأَعَنَّاهُ عَلَيْهِ فَلَمَّا فَرَغَ دَعَا لَنَا وَقَالَ ‏ ‏لَا ‏ ‏تَأْيَسَا مِنْ الْخَيْرِ مَا تَهَزَّزَتْ رُءُوسُكُمَا إِنَّ الْإِنْسَانَ تَلِدُهُ أُمُّهُ أَحْمَرَ لَيْسَ عَلَيْهِ قِشْرَةٌ ثُمَّ يُعْطِيهِ اللَّهُ وَيَرْزُقُهُ ‏","","",""],[15296,15296,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ ‏ ‏جَلَسْتُ إِلَى رَهْطٍ أَنَا رَابِعُهُمْ ‏ ‏بِإِيلِيَاءَ ‏ ‏فَقَالَ أَحَدُهُمْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَدْخُلَنَّ الْجَنَّةَ بِشَفَاعَةِ رَجُلٍ مِنْ أُمَّتِي أَكْثَرُ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏قُلْنَا سِوَاكَ يَا رَسُولَ اللَّهِ قَالَ سِوَايَ قُلْتُ أَنْتَ سَمِعْتَهُ قَالَ نَعَمْ فَلَمَّا قَامَ قُلْتُ مَنْ هَذَا قَالُوا ‏ ‏ابْنُ أَبِي الْجَدْعَاءِ ‏","","",""],[15297,15297,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي الْجَدْعَاءِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَدْخُلَنَّ الْجَنَّةَ بِشَفَاعَةِ رَجُلٍ مِنْ أُمَّتِي أَكْثَرُ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ سِوَاكَ قَالَ سِوَايَ سِوَايَ ‏ ‏قُلْتُ أَنْتَ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَنَا سَمِعْتُهُ ‏","","",""],[15298,15298,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏قَالَ قَالَ ‏ ‏عُبَادَةُ بْنُ قُرْطٍ ‏ ‏إِنَّكُمْ لَتَأْتُونَ أُمُورًا هِيَ أَدَقُّ فِي أَعْيُنِكُمْ مِنْ الشَّعَرِ كُنَّا نَعُدُّهَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُوبِقَاتِ ‏ ‏قَالَ ‏ ‏فَذُكِرَ ذَلِكَ ‏ ‏لِمُحَمَّدِ بْنِ سِيرِينَ ‏ ‏فَقَالَ ‏ ‏صَدَقَ ‏ ‏وَأَرَى جَرَّ ‏ ‏الْإِزَارِ ‏ ‏مِنْهَا ‏","","",""],[15299,15299,"","","‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ الْمِقْدَامِ ‏ ‏وَمُحَمَّدُ بْنُ سَابِقٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي الْجُوَيْرِيَةِ ‏ ‏أَنَّ ‏ ‏مَعْنَ بْنَ يَزِيدَ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏بَايَعْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا وَأَبِي وَجَدِّي وَخَطَبَ عَلَيَّ فَأَنْكَحَنِي وَخَاصَمْتُ إِلَيْهِ فَكَانَ ‏ ‏أَبِي يَزِيدُ ‏ ‏خَرَجَ بِدَنَانِيرَ يَتَصَدَّقُ بِهَا فَوَضَعَهَا عِنْدَ رَجُلٍ فِي الْمَسْجِدِ فَأَخَذْتُهَا فَأَتَيْتُهُ بِهَا فَقَالَ وَاللَّهِ مَا إِيَّاكَ أَرَدْتُ بِهَا فَخَاصَمْتُهُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَكَ مَا نَوَيْتَ يَا ‏ ‏يَزِيدُ ‏ ‏وَلَكَ يَا ‏ ‏مَعْنُ ‏ ‏مَا أَخَذْتَ ‏","","",""],[15300,15300,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُهَيْلُ بْنُ ذِرَاعٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏مَعْنَ بْنَ يَزِيدَ ‏ ‏أَوْ ‏ ‏أَبَا مَعْنٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْتَمِعُوا فِي مَسَاجِدِكُمْ فَإِذَا اجْتَمَعَ قَوْمٌ فَلْيُؤْذِنُونِي قَالَ فَاجْتَمَعْنَا أَوَّلَ النَّاسِ فَأَتَيْنَاهُ فَجَاءَ يَمْشِي مَعَنَا حَتَّى جَلَسَ إِلَيْنَا فَتَكَلَّمَ مُتَكَلِّمٌ مِنَّا فَقَالَ الْحَمْدُ لِلَّهِ الَّذِي لَيْسَ لِلْحَمْدِ دُونَهُ مُقْتَصَرٌ وَلَيْسَ وَرَاءَهُ مَنْفَذٌ وَنَحْوًا مِنْ هَذَا فَغَضِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ فَتَلَاوَمْنَا وَلَامَ بَعْضُنَا بَعْضًا فَقُلْنَا خَصَّنَا اللَّهُ بِهِ أَنْ أَتَانَا أَوَّلَ النَّاسِ وَأَنْ فَعَلَ وَفَعَلَ قَالَ فَأَتَيْنَاهُ فَوَجَدْنَاهُ فِي مَسْجِدِ بَنِي فُلَانٍ فَكَلَّمْنَاهُ فَأَقْبَلَ يَمْشِي مَعَنَا حَتَّى جَلَسَ فِي مَجْلِسِهِ الَّذِي كَانَ فِيهِ ‏ ‏أَوْ قَرِيبًا مِنْهُ ‏ ‏ثُمَّ قَالَ ‏ ‏إِنَّ الْحَمْدَ لِلَّهِ مَا شَاءَ اللَّهُ جَعَلَ بَيْنَ يَدَيْهِ وَمَا شَاءَ جَعَلَ خَلْفَهُ وَإِنَّ مِنْ ‏ ‏الْبَيَانِ ‏ ‏سِحْرًا ثُمَّ أَقْبَلَ عَلَيْنَا فَأَمَرَنَا وَكَلَّمَنَا وَعَلَّمَنَا ‏","","",""],[15301,15301,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ كُلَيْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الْجُوَيْرِيَةِ ‏ ‏قَالَ ‏ ‏أَصَبْتُ ‏ ‏جَرَّةً ‏ ‏حَمْرَاءَ فِيهَا دَنَانِيرُ فِي إِمَارَةِ ‏ ‏مُعَاوِيَةَ ‏ ‏فِي أَرْضِ ‏ ‏الرُّومِ ‏ ‏قَالَ وَعَلَيْنَا رَجُلٌ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏يُقَالُ لَهُ ‏ ‏مَعْنُ بْنُ يَزِيدَ ‏ ‏قَالَ فَأَتَيْتُ بِهَا يَقْسِمُهَا بَيْنَ الْمُسْلِمِينَ فَأَعْطَانِي مِثْلَ مَا أَعْطَى رَجُلًا مِنْهُمْ ثُمَّ قَالَ لَوْلَا أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَأَيْتُهُ يَفْعَلُهُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏نَفْلَ ‏ ‏إِلَّا بَعْدَ ‏ ‏الْخُمُسِ ‏ ‏إِذًا لَأَعْطَيْتُكَ قَالَ ثُمَّ أَخَذَ فَعَرَضَ عَلَيَّ مِنْ نَصِيبِهِ فَأَبَيْتُ عَلَيْهِ قُلْتُ مَا أَنَا بِأَحَقَّ بِهِ مِنْكَ ‏","","",""],[15302,15302,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏وَسُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْجُوَيْرِيَةِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْجُوَيْرِيَةِ ‏ ‏عَنْ ‏ ‏مَعْنِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏بَايَعْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا وَأَبِي وَجَدِّي وَخَاصَمْتُ إِلَيْهِ ‏ ‏فَأَفْلَجَنِي وَخَطَبَ عَلَيَّ فَأَنْكَحَنِي ‏","","",""],[15303,15303,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي مَرَرْتُ بِأَخٍ لِي مِنْ ‏ ‏بَنِي قُرَيْظَةَ ‏ ‏فَكَتَبَ لِي ‏ ‏جَوَامِعَ ‏ ‏مِنْ التَّوْرَاةِ أَلَا أَعْرِضُهَا عَلَيْكَ قَالَ فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَقُلْتُ لَهُ أَلَا ‏ ‏تَرَى ‏ ‏مَا بِوَجْهِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِينَا بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَسُولًا قَالَ ‏ ‏فَسُرِّيَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَوْ أَصْبَحَ فِيكُمْ ‏ ‏مُوسَى ‏ ‏ثُمَّ اتَّبَعْتُمُوهُ وَتَرَكْتُمُونِي لَضَلَلْتُمْ إِنَّكُمْ حَظِّي مِنْ الْأُمَمِ وَأَنَا حَظُّكُمْ مِنْ النَّبِيِّينَ ‏","","",""],[15304,15304,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏جُهَيْنَةَ ‏ ‏قَالَ ‏ ‏سَمِعَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ يَا حَرَامُ فَقَالَ يَا حَلَالُ ‏","","",""],[15305,15305,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِصَامُ بْنُ قُدَامَةَ الْبَجَلِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكُ بْنُ نُمَيْرٍ الْخُزَاعِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏قَاعِدٌ فِي الصَّلَاةِ قَدْ وَضَعَ ذِرَاعَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى رَافِعًا بِأُصْبُعِهِ السَّبَّابَةِ قَدْ حَنَاهَا شَيْئًا وَهُوَ يَدْعُو ‏","","",""],[15306,15306,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عِصَامُ بْنُ قُدَامَةَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ نُمَيْرٍ الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاضِعًا يَدَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى فِي الصَّلَاةِ يُشِيرُ بِأُصْبُعِهِ ‏","","",""],[15307,15307,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْرَائِيلَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَعْدَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَأَى رَجُلًا سَمِينًا فَجَعَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُومِئُ ‏ ‏إِلَى بَطْنِهِ بِيَدِهِ وَيَقُولُ ‏ ‏لَوْ كَانَ هَذَا فِي غَيْرِ هَذَا الْمَكَانِ لَكَانَ خَيْرًا لَكَ ‏","","",""],[15308,15308,"","","‏ ‏قَالَ ‏ ‏وَأُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَجُلٍ فَقَالُوا هَذَا أَرَادَ أَنْ يَقْتُلَكَ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ ‏ ‏تُرَعْ ‏ ‏لَمْ ‏ ‏تُرَعْ ‏ ‏وَلَوْ أَرَدْتَ ذَلِكَ لَمْ يُسَلِّطْكَ اللَّهُ عَلَيَّ ‏","","",""],[15309,15309,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْرَائِيلَ ‏ ‏فِي بَيْتِ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَعْدَةَ ‏ ‏وَهُوَ مَوْلَى ‏ ‏أَبِي إِسْرَائِيلَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَجُلٌ ‏ ‏يَقُصُّ عَلَيْهِ رُؤْيَا وَذَكَرَ سِمَنَهُ وَعِظَمَهُ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كَانَ هَذَا فِي غَيْرِ هَذَا كَانَ خَيْرًا لَكَ ‏","","",""],[15310,15310,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ صَفْوَانَ ‏ ‏أَنَّهُ صَادَ أَرْنَبَيْنِ فَلَمْ يَجِدْ حَدِيدَةً يَذْبَحُهُمَا بِهَا فَذَبَحَهُمَا ‏ ‏بِمَرْوَةٍ ‏ ‏فَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُ بِأَكْلِهِمَا ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏دَاوُدُ يَعْنِي ابْنَ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ صَفْوَانَ ‏ ‏أَنَّهُ مَرَّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَرْنَبَيْنِ مُعَلِّقُهُمَا ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[15311,15311,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي رَوْحٍ الْكَلَاعِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةً فَقَرَأَ فِيهَا سُورَةَ ‏ ‏الرُّومِ ‏ ‏فَلَبَسَ ‏ ‏عَلَيْهِ ‏ ‏بَعْضُهَا قَالَ ‏ ‏إِنَّمَا لَبَسَ عَلَيْنَا الشَّيْطَانُ الْقِرَاءَةَ مِنْ أَجْلِ أَقْوَامٍ يَأْتُونَ الصَّلَاةَ بِغَيْرِ وُضُوءٍ فَإِذَا أَتَيْتُمْ الصَّلَاةَ فَأَحْسِنُوا الْوُضُوءَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شَبِيبًا أَبَا رَوْحٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ صَلَّى الصُّبْحَ فَقَرَأَ فِيهَا ‏ ‏الرُّومَ ‏ ‏فَأَوْهَمَ ‏ ‏فَذَكَرَهُ ‏","","",""],[15312,15312,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شَبِيبًا أَبَا رَوْحٍ ‏ ‏مِنْ ‏ ‏ذِي الْكَلَاعِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏أَنَّهُ صَلَّى مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصُّبْحَ فَقَرَأَ ‏ ‏بِالرُّومِ ‏ ‏فَتَرَدَّدَ فِي آيَةٍ فَلَمَّا انْصَرَفَ قَالَ ‏ ‏إِنَّهُ ‏ ‏يَلْبِسُ ‏ ‏عَلَيْنَا الْقُرْآنَ أَنَّ أَقْوَامًا مِنْكُمْ يُصَلُّونَ مَعَنَا لَا يُحْسِنُونَ الْوُضُوءَ فَمَنْ شَهِدَ الصَّلَاةَ مَعَنَا فَلْيُحْسِنْ الْوُضُوءَ ‏","","",""],[15313,15313,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو مَالِكٍ الْأَشْجَعِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ لِقَوْمٍ ‏ ‏مَنْ وَحَّدَ اللَّهَ تَعَالَى وَكَفَرَ بِمَا يُعْبَدُ مِنْ دُونِهِ حَرُمَ مَالُهُ وَدَمُهُ وَحِسَابُهُ عَلَى اللَّهِ عَزَّ وَجَلَّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا بِهِ ‏ ‏يَزِيدُ ‏ ‏بِوَاسِطٍ ‏ ‏وَبَغْدَادَ ‏ ‏قَالَ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15314,15314,"","","‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏بِبَغْدَادَ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو مَالِكٍ الْأَشْجَعِيُّ سَعْدُ بْنُ طَارِقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بِحَسْبِ ‏ ‏أَصْحَابِي الْقَتْلُ ‏","","",""],[15315,15315,"","","‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو مَالِكٍ الْأَشْجَعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِذَا أَتَاهُ الْإِنْسَانُ يَقُولُ ‏ ‏كَيْفَ يَا رَسُولَ اللَّهِ أَقُولُ حِينَ أَسْأَلُ رَبِّي قَالَ قُلْ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَاهْدِنِي وَارْزُقْنِي وَقَبَضَ أَصَابِعَهُ الْأَرْبَعَ إِلَّا الْإِبْهَامَ فَإِنَّ هَؤُلَاءِ يَجْمَعْنَ لَكَ دُنْيَاكَ وَآخِرَتَكَ ‏","","",""],[15316,15316,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُهُ يَقُولُ لِلْقَوْمِ ‏ ‏مَنْ وَحَّدَ اللَّهَ وَكَفَرَ بِمَا يُعْبَدُ مِنْ دُونِهِ حَرُمَ مَالُهُ وَدَمُهُ وَحِسَابُهُ عَلَى اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[15317,15317,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو مَالِكٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي ‏ ‏يَا ‏ ‏أَبَتِ إِنَّكَ قَدْ ‏ ‏صَلَّيْتَ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏وَعَلِيٍّ ‏ ‏هَاهُنَا ‏ ‏بِالْكُوفَةِ ‏ ‏قَرِيبًا مِنْ خَمْسِ سِنِينَ أَكَانُوا ‏ ‏يَقْنُتُونَ ‏ ‏قَالَ أَيْ بُنَيَّ مُحْدَثٌ ‏","","",""],[15318,15318,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ يَعْنِي ابْنَ خَلِيفَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَالِكٍ الْأَشْجَعِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي ‏","","",""],[15319,15319,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ يَعْنِي ابْنَ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَالِكٍ الْأَشْجَعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي طَارِقُ بْنُ أَشْيَمَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُ مَنْ أَسْلَمَ يَقُولُ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَارْزُقْنِي وَهُوَ يَقُولُ هَؤُلَاءِ يَجْمَعْنَ لَكَ خَيْرَ الدُّنْيَا وَالْآخِرَةِ ‏","","",""],[15320,15320,"","","‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عِيسَى أَبُو بِشْرٍ الْبَصْرِيُّ الرَّاسِبِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَالِكٍ الْأَشْجَعِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏وَسَأَلْتُهُ ‏ ‏فَقَالَ ‏ ‏كَانَ ‏ ‏خِضَابُنَا ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَرْسَ ‏ ‏وَالزَّعْفَرَانَ ‏","","",""],[15321,15321,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ حَسَّانَ يَعْنِي الْمُسْلِيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُغِيرَةُ بْنُ عَبْدِ اللَّهِ الْيَشْكُرِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَسْجِدَ ‏ ‏الْكُوفَةِ ‏ ‏أَوَّلَ مَا بُنِيَ مَسْجِدُهَا وَهُوَ فِي أَصْحَابِ التَّمْرِ يَوْمَئِذٍ وَجُدُرُهُ مِنْ ‏ ‏سِهْلَةٍ ‏ ‏فَإِذَا ‏ ‏رَجُلٌ ‏ ‏يُحَدِّثُ النَّاسَ قَالَ بَلَغَنِي حَجَّةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَجَّةُ الْوَدَاعِ فَاسْتَتْبَعْتُ رَاحِلَةً مِنْ إِبِلِي ثُمَّ خَرَجْتُ حَتَّى جَلَسْتُ لَهُ فِي طَرِيقِ ‏ ‏عَرَفَةَ ‏ ‏أَوْ وَقَفْتُ لَهُ فِي طَرِيقِ ‏ ‏عَرَفَةَ ‏ ‏قَالَ فَإِذَا رَكْبٌ عَرَفْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِمْ بِالصِّفَةِ فَقَالَ رَجُلٌ أَمَامَهُ ‏ ‏خَلِّ ‏ ‏لِي عَنْ طَرِيقِ الرِّكَابِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْحَهُ ‏ ‏فَأَرَبٌ ‏ ‏مَا لَهُ فَدَنَوْتُ مِنْهُ حَتَّى اخْتَلَفَتْ رَأْسُ النَّاقَتَيْنِ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ دُلَّنِي عَلَى عَمَلٍ يُدْخِلُنِي الْجَنَّةَ ‏ ‏وَيُنْجِينِي مِنْ النَّارِ قَالَ ‏ ‏بَخٍ ‏ ‏بَخٍ ‏ ‏لَئِنْ كُنْتَ قَصَّرْتَ فِي الْخُطْبَةِ لَقَدْ أَبْلَغْتَ فِي الْمَسْأَلَةِ افْقَهْ إِذًا ‏ ‏تَعْبُدُ اللَّهَ عَزَّ وَجَلَّ لَا تُشْرِكُ بِهِ شَيْئًا وَتُقِيمُ الصَّلَاةَ وَتُؤَدِّي الزَّكَاةَ وَتَحُجُّ ‏ ‏الْبَيْتَ ‏ ‏وَتَصُومُ رَمَضَانَ ‏ ‏خَلِّ ‏ ‏طَرِيقَ الرِّكَابِ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏هَذَا الْحَدِيثَ مِنْ ‏ ‏الْمُغِيرَةِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏نَحْوَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏انْتَهَيْتُ إِلَى ‏ ‏رَجُلٍ ‏ ‏يُحَدِّثُ قَوْمًا فَجَلَسْتُ ‏ ‏فَقَالَ وُصِفَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏بِمِنًى ‏ ‏غَادِيًا إِلَى ‏ ‏عَرَفَاتٍ ‏ ‏فَذَكَرَ الْحَدِيثَ فَقُلْتُ يَا رَسُولَ اللَّهِ خَبِّرْنِي بِعَمَلٍ يُقَرِّبُنِي مِنْ الْجَنَّةِ وَيُبَاعِدُنِي مِنْ النَّارِ قَالَ تُقِيمُ الصَّلَاةَ وَتُؤْتِي الزَّكَاةَ وَتَحُجُّ ‏ ‏الْبَيْتَ ‏ ‏وَتَصُومُ رَمَضَانَ وَتُحِبُّ لِلنَّاسِ مَا تُحِبُّ أَنْ يُؤْتَى إِلَيْكَ وَتَكْرَهُ لَهُمْ مَا تَكْرَهُ أَنْ يُؤْتَى إِلَيْكَ ‏ ‏خَلِّ ‏ ‏عَنْ وُجُوهِ الرِّكَابِ ‏","","",""],[15322,15322,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مُرَّةَ الطَّيِّبِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غُرْفَتِي هَذِهِ حَسِبْتُ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏عَلَى نَاقَةٍ لَهُ حَمْرَاءَ مُخَضْرَمَةٍ فَقَالَ ‏ ‏هَذَا ‏ ‏يَوْمُ النَّحْرِ ‏ ‏وَهَذَا يَوْمُ الْحَجِّ الْأَكْبَرِ ‏","","",""],[15323,15323,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ الْجُشَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَآنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيَّ ‏ ‏أَطْمَارٌ ‏ ‏فَقَالَ هَلْ لَكَ مَالٌ قُلْتُ نَعَمْ قَالَ مِنْ أَيِّ الْمَالِ قُلْتُ مِنْ كُلِّ الْمَالِ قَدْ آتَانِي اللَّهُ عَزَّ وَجَلَّ مِنْ الشَّاءِ وَالْإِبِلِ قَالَ فَلْتُرَ نِعَمُ اللَّهِ وَكَرَامَتُهُ عَلَيْكَ ‏ ‏فَذَكَرَ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْأَحْوَصِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏قَشِفُ ‏ ‏الْهَيْئَةِ فَقَالَ هَلْ لَكَ مَالٌ قَالَ قُلْتُ نَعَمْ قَالَ مِنْ أَيِّ الْمَالِ قَالَ قُلْتُ مِنْ كُلِّ الْمَالِ مِنْ الْإِبِلِ ‏ ‏وَالرَّقِيقِ ‏ ‏وَالْخَيْلِ وَالْغَنَمِ فَقَالَ ‏ ‏إِذَا آتَاكَ اللَّهُ مَالًا فَلْيُرَ عَلَيْكَ ثُمَّ قَالَ هَلْ ‏ ‏تُنْتِجُ ‏ ‏إِبِلُ قَوْمِكَ صِحَاحًا آذَانُهَا فَتَعْمَدُ إِلَى مُوسَى فَتَقْطَعُ آذَانَهَا فَتَقُولُ هَذِهِ بُحُرٌ وَتَشُقُّهَا ‏ ‏أَوْ تَشُقُّ جُلُودَهَا ‏ ‏وَتَقُولُ هَذِهِ ‏ ‏صُرُمٌ ‏ ‏وَتُحَرِّمُهَا عَلَيْكَ وَعَلَى أَهْلِكَ قَالَ نَعَمْ قَالَ فَإِنَّ مَا آتَاكَ اللَّهُ عَزَّ وَجَلَّ لَكَ وَسَاعِدُ اللَّهِ أَشَدُّ وَمُوسَى اللَّهِ أَحَدُّ ‏ ‏وَرُبَّمَا قَالَ سَاعِدُ اللَّهِ أَشَدُّ مِنْ سَاعِدِكَ وَمُوسَى اللَّهِ أَحَدُّ مِنْ مُوسَاكَ ‏ ‏قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ أَرَأَيْتَ رَجُلًا نَزَلْتُ بِهِ فَلَمْ يُكْرِمْنِي وَلَمْ ‏ ‏يَقْرِنِي ‏ ‏ثُمَّ نَزَلَ بِي ‏ ‏أَجْزِيهِ بِمَا صَنَعَ أَمْ ‏ ‏أَقْرِيهِ ‏ ‏قَالَ ‏ ‏اقْرِهِ ‏","","",""],[15324,15324,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏وَإِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ لَكَ مِنْ مَالٍ قَالَ قُلْتُ نَعَمْ مِنْ كُلِّ الْمَالِ قَدْ آتَانِي اللَّهُ عَزَّ وَجَلَّ مِنْ الْإِبِلِ وَمِنْ الْخَيْلِ وَالرَّقِيقِ قَالَ ‏ ‏فَإِذَا آتَاكَ اللَّهُ عَزَّ وَجَلَّ خَيْرًا فَلْيُرَ عَلَيْكَ ‏","","",""],[15325,15325,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ بْنُ حُمَيْدٍ أَبُو عَبْدِ الرَّحْمَنِ التَّيْمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الزَّعْرَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏مَالِكِ بْنِ نَضْلَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَيْدِي ثَلَاثَةٌ فَيَدُ اللَّهِ الْعُلْيَا وَيَدُ الْمُعْطِي الَّتِي تَلِيهَا وَيَدُ السَّائِلِ السُّفْلَى فَأَعْطِ الْفَضْلَ وَلَا تَعْجَزْ عَنْ نَفْسِكَ ‏","","",""],[15326,15326,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏أَنْبَأَنَا قَالَ سَمِعْتُ ‏ ‏أَبَا الْأَحْوَصِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏قَشِيفُ ‏ ‏الْهَيْئَةِ فَقَالَ هَلْ لَكَ مَالٌ قَالَ قُلْتُ نَعَمْ قَالَ فَمَا مَالُكَ فَقَالَ مِنْ كُلِّ الْمَالِ مِنْ الْخَيْلِ وَالْإِبِلِ وَالرَّقِيقِ وَالْغَنَمِ قَالَ ‏ ‏فَإِذَا آتَاكَ اللَّهُ عَزَّ وَجَلَّ مَالًا فَلْيُرَ عَلَيْكَ فَقَالَ هَلْ ‏ ‏تُنْتِجُ ‏ ‏إِبِلُ قَوْمِكَ صِحَاحًا آذَانُهَا فَتَعْمَدُ إِلَى الْمُوسَى فَتَقْطَعُهَا ‏ ‏أَوْ تَقْطَعُهَا ‏ ‏وَتَقُولُ هَذِهِ بُحُرٌ وَتَشُقُّ جُلُودَهَا وَتَقُولُ هَذِهِ ‏ ‏صُرُمٌ ‏ ‏فَتُحَرِّمُهَا عَلَيْكَ وَعَلَى أَهْلِكَ قَالَ قُلْتُ نَعَمْ قَالَ كُلُّ مَا آتَاكَ اللَّهُ عَزَّ وَجَلَّ لَكَ ‏ ‏حِلٌّ ‏ ‏وَسَاعِدُ اللَّهِ أَشَدُّ وَمُوسَى اللَّهِ أَحَدُّ ‏ ‏وَرُبَّمَا قَالَهَا وَرُبَّمَا لَمْ يَقُلْهَا وَرُبَّمَا قَالَ سَاعِدُ اللَّهِ أَشَدُّ مِنْ سَاعِدِكَ وَمُوسَى اللَّهِ أَحَدُّ مِنْ مُوسَاكَ ‏ ‏قَالَ قُلْتُ يَا رَسُولَ اللَّهِ رَجُلٌ نَزَلْتُ بِهِ فَلَمْ ‏ ‏يَقْرِنِي ‏ ‏وَلَمْ يُكْرِمْنِي ثُمَّ نَزَلَ بِي ‏ ‏أَقْرِيهِ ‏ ‏أَوْ ‏ ‏أَجْزِيهِ بِمَا صَنَعَ قَالَ بَلْ ‏ ‏اقْرِهِ ‏","","",""],[15327,15327,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏أَشْعَثُ ‏ ‏سَيِّئُ الْهَيْئَةِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا لَكَ مَالٌ قَالَ مِنْ كُلِّ الْمَالِ قَدْ آتَانِي اللَّهُ عَزَّ وَجَلَّ قَالَ ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ إِذَا أَنْعَمَ عَلَى عَبْدٍ نِعْمَةً أَحَبَّ أَنْ تُرَى عَلَيْهِ ‏","","",""],[15328,15328,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ يَعْنِي إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏رَجُلٍ ‏ ‏وَهُوَ ‏ ‏يَتَمَجَّعُ ‏ ‏لَبَنًا بِتَمْرٍ فَقَالَ ادْنُ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمَّاهُمَا الْأَطْيَبَيْنِ ‏","","",""],[15329,15329,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏زَاذَانَ أَبِي عُمَرَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏لُقِّنَ ‏ ‏عِنْدَ الْمَوْتِ لَا إِلَهَ إِلَّا اللَّهُ دَخَلَ الْجَنَّةَ ‏","","",""],[15330,15330,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ يَعْنِي ابْنَ السَّائِبِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَكْرِ بْنِ وَائِلٍ ‏ ‏عَنْ ‏ ‏خَالِهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَعْشِرُ ‏ ‏قَوْمِي قَالَ ‏ ‏إِنَّمَا ‏ ‏الْعُشُورُ ‏ ‏عَلَى ‏ ‏الْيَهُودِ ‏ ‏وَالنَّصَارَى ‏ ‏وَلَيْسَ عَلَى أَهْلِ الْإِسْلَامِ ‏ ‏عُشُورٌ ‏","","",""],[15331,15331,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏حَرْبِ بْنِ عُبَيْدِ اللَّهِ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏خَالِهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ لَهُ أَشْيَاءَ فَسَأَلَهُ فَقَالَ ‏ ‏أَعْشِرُهَا ‏ ‏فَقَالَ ‏ ‏إِنَّمَا ‏ ‏الْعُشُورُ ‏ ‏عَلَى ‏ ‏الْيَهُودِ ‏ ‏وَالنَّصَارَى ‏ ‏وَلَيْسَ عَلَى أَهْلِ الْإِسْلَامِ ‏ ‏عُشُورٌ ‏","","",""],[15332,15332,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏حَرْبِ بْنِ هِلَالٍ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمِّهِ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي تَغْلِبَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيْسَ عَلَى الْمُسْلِمِينَ ‏ ‏عُشُورٌ ‏ ‏إِنَّمَا ‏ ‏الْعُشُورُ ‏ ‏عَلَى ‏ ‏الْيَهُودِ ‏ ‏وَالنَّصَارَى ‏","","",""],[15333,15333,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِرَجُلٍ ‏ ‏كَيْفَ تَقُولُ فِي الصَّلَاةِ قَالَ أَتَشَهَّدُ ثُمَّ أَقُولُ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنْ النَّارِ أَمَا إِنِّي لَا أُحْسِنُ ‏ ‏دَنْدَنَتَكَ ‏ ‏وَلَا ‏ ‏دَنْدَنَةَ ‏ ‏مُعَاذٍ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَوْلَهَا ‏ ‏نُدَنْدِنُ ‏","","",""],[15334,15334,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ مَيْسَرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏كُرْدُوسًا ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ أَصْحَابِ ‏ ‏بَدْرٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَأَنْ أَقْعُدَ فِي مِثْلِ هَذَا الْمَجْلِسِ أَحَبُّ إِلَيَّ مِنْ أَنْ أُعْتِقَ أَرْبَعَ رِقَابٍ ‏","","",""],[15335,15335,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏كُرْدُوسَ بْنَ قَيْسٍ ‏ ‏وَكَانَ ‏ ‏قَاصَّ ‏ ‏الْعَامَّةِ ‏ ‏بِالْكُوفَةِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ أَصْحَابِ ‏ ‏بَدْرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَأَنْ أَقْعُدَ فِي مِثْلِ هَذَا الْمَجْلِسِ أَحَبُّ إِلَيَّ مِنْ أَنْ أُعْتِقَ أَرْبَعَ رِقَابٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَقُلْتُ أَيَّ مَجْلِسٍ تَعْنِي ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏قَاصًّا ‏","","",""],[15336,15336,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْجَوَّابِ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ رُزَيْقٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَفَرٌ مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏مِنْهُمْ ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ سِنَانٍ الْأَشْجَعِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَرَّ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏أَحْتَجِمُ ‏ ‏فِي ثَمَانِ عَشْرَةَ لَيْلَةً خَلَتْ مِنْ شَهْرِ رَمَضَانَ فَقَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[15337,15337,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَلِمَةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏تَأْتِينَا ‏ ‏الرُّكْبَانُ ‏ ‏مِنْ قِبَلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَسْتَقْرِئُهُمْ فَيُحَدِّثُونَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِيَؤُمَّكُمْ أَكْثَرُكُمْ قُرْآنًا ‏","","",""],[15338,15338,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ النَّاسَ بِالْفِطْرِ عَامَ الْفَتْحِ وَقَالَ تَقَوَّوْا لِعَدُوِّكُمْ وَصَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏قَالَ الَّذِي حَدَّثَنِي لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْعَرْجِ ‏ ‏يَصُبُّ عَلَى رَأْسِهِ الْمَاءَ مِنْ الْعَطَشِ ‏ ‏أَوْ مِنْ الْحَرِّ ‏ ‏ثُمَّ قِيلَ يَا رَسُولَ اللَّهِ إِنَّ طَائِفَةً مِنْ النَّاسِ قَدْ صَامُوا حِينَ صُمْتَ فَلَمَّا كَانَ ‏ ‏بِالْكَدِيدِ ‏ ‏دَعَا ‏ ‏بِقَدَحٍ ‏ ‏فَشَرِبَ فَأَفْطَرَ النَّاسُ ‏","","",""],[15339,15339,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدٌ يَعْنِي ابْنَ أَوْسٍ الْعَبْسِيَّ ‏ ‏عَنْ ‏ ‏بِلَالٍ الْعَبْسِيِّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ الضَّبِّيُّ ‏ ‏أَنَّهُ أَتَى ‏ ‏الْبَصْرَةَ ‏ ‏وَبِهَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏أَمِيرًا فَإِذَا هُوَ ‏ ‏بِرَجُلٍ ‏ ‏قَائِمٍ فِي ظِلِّ الْقَصْرِ يَقُولُ صَدَقَ اللَّهُ وَرَسُولُهُ صَدَقَ اللَّهُ وَرَسُولُهُ لَا يَزِيدُ عَلَى ذَلِكَ فَدَنَوْتُ مِنْهُ شَيْئًا فَقُلْتُ لَهُ لَقَدْ أَكْثَرْتَ مِنْ قَوْلِكَ صَدَقَ اللَّهُ وَرَسُولُهُ فَقَالَ أَمَا وَاللَّهِ لَئِنْ شِئْتَ لَأَخْبَرْتُكَ فَقُلْتُ أَجَلْ فَقَالَ اجْلِسْ إِذًا فَقَالَ إِنِّي أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِالْمَدِينَةِ ‏ ‏فِي زَمَانِ كَذَا وَكَذَا وَقَدْ كَانَ شَيْخَانِ لِلْحَيِّ قَدْ انْطَلَقَ ابْنٌ لَهُمَا فَلَحِقَ بِهِ فَقَالَا إِنَّكَ قَادِمٌ ‏ ‏الْمَدِينَةَ ‏ ‏وَإِنَّ ابْنًا لَنَا قَدْ لَحِقَ بِهَذَا الرَّجُلِ فَأْتِهِ فَاطْلُبْهُ مِنْهُ فَإِنْ أَبَى إِلَّا ‏ ‏الِافْتِدَاءَ فَافْتَدِهِ فَأَتَيْتُ ‏ ‏الْمَدِينَةَ ‏ ‏فَدَخَلْتُ عَلَى نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا نَبِيَّ اللَّهِ إِنَّ شَيْخَيْنِ لِلْحَيِّ أَمَرَانِي أَنْ أَطْلُبَ ابْنًا لَهُمَا عِنْدَكَ فَقَالَ تَعْرِفُهُ فَقَالَ أَعْرِفُ نَسَبَهُ فَدَعَا الْغُلَامَ فَجَاءَ فَقَالَ هُوَ ذَا فَأْتِ بِهِ أَبَوَيْهِ فَقُلْتُ الْفِدَاءَ يَا نَبِيَّ اللَّهِ قَالَ ‏ ‏إِنَّهُ لَا يَصْلُحُ لَنَا آلُ ‏ ‏مُحَمَّدٍ ‏ ‏أَنْ نَأْكُلَ ثَمَنَ أَحَدٍ مِنْ وَلَدِ ‏ ‏إِسْمَاعِيلَ ‏ ‏ثُمَّ ضَرَبَ عَلَى كَتِفِي ثُمَّ قَالَ لَا أَخْشَى عَلَى ‏ ‏قُرَيْشٍ ‏ ‏إِلَّا أَنْفُسَهَا قُلْتُ وَمَا لَهُمْ يَا نَبِيَّ اللَّهِ قَالَ إِنْ طَالَ بِكَ الْعُمُرُ رَأَيْتَهُمْ هَاهُنَا حَتَّى ‏ ‏تَرَى النَّاسَ بَيْنَهُمَا كَالْغَنَمِ بَيْنَ حَوْضَيْنِ مَرَّةً إِلَى هَذَا وَمَرَّةً إِلَى هَذَا ‏ ‏فَأَنَا أَرَى نَاسًا يَسْتَأْذِنُونَ عَلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَأَيْتُهُمْ الْعَامَ يَسْتَأْذِنُونَ عَلَى ‏ ‏مُعَاوِيَةَ ‏ ‏فَذَكَرْتُ مَا قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15340,15340,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ وَهُوَ أَبُو شُجَاعٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَارِثَ بْنَ يَزِيدَ الْحَضْرَمِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَلِيِّ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏نَاشِرَةَ بْنِ سُمَيٍّ الْيَزَنِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏يَقُولُ فِي يَوْمِ ‏ ‏الْجَابِيَةِ ‏ ‏وَهُوَ يَخْطُبُ النَّاسَ إِنَّ اللَّهَ عَزَّ وَجَلَّ جَعَلَنِي خَازِنًا لِهَذَا الْمَالِ وَقَاسِمَهُ لَهُ ثُمَّ قَالَ بَلْ اللَّهُ يَقْسِمُهُ وَأَنَا بَادِئٌ بِأَهْلِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ أَشْرَفِهِمْ فَفَرَضَ لِأَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشْرَةَ آلَافٍ إِلَّا ‏ ‏جُوَيْرِيَةَ ‏ ‏وَصَفِيَّةَ ‏ ‏ومَيْمُونَةَ ‏ ‏فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَعْدِلُ بَيْنَنَا فَعَدَلَ بَيْنَهُنَّ ‏ ‏عُمَرُ ‏ ‏ثُمَّ قَالَ إِنِّي بَادِئٌ بِأَصْحَابِي ‏ ‏الْمُهَاجِرِينَ ‏ ‏الْأَوَّلِينَ فَإِنَّا أُخْرِجْنَا مِنْ دِيَارِنَا ظُلْمًا وَعُدْوَانًا ثُمَّ أَشْرَفِهِمْ فَفَرَضَ لِأَصْحَابِ ‏ ‏بَدْرٍ ‏ ‏مِنْهُمْ خَمْسَةَ آلَافٍ وَلِمَنْ كَانَ شَهِدَ ‏ ‏بَدْرًا ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَرْبَعَةَ آلَافٍ وَلِمَنْ شَهِدَ ‏ ‏أُحُدًا ‏ ‏ثَلَاثَةَ آلَافٍ قَالَ وَمَنْ أَسْرَعَ فِي الْهِجْرَةِ أَسْرَعَ بِهِ الْعَطَاءُ وَمَنْ أَبْطَأَ فِي الْهِجْرَةِ أَبْطَأَ بِهِ الْعَطَاءُ فَلَا يَلُومَنَّ رَجُلٌ إِلَّا ‏ ‏مُنَاخَ ‏ ‏رَاحِلَتِهِ ‏ ‏وَإِنِّي أَعْتَذِرُ إِلَيْكُمْ مِنْ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏إِنِّي أَمَرْتُهُ أَنْ يَحْبِسَ هَذَا الْمَالَ عَلَى ضَعَفَةِ ‏ ‏الْمُهَاجِرِينَ ‏ ‏فَأَعْطَى ذَا الْبَأْسِ وَذَا الشَّرَفِ وَذَا ‏ ‏اللَّسَانَةِ فَنَزَعْتُهُ وَأَمَّرْتُ ‏ ‏أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ ‏ ‏فَقَالَ ‏ ‏أَبُو عَمْرِو بْنُ حَفْصِ بْنِ الْمُغِيرَةِ ‏ ‏وَاللَّهِ مَا أَعْذَرْتَ يَا ‏ ‏عُمَرُ بْنَ الْخَطَّابِ ‏ ‏لَقَدْ نَزَعْتَ عَامِلًا اسْتَعْمَلَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَغَمَدْتَ سَيْفًا سَلَّهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَوَضَعْتَ ‏ ‏لِوَاءً ‏ ‏نَصَبَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَقَدْ قَطَعْتَ الرَّحِمَ وَحَسَدْتَ ابْنَ الْعَمِّ فَقَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏إِنَّكَ قَرِيبُ الْقَرَابَةِ حَدِيثُ السِّنِّ مُغْضَبٌ مِنْ ابْنِ عَمِّكَ ‏","","",""],[15341,15341,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ عَبْدُ الرَّحْمَنِ بْنِ النُّعْمَانِ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏وَكَانَ قَدْ أَدْرَكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اكْتَحِلُوا ‏ ‏بِالْإِثْمِدِ ‏ ‏الْمُرَوَّحِ ‏ ‏فَإِنَّهُ ‏ ‏يَجْلُو ‏ ‏الْبَصَرَ وَيُنْبِتُ الشَّعْرَ ‏","","",""],[15342,15342,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبُ بْنُ شَدَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَحَّازُ بْنُ جُدَيٍّ الْحَنَفِيُّ ‏ ‏عَنْ ‏ ‏سِنَانِ بْنِ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِالْقُدُورِ فَأُكْفِئَتْ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏وَكَانَ فِيهَا لُحُومُ حُمُرِ النَّاسِ ‏","","",""],[15343,15343,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَهَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏جَوْنِ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْمُحَبِّقِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِبَيْتٍ ‏ ‏بِفِنَائِهِ ‏ ‏قِرْبَةٌ ‏ ‏مُعَلَّقَةٌ فَاسْتَسْقَى فَقِيلَ إِنَّهَا مَيْتَةٌ قَالَ ‏ ‏ذَكَاةُ ‏ ‏الْأَدِيمِ ‏ ‏دِبَاغُهُ ‏","","",""],[15344,15344,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ أَبُو قَطَنٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏جَوْنِ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْمُحَبِّقِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دِبَاغُهَا ‏ ‏طُهُورُهَا ‏ ‏أَوْ ‏ ‏ذَكَاتُهَا ‏","","",""],[15345,15345,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دَلْهَمٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْمُحَبِّقِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذُوا عَنِّي خُذُوا عَنِّي قَدْ جَعَلَ اللَّهُ لَهُنَّ سَبِيلًا ‏ ‏الْبِكْرُ ‏ ‏بِالْبِكْرِ ‏ ‏جَلْدُ مِائَةٍ وَنَفْيُ سَنَةٍ ‏ ‏وَالثَّيِّبُ ‏ ‏بِالثَّيِّبِ ‏ ‏جَلْدُ مِائَةٍ ‏ ‏وَالرَّجْمُ ‏","","",""],[15346,15346,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْمُحَبِّقِ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الرَّجُلِ ‏ ‏يُوَاقِعُ ‏ ‏جَارِيَةَ ‏ ‏امْرَأَتِهِ قَالَ إِنْ أَكْرَهَهَا فَهِيَ حُرَّةٌ وَلَهَا عَلَيْهِ مِثْلُهَا وَإِنْ طَاوَعَتْهُ فَهِيَ أَمَتُهُ وَلَهَا عَلَيْهِ مِثْلُهَا ‏","","",""],[15347,15347,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ حَبِيبِ بْنِ عَبْدِ اللَّهِ الْأَزْدِيِّ ثُمَّ النُّمَيْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَبِيبُ بْنُ عَبْدِ اللَّهِ ‏ ‏يَعْنِي أَبَاهُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سِنَانَ بْنَ سَلَمَةَ بْنِ الْمُحَبِّقِ الْهُذَلِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَتْ لَهُ ‏ ‏حَمُولَةٌ ‏ ‏تَأْوِي إِلَى ‏ ‏شِبَعٍ ‏ ‏فَلْيَصُمْ رَمَضَانَ حَيْثُ أَدْرَكَهُ ‏","","",""],[15348,15348,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرْبُ بْنُ شَدَّادٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنِ ‏ ‏النَّحَّازِ الْحَنَفِيِّ ‏ ‏أَنَّ ‏ ‏سِنَانَ بْنَ سَلَمَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِلُحُومِ حُمُرِ النَّاسِ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏وَهِيَ فِي الْقُدُورِ ‏ ‏فَأُكْفِئَتْ ‏","","",""],[15349,15349,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ يَعْنِي التَّيْمِيَّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ يَعْنِي النَّهْدِيَّ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ مُخَارِقٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏} ‏انْطَلَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏رَضْمَةٍ ‏ ‏مِنْ جَبَلٍ فَعَلَا أَعْلَاهَا ثُمَّ نَادَى ‏ ‏أَوْ قَالَ قَالَ ‏ ‏يَا آلَ ‏ ‏عَبْدِ مَنَافَاهُ ‏ ‏إِنِّي نَذِيرٌ إِنَّ مَثَلِي وَمَثَلَكُمْ كَمَثَلِ رَجُلٍ رَأَى الْعَدُوَّ فَانْطَلَقَ ‏ ‏يَرْبَأُ ‏ ‏أَهْلَهُ يُنَادِي ‏ ‏أَوْ قَالَ يَهْتِفُ ‏ ‏يَا ‏ ‏صَبَاحَاهْ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏فِي هَذَا الْحَدِيثِ عَنْ ‏ ‏قَبِيصَةَ بْنِ مُخَارِقٍ ‏ ‏أَوْ ‏ ‏وَهْبِ بْنِ عَمْرٍو ‏ ‏وَهُوَ خَطَأٌ إِنَّمَا هُوَ ‏ ‏زُهَيْرُ بْنُ عَمْرٍو ‏ ‏فَلَمَّا أَخْطَأَ تَرَكْتُ ‏ ‏وَهْبَ بْنَ عَمْرٍو ‏","","",""],[15350,15350,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَوْفٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَيَّانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏قَطَنُ بْنُ قَبِيصَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَبِيصَةَ بْنِ مُخَارِقٍ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْعِيَافَةُ ‏ ‏وَالطِّيَرَةُ ‏ ‏وَالطَّرْقُ ‏ ‏مِنْ ‏ ‏الْجِبْتِ ‏ ‏قَالَ ‏ ‏الْعِيَافَةُ ‏ ‏مِنْ الزَّجْرِ ‏ ‏وَالطَّرْقُ ‏ ‏مِنْ الْخَطِّ ‏","","",""],[15351,15351,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏هَارُونَ بْنِ رِئَابٍ ‏ ‏عَنْ ‏ ‏كِنَانَةَ بْنِ نُعَيْمٍ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ الْمُخَارِقِ الْهِلَالِيِّ ‏ ‏تَحَمَّلْتُ ‏ ‏بِحَمَالَةٍ ‏ ‏فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْأَلُهُ فِيهَا فَقَالَ ‏ ‏نُؤَدِّهَا عَنْكَ وَنُخْرِجُهَا مِنْ نَعَمْ ‏ ‏الصَّدَقَةِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً وَنُخْرِجُهَا إِذَا جَاءَتْنَا ‏ ‏الصَّدَقَةُ ‏ ‏أَوْ إِذَا جَاءَ نَعَمُ ‏ ‏الصَّدَقَةِ ‏ ‏وَقَالَ يَا ‏ ‏قَبِيصَةُ ‏ ‏إِنَّ الْمَسْأَلَةَ لَا تَصْلُحُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً حُرِّمَتْ ‏ ‏إِلَّا فِي ثَلَاثٍ رَجُلٍ ‏ ‏تَحَمَّلَ ‏ ‏بِحَمَالَةٍ ‏ ‏حَلَّتْ لَهُ الْمَسْأَلَةُ حَتَّى يُؤَدِّيَهَا ثُمَّ يُمْسِكَ وَرَجُلٍ أَصَابَتْهُ حَاجَةٌ ‏ ‏وَفَاقَةٌ ‏ ‏حَتَّى يَشْهَدَ لَهُ ثَلَاثَةٌ مِنْ ‏ ‏ذَوِي ‏ ‏الْحِجَا ‏ ‏مِنْ قَوْمِهِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً رَجُلٍ أَصَابَتْهُ ‏ ‏فَاقَةٌ ‏ ‏أَوْ حَاجَةٌ ‏ ‏حَتَّى يَشْهَدَ لَهُ ‏ ‏أَوْ يَكَلَّمَ ‏ ‏ثَلَاثَةٌ مِنْ ‏ ‏ذَوِي ‏ ‏الْحِجَا ‏ ‏مِنْ قَوْمِهِ ‏ ‏أَنَّهُ قَدْ أَصَابَتْهُ حَاجَةٌ ‏ ‏أَوْ ‏ ‏فَاقَةٌ ‏ ‏إِلَّا قَدْ حَلَّتْ لَهُ الْمَسْأَلَةُ فَيَسْأَلُ حَتَّى يُصِيبَ ‏ ‏قِوَامًا ‏ ‏مِنْ عَيْشٍ ‏ ‏أَوْ ‏ ‏سِدَادًا ‏ ‏مِنْ عَيْشٍ ‏ ‏ثُمَّ يُمْسِكَ وَرَجُلٍ أَصَابَتْهُ ‏ ‏جَائِحَةٌ ‏ ‏اجْتَاحَتْ مَالَهُ حَلَّتْ لَهُ الْمَسْأَلَةُ فَيَسْأَلُ حَتَّى يُصِيبَ ‏ ‏قِوَامًا ‏ ‏مِنْ عَيْشٍ ‏ ‏أَوْ ‏ ‏سَدَادًا ‏ ‏مِنْ عَيْشٍ ‏ ‏ثُمَّ يُمْسِكَ وَمَا كَانَ سِوَى ذَلِكَ مِنْ الْمَسْأَلَةِ ‏ ‏سُحْتٌ ‏","","",""],[15352,15352,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏كُرْزِ بْنِ عَلْقَمَةَ الْخُزَاعِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ هَلْ لِلْإِسْلَامِ مِنْ مُنْتَهَى قَالَ أَيُّمَا أَهْلِ بَيْتٍ ‏ ‏وَقَالَ ‏ ‏فِي مَوْضِعٍ آخَرَ قَالَ نَعَمْ ‏ ‏أَيُّمَا أَهْلِ بَيْتٍ مِنْ ‏ ‏الْعَرَبِ ‏ ‏أَوْ ‏ ‏الْعُجْمِ ‏ ‏أَرَادَ اللَّهُ بِهِمْ خَيْرًا أَدْخَلَ عَلَيْهِمْ الْإِسْلَامَ قَالَ ثُمَّ مَهْ قَالَ ثُمَّ تَقَعُ الْفِتَنُ كَأَنَّهَا ‏ ‏الظُّلَلُ ‏ ‏قَالَ كَلَّا وَاللَّهِ إِنْ شَاءَ اللَّهُ قَالَ بَلَى وَالَّذِي نَفْسِي بِيَدِهِ ثُمَّ تَعُودُونَ فِيهَا ‏ ‏أَسَاوِدَ ‏ ‏صُبًّا ‏ ‏يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏ ‏وَقَرَأَ عَلَيَّ ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏أَسَاوِدَ ‏ ‏صُبًّا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏الْحَيَّةُ السَّوْدَاءُ تُنْصَبُ أَيْ تَرْتَفِعُ ‏","","",""],[15353,15353,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏كُرْزِ بْنِ عَلْقَمَةَ الْخُزَاعِيِّ ‏ ‏قَالَ ‏ ‏قَالَ أَعْرَابِيٌّ يَا رَسُولَ اللَّهِ هَلْ لِلْإِسْلَامِ مِنْ مُنْتَهَى قَالَ نَعَمْ ‏ ‏أَيُّمَا أَهْلِ بَيْتٍ مِنْ ‏ ‏الْعَرَبِ ‏ ‏أَوْ ‏ ‏الْعُجْمِ ‏ ‏أَرَادَ اللَّهُ عَزَّ وَجَلَّ بِهِمْ خَيْرًا أَدْخَلَ عَلَيْهِمْ الْإِسْلَامَ قَالَ ثُمَّ مَاذَا يَا رَسُولَ اللَّهِ قَالَ ثُمَّ تَقَعُ فِتَنٌ كَأَنَّهَا ‏ ‏الظُّلَلُ ‏ ‏فَقَالَ الْأَعْرَابِيُّ كَلَّا يَا رَسُولَ اللَّهِ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلَى وَالَّذِي نَفْسِي بِيَدِهِ لَتَعُودُنَّ فِيهَا ‏ ‏أَسَاوِدَ ‏ ‏صُبًّا ‏ ‏يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[15354,15354,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ قَيْسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏كُرْزٍ الْخُزَاعِيِّ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْرَابِيٌّ فَقَالَ يَا رَسُولَ اللَّهِ هَلْ لِهَذَا الْأَمْرِ مِنْ مُنْتَهَى قَالَ نَعَمْ ‏ ‏فَمَنْ أَرَادَ اللَّهُ بِهِ خَيْرًا مِنْ ‏ ‏أَعْجَمٍ ‏ ‏أَوْ ‏ ‏عُرْبٍ ‏ ‏أَدْخَلَهُ عَلَيْهِمْ ثُمَّ تَقَعُ فِتَنٌ ‏ ‏كَالظُّلَلِ ‏ ‏يَعُودُونَ فِيهَا ‏ ‏أَسَاوِدَ ‏ ‏صُبًّا ‏ ‏يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ وَأَفْضَلُ النَّاسِ يَوْمَئِذٍ مُؤْمِنٌ مُعْتَزِلٌ فِي ‏ ‏شِعْبٍ ‏ ‏مِنْ ‏ ‏الشِّعَابِ ‏ ‏يَتَّقِي رَبَّهُ تَبَارَكَ وَتَعَالَى وَيَدَعُ النَّاسَ مِنْ شَرِّهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ الْقُرْقُسَانِيُّ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏ابْنِ الْمُغِيرَةِ ‏ ‏إِلَّا أَنَّهُ قَالَ ‏ ‏كُرْزُ بْنُ حُبَيْشٍ الْخُزَاعِيُّ ‏","","",""],[15355,15355,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِلَالُ بْنُ عَامِرٍ الْمُزَنِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ النَّاسَ ‏ ‏بِمِنًى ‏ ‏عَلَى بَغْلَةٍ وَعَلَيْهِ ‏ ‏بُرْدٌ ‏ ‏أَحْمَرُ قَالَ وَرَجُلٌ مِنْ أَهْلِ ‏ ‏بَدْرٍ ‏ ‏بَيْنَ يَدَيْهِ ‏ ‏يُعَبِّرُ ‏ ‏عَنْهُ قَالَ فَجِئْتُ حَتَّى أَدْخَلْتُ يَدِي بَيْنَ قَدَمِهِ ‏ ‏وَشِرَاكِهِ ‏ ‏قَالَ فَجَعَلْتُ أَعْجَبُ مِنْ ‏ ‏بَرَدِهَا ‏","","",""],[15356,15356,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْخٌ ‏ ‏مِنْ ‏ ‏بَنِي فَزَارَةَ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَامِرٍ الْمُزَنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ النَّاسَ عَلَى بَغْلَةٍ ‏ ‏شَهْبَاءَ ‏ ‏وَعَلِيٌّ ‏ ‏يُعَبِّرُ ‏ ‏عَنْهُ ‏","","",""],[15357,15357,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ هِشَامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي الْمُعَلَّى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ يَوْمًا فَقَالَ ‏ ‏إِنَّ رَجُلًا خَيَّرَهُ رَبُّهُ عَزَّ وَجَلَّ بَيْنَ أَنْ يَعِيشَ فِي الدُّنْيَا مَا شَاءَ أَنْ يَعِيشَ فِيهَا يَأْكُلُ مِنْ الدُّنْيَا مَا شَاءَ أَنْ يَأْكُلَ مِنْهَا وَبَيْنَ لِقَاءِ رَبِّهِ عَزَّ وَجَلَّ فَاخْتَارَ لِقَاءَ رَبِّهِ قَالَ فَبَكَى ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ فَقَالَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا تَعْجَبُونَ مِنْ هَذَا الشَّيْخِ أَنْ ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا صَالِحًا خَيَّرَهُ رَبُّهُ تَبَارَكَ وَتَعَالَى بَيْنَ الدُّنْيَا وَبَيْنَ لِقَاءِ رَبِّهِ تَبَارَكَ وَتَعَالَى فَاخْتَارَ لِقَاءَ رَبِّهِ عَزَّ وَجَلَّ وَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَعْلَمَهُمْ بِمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بَلْ ‏ ‏نَفْدِيكَ بِأَمْوَالِنَا وَأَبْنَائِنَا ‏ ‏أَوْ بِآبَائِنَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ النَّاسِ أَحَدٌ أَمَنُّ عَلَيْنَا فِي صُحْبَتِهِ وَذَاتِ يَدِهِ مِنْ ‏ ‏ابْنِ أَبِي قُحَافَةَ ‏ ‏وَلَوْ كُنْتُ مُتَّخِذًا ‏ ‏خَلِيلًا ‏ ‏لَاتَّخَذْتُ ‏ ‏ابْنَ أَبِي قُحَافَةَ ‏ ‏وَلَكِنْ وُدٌّ وَإِخَاءُ إِيمَانٍ وَلَكِنْ وُدٌّ وَإِخَاءُ إِيمَانٍ مَرَّتَيْنِ وَإِنَّ صَاحِبَكُمْ ‏ ‏خَلِيلُ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[15358,15358,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ يَزِيدَ الْجُعْفِيِّ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ أَنَا وَأَخِي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُلْنَا يَا رَسُولَ اللَّهِ إِنَّ أُمَّنَا ‏ ‏مُلَيْكَةَ ‏ ‏كَانَتْ تَصِلُ ‏ ‏الرَّحِمَ ‏ ‏وَتَقْرِي ‏ ‏الضَّيْفَ وَتَفْعَلُ وَتَفْعَلُ هَلَكَتْ فِي الْجَاهِلِيَّةِ فَهَلْ ذَلِكَ نَافِعُهَا شَيْئًا قَالَ لَا قَالَ قُلْنَا فَإِنَّهَا كَانَتْ ‏ ‏وَأَدَتْ ‏ ‏أُخْتًا لَنَا فِي الْجَاهِلِيَّةِ فَهَلْ ذَلِكَ نَافِعُهَا شَيْئًا قَالَ ‏ ‏الْوَائِدَةُ ‏ ‏وَالْمَوْءُودَةُ ‏ ‏فِي النَّارِ إِلَّا أَنْ تُدْرِكَ ‏ ‏الْوَائِدَةُ ‏ ‏الْإِسْلَامَ فَيَعْفُوَ اللَّهُ عَنْهَا ‏","","",""],[15359,15359,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُوسَى بْنُ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَلَّقَ ‏ ‏حَفْصَةَ بِنْتَ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏ثُمَّ ‏ ‏رَاجَعَهَا ‏","","",""],[15360,15360,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى بْنِ الطَّبَّاعِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ يَعْنِي ابْنَ حَازِمٍ ‏ ‏عَنْ ‏ ‏وَاصِلٍ الْأَحْدَبِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏شُرَيْحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ تَعَالَى ‏ ‏يَا ابْنَ ‏ ‏آدَمَ ‏ ‏قُمْ إِلَيَّ أَمْشِ إِلَيْكَ وَامْشِ إِلَيَّ ‏ ‏أُهَرْوِلْ ‏ ‏إِلَيْكَ ‏","","",""],[15361,15361,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏زُرْعَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ جَرْهَدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِهِ وَهُوَ كَاشِفٌ عَنْ فَخِذِهِ فَقَالَ أَمَا عَلِمْتَ أَنَّ ‏ ‏الْفَخِذَ عَوْرَةٌ ‏","","",""],[15362,15362,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏زُرْعَةَ بْنِ مُسْلِمِ بْنِ جَرْهَدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏جَرْهَدًا ‏ ‏فِي الْمَسْجِدِ وَعَلَيْهِ ‏ ‏بُرْدَةٌ ‏ ‏قَدْ انْكَشَفَ فَخِذُهُ فَقَالَ ‏ ‏الْفَخِذُ عَوْرَةٌ ‏","","",""],[15363,15363,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزِّنَادِ ‏ ‏وَقَالَ أَخْبَرَنِي ‏ ‏آلُ جَرْهَدٍ ‏ ‏عَنْ ‏ ‏جَرْهَدٍ ‏ ‏قَالَ ‏ ‏الْفَخِذُ عَوْرَةٌ ‏","","",""],[15364,15364,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏ابْنِ جَرْهَدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا كَاشِفٌ فَخِذِي فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَطِّهَا فَإِنَّهَا مِنْ الْعَوْرَةِ ‏","","",""],[15365,15365,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَرْهَدٍ الْأَسْلَمِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏جَرْهَدًا ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فَخِذُ الْمَرْءِ الْمُسْلِمِ عَوْرَةٌ ‏","","",""],[15366,15366,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏زُرْعَةَ بْنِ جَرْهَدٍ الْأَسْلَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ الصُّفَّةِ ‏ ‏قَالَ ‏ ‏جَلَسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَأَى فَخِذِي مُنْكَشِفَةً فَقَالَ ‏ ‏خَمِّرْ ‏ ‏عَلَيْكَ أَمَا عَلِمْتَ أَنَّ ‏ ‏الْفَخِذَ عَوْرَةٌ ‏","","",""],[15367,15367,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زُرْعَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ جَرْهَدٍ ‏ ‏عَنْ ‏ ‏جَرْهَدٍ ‏ ‏جَدِّهِ وَنَفَرٍ مِنْ ‏ ‏أَسْلَمَ ‏ ‏سِوَاهُ ذَوِي رِضًا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ عَلَى ‏ ‏جَرْهَدٍ ‏ ‏وَفَخِذُ ‏ ‏جَرْهَدٍ ‏ ‏مَكْشُوفَةٌ فِي الْمَسْجِدِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏جَرْهَدُ ‏ ‏غَطِّ فَخِذَكَ فَإِنَّ يَا ‏ ‏جَرْهَدُ ‏ ‏الْفَخِذَ عَوْرَةٌ ‏","","",""],[15368,15368,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الزِّنَادِ ‏ ‏عَنْ ‏ ‏زُرْعَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ جَرْهَدٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏جَرْهَدٍ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيَّ ‏ ‏بُرْدَةٌ ‏ ‏وَقَدْ انْكَشَفَتْ فَخِذِي قَالَ غَطِّ فَإِنَّ ‏ ‏الْفَخْذَ عَوْرَةٌ ‏","","",""],[15369,15369,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عُلَاثَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدُ بْنُ اللَّجْلَاجِ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏بَيْنَمَا نَحْنُ فِي السُّوقِ إِذْ مَرَّتْ امْرَأَةٌ تَحْمِلُ صَبِيًّا فَثَارَ النَّاسُ وَثُرْتُ مَعَهُمْ فَانْتَهَيْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ لَهَا مَنْ أَبُو هَذَا فَسَكَتَتْ فَقَالَ مَنْ أَبُو هَذَا فَسَكَتَتْ فَقَالَ شَابٌّ ‏ ‏بِحِذَائِهَا ‏ ‏يَا رَسُولَ اللَّهِ إِنَّهَا حَدِيثَةُ السِّنِّ حَدِيثَةُ عَهْدٍ ‏ ‏بِجِزْيَةٍ ‏ ‏وَإِنَّهَا لَمْ تُخْبِرْكَ وَأَنَا أَبُوهُ يَا رَسُولَ اللَّهِ فَالْتَفَتَ إِلَى مَنْ عِنْدَهُ كَأَنَّهُ يَسْأَلُهُمْ عَنْهُ فَقَالُوا مَا عَلِمْنَا إِلَّا خَيْرًا ‏ ‏أَوْ نَحْوَ ذَلِكَ ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْصَنْتَ ‏ ‏قَالَ نَعَمْ ‏ ‏فَأَمَرَ ‏ ‏بِرَجْمِهِ ‏ ‏فَذَهَبْنَا فَحَفَرْنَا لَهُ حَتَّى أَمْكَنَّا وَرَمَيْنَاهُ بِالْحِجَارَةِ حَتَّى هَدَأَ ثُمَّ رَجَعْنَا إِلَى مَجَالِسِنَا فَبَيْنَمَا نَحْنُ كَذَلِكَ إِذْ أَنَا بِشَيْخٍ يَسْأَلُ عَنْ الْفَتَى فَقُمْنَا إِلَيْهِ فَأَخَذْنَا ‏ ‏بِتَلَابِيبِهِ ‏ ‏فَجِئْنَا بِهِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّ هَذَا جَاءَ يَسْأَلُ عَنْ الْخَبِيثِ فَقَالَ ‏ ‏مَهْ ‏ ‏لَهُوَ أَطْيَبُ عِنْدَ اللَّهِ رِيحًا مِنْ ‏ ‏الْمِسْكِ ‏ ‏قَالَ فَذَهَبْنَا فَأَعَنَّاهُ عَلَى غُسْلِهِ ‏ ‏وَحَنُوطِهِ ‏ ‏وَتَكْفِينِهِ وَحَفَرْنَا لَهُ ‏ ‏وَلَا أَدْرِي أَذَكَرَ الصَّلَاةَ أَمْ لَا ‏","","",""],[15370,15370,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مَسْلِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَزِيدَ بْنَ أَبِي مَرْيَمَ ‏ ‏قَالَ ‏ ‏لَحِقَنِي ‏ ‏عَبَايَةُ بْنُ رَافِعِ بْنِ خَدِيجٍ ‏ ‏وَأَنَا رَائِحٌ إِلَى الْمَسْجِدِ إِلَى الْجُمُعَةِ مَاشِيًا وَهُوَ رَاكِبٌ قَالَ أَبْشِرْ فَإِنِّي ‏ ‏سَمِعْتُ ‏ ‏أَبَا عَبْسٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اغْبَرَّتْ قَدَمَاهُ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ حَرَّمَهُمَا اللَّهُ عَزَّ وَجَلَّ عَلَى النَّارِ ‏","","",""],[15371,15371,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ الْعَدَوِيِّ ‏ ‏سَمِعَهُ مِنْهُ عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْأَعْرَابِيِّ ‏ ‏الَّذِي سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ خَيْرَ دِينِكُمْ أَيْسَرُهُ إِنَّ خَيْرَ دِينِكُمْ أَيْسَرُهُ ‏","","",""],[15372,15372,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو النَّضْرِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏كَانَ قَدِيمًا مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏كَانَ فِي عَهْدِ ‏ ‏عُثْمَانَ ‏ ‏رَجُلٌ ‏ ‏يُخْبِرُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ لَقِيَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ اكْتُبْ لِي كِتَابًا أَنْ لَا أُؤَاخَذَ ‏ ‏بِجَرِيرَةِ ‏ ‏غَيْرِي فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ذَلِكَ لَكَ وَلِكُلِّ مُسْلِمٍ ‏","","",""],[15373,15373,"","","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏أَنَّ ‏ ‏هِشَامَ بْنَ يَحْيَى ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عِكْرِمَةَ بْنَ سَلَمَةَ بْنِ رَبِيعَةَ ‏ ‏أَخْبَرَهُ أَنَّ أَخَوَيْنِ مِنْ بَنِي ‏ ‏الْمُغِيرَةِ ‏ ‏لَقِيَا ‏ ‏مُجَمِّعَ بْنَ يَزِيدَ الْأَنْصَارِيَّ ‏ ‏فَقَالَ إِنِّي أَشْهَدُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ أَنْ لَا يَمْنَعَ جَارٌ جَارَهُ أَنْ يَغْرِزَ خَشَبَةً فِي جِدَارِهِ فَقَالَ الْحَالِفُ أَيْ أَخِي قَدْ عَلِمْتُ أَنَّكَ مَقْضِيٌّ لَكَ وَقَدْ حَلَفْتُ فَاجْعَلْ ‏ ‏أُسْطُوَانًا دُونَ جِدَارِي فَفَعَلَ الْآخَرُ فَغَرَزَ فِي ‏ ‏الْأُسْطُوَانِ خَشَبَةً ‏ ‏قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏وَأَنَا نَظَرْتُ إِلَى ذَلِكَ ‏","","",""],[15374,15374,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ يَحْيَى ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عِكْرِمَةَ بْنَ سَلَمَةَ بْنِ رَبِيعَةَ ‏ ‏أَخْبَرَهُ أَنَّ أَخَوَيْنِ مِنْ بَنِي ‏ ‏الْمُغِيرَةِ ‏ ‏أَعْتَقَ أَحَدُهُمَا أَنْ لَا يَغْرِزَ خَشَبًا فِي جِدَارِهِ فَلَقِيَا ‏ ‏مُجَمِّعَ بْنَ يَزِيدَ الْأَنْصَارِيَّ ‏ ‏وَرِجَالًا كَثِيرًا فَقَالُوا نَشْهَدُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَمْنَعْ جَارٌ جَارَهُ أَنْ يَغْرِزَ خَشَبًا فِي جِدَارِهِ فَقَالَ الْحَالِفُ أَيْ أَخِي قَدْ عَلِمْتُ أَنَّكَ مَقْضِيٌّ لَكَ عَلَيَّ وَقَدْ حَلَفْتُ فَاجْعَلْ ‏ ‏أُسْطُوَانًا دُونَ جِدَارِي فَفَعَلَ الْآخَرُ فَغَرَزَ فِي ‏ ‏الْأُسْطُوَانِ خَشَبَةً ‏ ‏فَقَالَ ‏ ‏لِي ‏ ‏عَمْرٌو ‏ ‏فَأَنَا نَظَرْتُ إِلَى ذَلِكَ ‏","","",""],[15375,15375,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَزِيدُ بْنُ عِيَاضٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ رُقَيْشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ بْنِ جَارِيَةَ ‏ ‏عَنْ ‏ ‏مُجَمِّعِ بْنِ يَزِيدَ بْنِ جَارِيَةَ ‏ ‏أَنَّهُ رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي نَعْلَيْنِ ‏","","",""],[15376,15376,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏السَّائِبُ بْنُ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏أَبِي الشَّمَّاخِ الْأَزْدِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَمٍّ لَهُ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ أَتَى ‏ ‏مُعَاوِيَةَ ‏ ‏فَدَخَلَ عَلَيْهِ وَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏وَلِيَ ‏ ‏أَمْرَ النَّاسِ ثُمَّ أَغْلَقَ بَابَهُ دُونَ الْمِسْكِينِ أَوْ الْمَظْلُومِ أَوْ ذِي الْحَاجَةِ أَغْلَقَ اللَّهُ عَزَّ وَجَلَّ دُونَهُ أَبْوَابَ رَحْمَتِهِ عِنْدَ حَاجَتِهِ وَفَقْرِهِ أَفْقَرَ مَا يَكُونُ إِلَيْهَا ‏","","",""],[15377,15377,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏نَادَى ‏ ‏رَجُلٌ ‏ ‏مِنْ أَهْلِ ‏ ‏الشَّامِ ‏ ‏يَوْمَ ‏ ‏صِفِّينَ ‏ ‏أَفِيكُمْ ‏ ‏أُوَيْسٌ الْقَرَنِيُّ ‏ ‏قَالُوا نَعَمْ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ خَيْرِ التَّابِعِينَ ‏ ‏أُوَيْسًا الْقَرَنِيَّ ‏","","",""],[15378,15378,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏أُتِيَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فِي امْرَأَةٍ تَزَوَّجَهَا رَجُلٌ ثُمَّ مَاتَ عَنْهَا وَلَمْ يَفْرِضْ لَهَا ‏ ‏صَدَاقًا ‏ ‏وَلَمْ يَكُنْ دَخَلَ بِهَا قَالَ فَاخْتَلَفُوا إِلَيْهِ فَقَالَ أَرَى ‏ ‏لَهَا مِثْلَ ‏ ‏صَدَاقِ ‏ ‏نِسَائِهَا وَلَهَا الْمِيرَاثُ وَعَلَيْهَا الْعِدَّةُ فَشَهِدَ ‏ ‏مَعْقِلُ بْنُ سِنَانٍ الْأَشْجَعِيُّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى فِي ‏ ‏بِرْوَعَ ابْنَةِ وَاشِقٍ ‏ ‏بِمِثْلِ مَا قَضَى ‏","","",""],[15379,15379,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏قَالَ ‏ ‏شَهِدَ عِنْدِي ‏ ‏نَفَرٌ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏مِنْهُمْ ‏ ‏الْحَسَنُ بْنُ أَبِي الْحَسَنِ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ سِنَانٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِهِ وَهُوَ ‏ ‏يَحْتَجِمُ ‏ ‏لِثَمَانِ عَشْرَةَ قَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[15380,15380,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏كَهْمَسُ بْنُ الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَيَّارِ بْنِ مَنْظُورٍ الْفَزَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏بُهَيْسَةَ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏قَالَ ‏ ‏اسْتَأْذَنْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلْتُ بَيْنَهُ وَبَيْنَ قَمِيصِهِ قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ مَا الشَّيْءُ الَّذِي لَا يَحِلُّ مَنْعُهُ قَالَ الْمَاءُ قُلْتُ يَا رَسُولَ اللَّهِ مَا الشَّيْءُ الَّذِي لَا يَحِلُّ مَنْعُهُ قَالَ الْمَاءُ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ مَا الشَّيْءُ الَّذِي لَا يَحِلُّ مَنْعُهُ قَالَ ‏ ‏أَنْ تَفْعَلَ الْخَيْرَ خَيْرٌ لَكَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَيَّارَ بْنَ مَنْظُورٍ الْفَزَارِيَّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏بُهَيْسَةَ ‏ ‏قَالَتِ ‏ ‏اسْتَأْذَنَ أَبِي عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ بَيْنَهُ وَبَيْنَ قَمِيصِهِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[15381,15381,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَيَّارُ بْنُ مَنْظُورٍ الْفَزَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏بُهَيْسَةَ ‏ ‏قَالَتِ ‏ ‏اسْتَأْذَنَ ‏ ‏أَبِي ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَ ‏ ‏يَدْنُو ‏ ‏مِنْهُ ‏ ‏وَيَلْتَزِمُهُ ‏ ‏ثُمَّ قَالَ يَا نَبِيَّ اللَّهِ مَا الشَّيْءُ الَّذِي لَا يَحِلُّ مَنْعُهُ قَالَ الْمَاءُ ثُمَّ قَالَ يَا نَبِيَّ اللَّهِ مَا الشَّيْءُ الَّذِي لَا يَحِلُّ مَنْعُهُ قَالَ الْمِلْحُ ثُمَّ قَالَ يَا نَبِيَّ اللَّهِ مَا الشَّيْءُ الَّذِي لَا يَحِلُّ مَنْعُهُ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ تَفْعَلْ الْخَيْرَ خَيْرٌ لَكَ ‏ ‏قَالَ ‏ ‏فَانْتَهَى قَوْلُهُ إِلَى الْمَاءِ وَالْمِلْحِ قَالَ وَكَانَ ذَلِكَ الرَّجُلُ لَا يَمْنَعُ شَيْئًا وَإِنْ قَلَّ ‏","","",""],[15382,15382,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحِيمِ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْحَارِثِ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ غَسَّانَ التَّيْمِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الرَّسِيمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏وَفَدْنَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَهَانَا عَنْ ‏ ‏الظُّرُوفِ ‏ ‏قَالَ ثُمَّ قَدِمْنَا عَلَيْهِ فَقُلْنَا إِنَّ أَرْضَنَا أَرْضٌ ‏ ‏وَخِمَةٌ ‏ ‏قَالَ فَقَالَ ‏ ‏اشْرَبُوا فِيمَا شِئْتُمْ مَنْ شَاءَ ‏ ‏أَوْكَأَ ‏ ‏سِقَاءَهُ ‏ ‏عَلَى إِثْمٍ ‏","","",""],[15383,15383,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ أَبُو زَيْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ اللَّهِ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ غَسَّانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبِي ‏ ‏فِي الْوَفْدِ الَّذِينَ وَفَدُوا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏عَبْدِ قَيْسٍ ‏ ‏فَنَهَاهُمْ عَنْ هَذِهِ الْأَوْعِيَةِ قَالَ ‏ ‏فَأَتْخَمْنَا ‏ ‏ثُمَّ أَتَيْنَاهُ الْعَامَ الْمُقْبِلَ قَالَ فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّكَ نَهَيْتَنَا عَنْ هَذِهِ الْأَوْعِيَةِ ‏ ‏فَأَتْخَمْنَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْتَبِذُوا ‏ ‏فِيمَا بَدَا لَكُمْ وَلَا تَشْرَبُوا مُسْكِرًا فَمَنْ شَاءَ ‏ ‏أَوْكَأَ ‏ ‏سِقَاءَهُ ‏ ‏عَلَى إِثْمٍ ‏","","",""],[15384,15384,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عُثْمَانَ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ خُثَيْمٍ الْهِلَالِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَدَّتِي ‏ ‏رَبِيعَةَ ابْنَةَ عِيَاضٍ ‏ ‏قَالَتْ سَمِعْتُ ‏ ‏جَدِّي ‏ ‏عُبَيْدَةَ بْنَ عَمْرٍو الْكِلَابِيَّ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ‏ ‏فَأَسْبَغَ ‏ ‏الْوُضُوءَ ‏ ‏قَالَ ‏ ‏وَكَانَتْ ‏ ‏رِبْعِيَّةُ ‏ ‏إِذَا تَوَضَّأَتْ ‏ ‏أَسْبَغَتْ ‏ ‏الْوُضُوءَ ‏","","",""],[15385,15385,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ رَأْسَهُ حَتَّى بَلَغَ ‏ ‏الْقَذَالَ ‏ ‏وَمَا يَلِيهِ مِنْ مُقَدَّمِ الْعُنُقِ مَرَّةً ‏ ‏قَالَ ‏ ‏الْقَذَالُ ‏ ‏السَّالِفَةُ الْعُنُقِ ‏","","",""],[15386,15386,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ أَبِي النَّجُودِ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ حَسَّانَ الْبَكْرِيِّ ‏ ‏قَالَ ‏ ‏قَدِمْنَا ‏ ‏الْمَدِينَةَ ‏ ‏فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏وَبِلَالٌ ‏ ‏قَائِمٌ بَيْنَ يَدَيْهِ ‏ ‏مُتَقَلِّدٌ ‏ ‏السَّيْفَ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِذَا رَايَاتٌ سُودٌ وَسَأَلْتُ مَا هَذِهِ الرَّايَاتُ فَقَالُوا ‏ ‏عَمْرُو بْنُ الْعَاصِ ‏ ‏قَدِمَ مِنْ غَزَاةٍ ‏","","",""],[15387,15387,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَّامٌ أَبُو الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ حَسَّانَ ‏ ‏قَالَ ‏ ‏مَرَرْتُ بِعَجُوزٍ ‏ ‏بِالرَّبَذَةِ ‏ ‏مُنْقَطِعٌ ‏ ‏بِهَا مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏قَالَ فَقَالَتْ أَيْنَ تُرِيدُونَ قَالَ فَقُلْتُ نُرِيدُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ فَاحْمِلُونِي مَعَكُمْ فَإِنَّ لِي إِلَيْهِ حَاجَةً قَالَ فَقُلْتُ فَدَخَلْتُ الْمَسْجِدَ فَإِذَا هُوَ ‏ ‏غَاصٌّ ‏ ‏بِالنَّاسِ وَإِذَا رَايَةٌ سَوْدَاءُ ‏ ‏تَخْفِقُ ‏ ‏فَقُلْتُ مَا شَأْنُ النَّاسِ الْيَوْمَ قَالُوا هَذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرِيدُ أَنْ يَبْعَثَ ‏ ‏عَمْرَو بْنَ الْعَاصِ ‏ ‏وَجْهًا ‏ ‏قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنْ رَأَيْتَ أَنْ تَجْعَلَ ‏ ‏الدَّهْنَاءَ ‏ ‏حِجَازًا بَيْنَنَا وَبَيْنَ ‏ ‏بَنِي تَمِيمٍ ‏ ‏فَافْعَلْ فَإِنَّهَا كَانَتْ ‏ ‏لَنَا مَرَّةً قَالَ ‏ ‏فَاسْتَوْفَزَتْ ‏ ‏الْعَجُوزُ وَأَخَذَتْهَا ‏ ‏الْحَمِيَّةُ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ أَيْنَ تَضْطَرُّ ‏ ‏مُضَرَكَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ حَمَلْتُ هَذِهِ وَلَا أَشْعُرُ أَنَّهَا كَائِنَةٌ لِي خَصْمًا قَالَ قُلْتُ أَعُوذُ بِاللَّهِ أَنْ أَكُونَ كَمَا قَالَ الْأَوَّلُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا قَالَ الْأَوَّلُ قَالَ عَلَى الْخَبِيرِ سَقَطْتَ ‏ ‏يَقُولُ ‏ ‏سَلَّامٌ ‏ ‏هَذَا أَحْمَقُ ‏ ‏يَقُولُ الرَّسُولُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْخَبِيرِ سَقَطْتَ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هِيهْ ‏ ‏يَسْتَطْعِمُهُ الْحَدِيثَ ‏ ‏قَالَ إِنَّ ‏ ‏عَادًا ‏ ‏أَرْسَلُوا وَافِدَهُمْ ‏ ‏قَيْلًا ‏ ‏فَنَزَلَ عَلَى ‏ ‏مُعَاوِيَةَ بْنِ بَكْرٍ ‏ ‏شَهْرًا ‏ ‏يَسْقِيهِ الْخَمْرَ وَتُغَنِّيهِ ‏ ‏الْجَرَادَتَانِ ‏ ‏فَانْطَلَقَ حَتَّى أَتَى عَلَى جِبَالِ ‏ ‏مُهْرَةَ ‏ ‏فَقَالَ اللَّهُمَّ إِنِّي لَمْ آتِ لِأَسِيرٍ ‏ ‏أُفَادِيهِ وَلَا لِمَرِيضٍ فَأُدَاوِيَهُ فَاسْقِ عَبْدَكَ مَا كُنْتَ سَاقِيَهُ وَاسْقِ ‏ ‏مُعَاوِيَةَ بْنَ بَكْرٍ ‏ ‏شَهْرًا يَشْكُرْ لَهُ الْخَمْرَ الَّتِي شَرِبَهَا عِنْدَهُ قَالَ فَمَرَّتْ سَحَابَاتٌ سُودٌ فَنُودِيَ أَنْ خُذْهَا ‏ ‏رَمَادًا ‏ ‏رِمْدِدًا ‏ ‏لَا ‏ ‏تَذَرْ ‏ ‏مِنْ ‏ ‏عَادٍ ‏ ‏أَحَدًا ‏ ‏قَالَ ‏ ‏أَبُو وَائِلٍ ‏ ‏فَبَلَغَنِي أَنَّ مَا أُرْسِلَ عَلَيْهِمْ مِنْ الرِّيحِ كَقَدْرِ مَا يَجْرِي فِي الْخَاتَمِ ‏","","",""],[15388,15388,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الْمُنْذِرِ سَلَّامُ بْنُ سُلَيْمَانَ النَّحْوِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ الْبَكْرِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْتُ أَشْكُو ‏ ‏الْعَلَاءَ بْنَ الْحَضْرَمِيِّ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرَرْتُ ‏ ‏بِالرَّبَذَةِ ‏ ‏فَإِذَا عَجُوزٌ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏مُنْقَطِعٌ ‏ ‏بِهَا فَقَالَتْ لِي يَا عَبْدَ اللَّهِ إِنَّ لِي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَاجَةً فَهَلْ أَنْتَ مُبَلِّغِي إِلَيْهِ قَالَ فَحَمَلْتُهَا فَأَتَيْتُ ‏ ‏الْمَدِينَةَ ‏ ‏فَإِذَا الْمَسْجِدُ غَاصٌّ بِأَهْلِهِ وَإِذَا رَايَةٌ سَوْدَاءُ ‏ ‏تَخْفِقُ ‏ ‏وَبِلَالٌ ‏ ‏مُتَقَلِّدٌ ‏ ‏السَّيْفَ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ مَا شَأْنُ النَّاسِ قَالُوا يُرِيدُ أَنْ يَبْعَثَ ‏ ‏عَمْرَو بْنَ الْعَاصِ ‏ ‏وَجْهًا ‏ ‏قَالَ فَجَلَسْتُ قَالَ فَدَخَلَ مَنْزِلَهُ ‏ ‏أَوْ قَالَ ‏ ‏رَحْلَهُ ‏ ‏فَاسْتَأْذَنْتُ عَلَيْهِ فَأَذِنَ لِي فَدَخَلْتُ فَسَلَّمْتُ فَقَالَ هَلْ كَانَ بَيْنَكُمْ وَبَيْنَ ‏ ‏بَنِي تَمِيمٍ ‏ ‏شَيْءٌ قَالَ فَقُلْتُ نَعَمْ قَالَ وَكَانَتْ لَنَا ‏ ‏الدَّبْرَةُ ‏ ‏عَلَيْهِمْ وَمَرَرْتُ بِعَجُوزٍ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏مُنْقَطِعٌ ‏ ‏بِهَا فَسَأَلَتْنِي أَنْ أَحْمِلَهَا إِلَيْكَ وَهَا هِيَ بِالْبَابِ فَأَذِنَ لَهَا فَدَخَلَتْ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنْ رَأَيْتَ أَنْ تَجْعَلَ بَيْنَنَا وَبَيْنَ ‏ ‏بَنِي تَمِيمٍ ‏ ‏حَاجِزًا فَاجْعَلْ ‏ ‏الدَّهْنَاءَ ‏ ‏فَحَمِيَتْ ‏ ‏الْعَجُوزُ ‏ ‏وَاسْتَوْفَزَتْ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ فَإِلَى أَيْنَ تَضْطَرُّ ‏ ‏مُضَرَكَ ‏ ‏قَالَ قُلْتُ إِنَّمَا مَثَلِي مَا قَالَ الْأَوَّلُ ‏ ‏مِعْزَاءُ ‏ ‏حَمَلَتْ ‏ ‏حَتْفَهَا ‏ ‏حَمَلْتُ هَذِهِ وَلَا أَشْعُرُ أَنَّهَا كَانَتْ لِي خَصْمًا أَعُوذُ بِاللَّهِ وَرَسُولِهِ أَنْ أَكُونَ كَوَافِدِ ‏ ‏عَادٍ ‏ ‏قَالَ ‏ ‏هِيهْ ‏ ‏وَمَا وَافِدُ ‏ ‏عَادٍ ‏ ‏وَهُوَ أَعْلَمُ بِالْحَدِيثِ مِنْهُ وَلَكِنْ يَسْتَطْعِمُهُ ‏ ‏قُلْتُ إِنَّ ‏ ‏عَادًا ‏ ‏قَحَطُوا فَبَعَثُوا وَافِدًا لَهُمْ يُقَالُ لَهُ ‏ ‏قَيْلٌ ‏ ‏فَمَرَّ ‏ ‏بِمُعَاوِيَةَ بْنِ بَكْرٍ ‏ ‏فَأَقَامَ عِنْدَهُ شَهْرًا ‏ ‏يَسْقِيهِ الْخَمْرَ ‏ ‏وَتُغَنِّيهِ ‏ ‏جَارِيَتَانِ ‏ ‏يُقَالُ لَهُمَا ‏ ‏الْجَرَادَتَانِ ‏ ‏فَلَمَّا مَضَى الشَّهْرُ خَرَجَ جِبَالَ ‏ ‏تِهَامَةَ ‏ ‏فَنَادَى اللَّهُمَّ إِنَّكَ تَعْلَمُ أَنِّي لَمْ أَجِئْ إِلَى مَرِيضٍ فَأُدَاوِيَهُ وَلَا إِلَى أَسِيرٍ فَأُفَادِيَهُ اللَّهُمَّ اسْقِ ‏ ‏عَادًا ‏ ‏مَا كُنْتَ ‏ ‏تَسْقِيهِ فَمَرَّتْ بِهِ سَحَابَاتٌ سُودٌ فَنُودِيَ مِنْهَا اخْتَرْ فَأَوْمَأَ إِلَى سَحَابَةٍ مِنْهَا سَوْدَاءَ فَنُودِيَ مِنْهَا خُذْهَا ‏ ‏رَمَادًا ‏ ‏رِمْدِدًا ‏ ‏لَا تُبْقِ مِنْ ‏ ‏عَادٍ ‏ ‏أَحَدًا قَالَ فَمَا بَلَغَنِي أَنَّهُ بُعِثَ عَلَيْهِمْ مِنْ الرِّيحِ إِلَّا قَدْرَ مَا يَجْرِي فِي خَاتِمِي هَذَا حَتَّى هَلَكُوا ‏ ‏قَالَ ‏ ‏أَبُو وَائِلٍ ‏ ‏وَصَدَقَ قَالَ فَكَانَتْ الْمَرْأَةُ وَالرَّجُلُ إِذَا بَعَثُوا وَافِدًا لَهُمْ قَالُوا لَا تَكُنْ كَوَافِدِ ‏ ‏عَادٍ ‏","","",""],[15389,15389,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي السَّلِيلِ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ الْهُجَيْمِيِّ ‏ ‏قَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏مَرَّةً ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ الْهُجَيْمِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ قَوْمِهِ ‏ ‏قَالَ ‏ ‏لَقِيتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏وَعَلَيْهِ ‏ ‏إِزَارٌ ‏ ‏مِنْ قُطْنٍ مُنْتَثِرُ ‏ ‏الْحَاشِيَةِ ‏ ‏فَقُلْتُ عَلَيْكَ السَّلَامُ يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏إِنَّ عَلَيْكَ السَّلَامَ تَحِيَّةُ الْمَوْتَى إِنَّ عَلَيْكَ السَّلَامَ تَحِيَّةُ الْمَوْتَى إِنَّ عَلَيْكَ السَّلَامَ تَحِيَّةُ الْمَوْتَى سَلَامٌ عَلَيْكُمْ سَلَامٌ عَلَيْكُمْ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا هَكَذَا ‏ ‏قَالَ سَأَلْتُ عَنْ ‏ ‏الْإِزَارِ ‏ ‏فَقُلْتُ أَيْنَ ‏ ‏أَتَّزِرُ ‏ ‏فَأَقْنَعَ ‏ ‏ظَهْرَهُ بِعَظْمِ سَاقِهِ وَقَالَ هَاهُنَا اتَّزِرْ فَإِنْ أَبَيْتَ فَهَاهُنَا أَسْفَلَ مِنْ ذَلِكَ فَإِنْ أَبَيْتَ فَهَاهُنَا فَوْقَ الْكَعْبَيْنِ فَإِنْ أَبَيْتَ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ قَالَ وَسَأَلْتُهُ ‏ ‏عَنْ الْمَعْرُوفِ فَقَالَ لَا تَحْقِرَنَّ مِنْ الْمَعْرُوفِ شَيْئًا وَلَوْ أَنْ تُعْطِيَ صِلَةَ الْحَبْلِ وَلَوْ أَنْ تُعْطِيَ ‏ ‏شِسْعَ ‏ ‏النَّعْلِ وَلَوْ أَنْ تَنْزِعَ مِنْ دَلْوِكَ فِي إِنَاءِ الْمُسْتَسْقِي وَلَوْ أَنْ تُنَحِّيَ الشَّيْءَ مِنْ طَرِيقِ النَّاسِ ‏ ‏يُؤْذِيهِمْ وَلَوْ أَنْ ‏ ‏تَلْقَى أَخَاكَ وَوَجْهُكَ إِلَيْهِ مُنْطَلِقٌ وَلَوْ أَنْ ‏ ‏تَلْقَى أَخَاكَ فَتُسَلِّمَ عَلَيْهِ وَلَوْ أَنْ تُؤْنِسَ الْوُحْشَانَ فِي الْأَرْضِ وَإِنْ سَبَّكَ رَجُلٌ بِشَيْءٍ يَعْلَمُهُ فِيكَ وَأَنْتَ تَعْلَمُ فِيهِ نَحْوَهُ فَلَا تَسُبَّهُ فَيَكُونَ أَجْرُهُ لَكَ وَوِزْرُهُ عَلَيْهِ وَمَا سَرَّ أُذُنَكَ أَنْ تَسْمَعَهُ فَاعْمَلْ بِهِ وَمَا سَاءَ أُذُنَكَ أَنْ تَسْمَعَهُ فَاجْتَنِبْهُ ‏","","",""],[15390,15390,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ صُحَارٍ الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى ‏ ‏يُخْسَفَ ‏ ‏بِقَبَائِلَ فَيُقَالُ مَنْ بَقِيَ مِنْ بَنِي فُلَانٍ قَالَ فَعَرَفْتُ حِينَ قَالَ قَبَائِلَ أَنَّهَا ‏ ‏الْعَرَبُ ‏ ‏لِأَنَّ ‏ ‏الْعَجَمَ ‏ ‏تُنْسَبُ إِلَى ‏ ‏قُرَاهَا ‏","","",""],[15391,15391,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الطَّيَالِسِيُّ ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ يَسَارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ صُحَارٍ الْعَبْدِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَأْذَنَ لِي فِي ‏ ‏جَرَّةٍ ‏ ‏أَنْتَبِذُ ‏ ‏فِيهَا فَرَخَّصَ لِي فِيهَا ‏ ‏أَوْ أَذِنَ لِي فِيهَا ‏","","",""],[15392,15392,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ يَعْنِي الثَّقَفِيَّ عَبْدَ اللَّهِ بْنَ عَقِيلٍ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ الْمُسَيَّبِ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏سَبْرَةَ بْنِ أَبِي فَاكِهٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الشَّيْطَانَ قَعَدَ لِابْنِ ‏ ‏آدَمَ ‏ ‏بِأَطْرُقِهِ فَقَعَدَ لَهُ بِطَرِيقِ الْإِسْلَامِ فَقَالَ لَهُ أَتُسْلِمُ وَتَذَرُ دِينَكَ وَدِينَ آبَائِكَ وَآبَاءِ أَبِيكَ قَالَ فَعَصَاهُ فَأَسْلَمَ ثُمَّ قَعَدَ لَهُ بِطَرِيقِ الْهِجْرَةِ فَقَالَ أَتُهَاجِرُ وَتَذَرُ أَرْضَكَ وَسَمَاءَكَ وَإِنَّمَا مَثَلُ الْمُهَاجِرِ كَمَثَلِ الْفَرَسِ فِي ‏ ‏الطِّوَلِ ‏ ‏قَالَ فَعَصَاهُ فَهَاجَرَ قَالَ ثُمَّ قَعَدَ لَهُ بِطَرِيقِ الْجِهَادِ فَقَالَ لَهُ هُوَ جَهْدُ النَّفْسِ وَالْمَالِ فَتُقَاتِلُ فَتُقْتَلُ فَتُنْكَحُ الْمَرْأَةُ وَيُقَسَّمُ الْمَالُ قَالَ فَعَصَاهُ فَجَاهَدَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَنْ فَعَلَ ذَلِكَ مِنْهُمْ فَمَاتَ كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُدْخِلَهُ الْجَنَّةَ أَوْ قُتِلَ كَانَ حَقًّا عَلَى اللَّهِ عَزَّ وَجَلَّ أَنْ يُدْخِلَهُ الْجَنَّةَ وَإِنْ غَرِقَ كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُدْخِلَهُ الْجَنَّةَ أَوْ ‏ ‏وَقَصَتْهُ ‏ ‏دَابَّتُهُ كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُدْخِلَهُ الْجَنَّةَ ‏","","",""],[15393,15393,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَرْقَمَ ‏ ‏أَنَّهُ حَجَّ فَكَانَ ‏ ‏يُصَلِّي بِأَصْحَابِهِ يُؤَذِّنُ وَيُقِيمُ فَأَقَامَ يَوْمًا الصَّلَاةَ وَقَالَ لِيُصَلِّ أَحَدُكُمْ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا أَرَادَ أَحَدُكُمْ أَنْ يَذْهَبَ إِلَى ‏ ‏الْخَلَاءِ ‏ ‏وَأُقِيمَتْ الصَّلَاةُ فَلْيَذْهَبْ إِلَى ‏ ‏الْخَلَاءِ ‏","","",""],[15394,15394,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ صَالِحٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبْدِ اللَّهِ بْنِ مَعْقِلِ بْنِ سِنَانٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نِيَارٍ الْأَسْلَمِيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شَأْسٍ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏وَكَانَ مِنْ أَصْحَابِ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ ‏ ‏عَلِيٍّ ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏فَجَفَانِي فِي سَفَرِي ذَلِكَ حَتَّى ‏ ‏وَجَدْتُ ‏ ‏فِي نَفْسِي عَلَيْهِ فَلَمَّا قَدِمْتُ أَظْهَرْتُ ‏ ‏شَكَايَتَهُ فِي الْمَسْجِدِ حَتَّى بَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلْتُ الْمَسْجِدَ ذَاتَ ‏ ‏غُدْوَةٍ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نَاسٍ مِنْ أَصْحَابِهِ فَلَمَّا رَآنِي أَمَدَّنِي عَيْنَيْهِ يَقُولُ حَدَّدَ إِلَيَّ النَّظَرَ حَتَّى إِذَا جَلَسْتُ قَالَ يَا ‏ ‏عَمْرُو ‏ ‏وَاللَّهِ لَقَدْ آذَيْتَنِي قُلْتُ أَعُوذُ بِاللَّهِ أَنْ أُوذِيَكَ يَا رَسُولَ اللَّهِ قَالَ بَلَى ‏ ‏مَنْ آذَى ‏ ‏عَلِيًّا ‏ ‏فَقَدْ آذَانِي ‏","","",""],[15395,15395,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُرَجَّى بْنُ رَجَاءٍ الْيَشْكُرِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَلْمُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَوَادَةَ بْنَ الرَّبِيعِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلْتُهُ فَأَمَرَ لِي ‏ ‏بِذَوْدٍ ‏ ‏ثُمَّ قَالَ لِي إِذَا رَجَعْتَ إِلَى بَيْتِكَ ‏ ‏فَمُرْهُمْ فَلْيُحْسِنُوا غِذَاءَ ‏ ‏رِبَاعِهِمْ ‏ ‏وَمُرْهُمْ فَلْيُقَلِّمُوا أَظْفَارَهُمْ وَلَا يَعْبِطُوا بِهَا ضُرُوعَ مَوَاشِيهِمْ إِذَا حَلَبُوا ‏","","",""],[15396,15396,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ هِنْدِ بْنِ أَسْمَاءَ الْأَسْلَمِيِّ ‏ ‏عَنْ ‏ ‏هِنْدِ بْنِ أَسْمَاءَ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى قَوْمِي مِنْ ‏ ‏أَسْلَمَ ‏ ‏فَقَالَ ‏ ‏مُرْ قَوْمَكَ فَلْيَصُومُوا هَذَا الْيَوْمَ ‏ ‏يَوْمَ ‏ ‏عَاشُورَاءَ ‏ ‏فَمَنْ وَجَدْتَهُ مِنْهُمْ قَدْ أَكَلَ فِي أَوَّلِ يَوْمِهِ فَلْيَصُمْ آخِرَهُ ‏","","",""],[15397,15397,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ هِنْدِ بْنِ حَارِثَةَ ‏ ‏وَكَانَ ‏ ‏هِنْدٌ ‏ ‏مِنْ أَصْحَابِ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏وَأَخُوهُ الَّذِي بَعَثَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُ قَوْمَهُ بِصِيَامِ ‏ ‏عَاشُورَاءَ ‏ ‏وَهُوَ ‏ ‏أَسْمَاءُ بْنُ حَارِثَةَ ‏ ‏فَحَدَّثَنِي ‏ ‏يَحْيَى بْنُ هِنْدٍ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بْنِ حَارِثَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ فَقَالَ ‏ ‏مُرْ قَوْمَكَ بِصِيَامِ هَذَا الْيَوْمِ قَالَ أَرَأَيْتَ إِنْ وَجَدْتُهُمْ قَدْ طَعِمُوا قَالَ فَلْيُتِمُّوا آخِرَ يَوْمِهِمْ ‏","","",""],[15398,15398,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ يَعْنِي ابْنَ عُرْوَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الْأَحْنَفِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَمٍّ لَهُ يُقَالُ لَهُ ‏ ‏جَارِيَةُ بْنُ قُدَامَةَ ‏ ‏أَنَّ رَجُلًا قَالَ لَهُ يَا رَسُولَ اللَّهِ قُلْ لِي قَوْلًا وَأَقْلِلْ عَلَيَّ لَعَلِّي أَعْقِلُهُ قَالَ ‏ ‏لَا تَغْضَبْ فَأَعَادَ عَلَيْهِ مِرَارًا كُلُّ ذَلِكَ يَقُولُ لَا تَغْضَبْ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏كَذَا ‏ ‏قَالَ ‏ ‏هِشَامٌ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ وَهُمْ يَقُولُونَ لَمْ يُدْرِكْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15399,15399,"","","‏ ‏حَدَّثَنَا ‏ ‏عِصَامُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ بْنِ أَبِي إِسْحَاقَ الْهَمْدَانِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏ذِي الْجَوْشَنِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ أَنْ فَرَغَ مِنْ أَهْلِ ‏ ‏بَدْرٍ ‏ ‏بِابْنِ فَرَسٍ لِي فَقُلْتُ يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنِّي قَدْ جِئْتُكَ بِابْنِ الْعَرْجَاءِ لِتَتَّخِذَهُ قَالَ ‏ ‏لَا حَاجَةَ لِي فِيهِ وَلَكِنْ إِنْ شِئْتَ أَنْ ‏ ‏أَقِيضَكَ ‏ ‏بِهِ ‏ ‏الْمُخْتَارَةَ ‏ ‏مِنْ دُرُوعِ ‏ ‏بَدْرٍ ‏ ‏فَقُلْتُ مَا كُنْتُ ‏ ‏لِأَقِيضَكَ ‏ ‏الْيَوْمَ بِعُدَّةٍ قَالَ فَلَا حَاجَةَ لِي فِيهِ ثُمَّ قَالَ يَا ‏ ‏ذَا الْجَوْشَنِ ‏ ‏أَلَا تُسْلِمُ فَتَكُونَ مِنْ أَوَّلِ هَذَا الْأَمْرِ قُلْتُ لَا قَالَ لِمَ قُلْتُ إِنِّي رَأَيْتُ قَوْمَكَ قَدْ ‏ ‏وَلِعُوا ‏ ‏بِكَ قَالَ فَكَيْفَ بَلَغَكَ عَنْ مَصَارِعِهِمْ ‏ ‏بِبَدْرٍ ‏ ‏قَالَ قُلْتُ بَلَغَنِي قَالَ قُلْتُ إِنْ تَغْلِبْ عَلَى ‏ ‏مَكَّةَ ‏ ‏وَتَقْطُنْهَا قَالَ لَعَلَّكَ إِنْ عِشْتَ أَنْ ‏ ‏تَرَى ذَلِكَ قَالَ ثُمَّ قَالَ يَا ‏ ‏بِلَالُ ‏ ‏خُذْ حَقِيبَةَ الرَّجُلِ فَزَوِّدْهُ مِنْ الْعَجْوَةِ فَلَمَّا أَنْ ‏ ‏أَدْبَرْتُ ‏ ‏قَالَ أَمَا إِنَّهُ مِنْ خَيْرِ ‏ ‏بَنِي عَامِرٍ ‏ ‏قَالَ فَوَاللَّهِ إِنِّي لَبِأَهْلِي ‏ ‏بِالْغَوْرِ ‏ ‏إِذْ أَقْبَلَ رَاكِبٌ فَقُلْتُ مِنْ أَيْنَ قَالَ مِنْ ‏ ‏مَكَّةَ ‏ ‏فَقُلْتُ مَا فَعَلَ النَّاسُ قَالَ قَدْ غَلَبَ عَلَيْهَا ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُلْتُ ‏ ‏هَبِلَتْنِي ‏ ‏أُمِّي فَوَاللَّهِ لَوْ أُسْلِمُ يَوْمَئِذٍ ثُمَّ أَسْأَلُهُ ‏ ‏الْحِيرَةَ ‏ ‏لَأَقْطَعَنِيهَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَالْحَكَمُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏ذِي الْجَوْشَنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبَّادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏ذِي الْجَوْشَنِ أَبِي شِمْرٍ الضِّبَابِيِّ ‏ ‏نَحْوَ هَذَا الْحَدِيثِ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏فَكَانَ ‏ ‏ابْنُ ذِي الْجَوْشَنِ ‏ ‏جَارًا ‏ ‏لِأَبِي إِسْحَاقَ ‏ ‏لَا أُرَاهُ إِلَّا سَمِعَهُ مِنْهُ ‏","","",""],[15400,15400,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏أَنَّهُ ‏ ‏طَبَخَ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِدْرًا فِيهِ لَحْمٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاوِلْنِي ذِرَاعَهَا فَنَاوَلْتُهُ فَقَالَ نَاوِلْنِي ذِرَاعَهَا فَنَاوَلْتُهُ فَقَالَ نَاوِلْنِي ذِرَاعَهَا فَقَالَ يَا نَبِيَّ اللَّهِ كَمْ لِلشَّاةِ مِنْ ذِرَاعٍ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَوْ سَكَتَّ لَأَعْطَتْكَ ذِرَاعًا مَا دَعَوْتَ بِهِ ‏","","",""]];
